def _default_disallowed_tools(allowed_tools: str) -> str:
    """Deny dangerous tools unless the profile explicitly allowed them."""
    allowed = {
        token.split("(", 1)[0]
        for token in re.split(r"[\s,]+", allowed_tools.strip())
        if token
    }
    return ",".join(tool for tool in ("Bash", "Write") if tool not in allowed)

def _log_stream_event(raw_line: str) -> None:
    raw_line = raw_line.strip()
    if not raw_line:
        return
    try:
        event = json.loads(raw_line)
    except json.JSONDecodeError:
        logger.info("Claude stream: %s", _truncate(raw_line, 500))
        return

    summary = _summarize_stream_event(event)
    if summary:
        logger.info("Claude stream: %s", summary)
    else:
        logger.debug("Claude stream event: %s", _truncate(raw_line, 1000))

def _resolve_bedrock_fable_model() -> str:
    """Resolve the Bedrock Fable model/inference profile used by Claude Code."""
    return (
        os.environ.get(_BEDROCK_FABLE_MODEL_ENV, "").strip()
        or _DEFAULT_BEDROCK_FABLE_MODEL
    )

def _resolve_bedrock_opus_model() -> str:
    """Resolve the Bedrock Opus model/inference profile used by Claude Code."""
    return (
        os.environ.get(_BEDROCK_OPUS_MODEL_ENV, "").strip()
        or _DEFAULT_BEDROCK_OPUS_MODEL
    )

def _resolve_claude_model(model: str | None) -> str | None:
    """Resolve the Claude Code model alias, honoring operator override."""
    override = os.environ.get(_CLAUDE_MODEL_ENV, "").strip()
    if override:
        return override
    return model or _DEFAULT_CLAUDE_MODEL

def _summarize_stream_event(event: dict[str, Any]) -> str:
    event_type = str(event.get("type") or event.get("event") or "")
    subtype = str(event.get("subtype") or "")

    if event_type == "system":
        session_id = event.get("session_id") or event.get("sessionId") or ""
        model = event.get("model") or ""
        cwd = event.get("cwd") or ""
        parts = ["system"]
        if subtype:
            parts.append(subtype)
        if model:
            parts.append(f"model={model}")
        if session_id:
            parts.append(f"session={session_id}")
        if cwd:
            parts.append(f"cwd={cwd}")
        return " ".join(parts)

    if event_type == "assistant":
        message = event.get("message")
        if not isinstance(message, dict):
            return "assistant event"
        content = message.get("content")
        summaries: list[str] = []
        if isinstance(content, list):
            for block in content:
                if not isinstance(block, dict):
                    continue
                block_type = block.get("type")
                if block_type == "text":
                    text = str(block.get("text") or "").strip()
                    if text:
                        summaries.append(f"text={_truncate(text, 240)}")
                elif block_type == "tool_use":
                    name = str(block.get("name") or "tool")
                    summaries.append(f"tool={name} {_summarize_tool_input(block.get('input'))}")
        return "assistant " + "; ".join(summaries) if summaries else "assistant event"

    if event_type == "user":
        message = event.get("message")
        if not isinstance(message, dict):
            return "user event"
        content = message.get("content")
        if isinstance(content, list):
            result_count = sum(
                1 for block in content
                if isinstance(block, dict) and block.get("type") == "tool_result"
            )
            if result_count:
                return f"tool_result count={result_count}"
        return "user event"

    if event_type == "result":
        duration = event.get("duration_ms")
        cost = event.get("total_cost_usd")
        turns = event.get("num_turns")
        result = str(event.get("result") or "").strip()
        parts = ["result"]
        if subtype:
            parts.append(subtype)
        if turns is not None:
            parts.append(f"turns={turns}")
        if duration is not None:
            parts.append(f"duration_ms={duration}")
        if cost is not None:
            parts.append(f"cost_usd={cost}")
        if result:
            parts.append(f"text={_truncate(result, 300)}")
        return " ".join(parts)

    return f"{event_type or 'unknown'} event"

def _summarize_tool_input(tool_input: Any) -> str:
    if not isinstance(tool_input, dict):
        return ""
    for key in ("file_path", "path", "pattern", "command"):
        value = tool_input.get(key)
        if isinstance(value, str) and value:
            return f"{key}={_truncate(value, 180)}"
    return _truncate(json.dumps(tool_input, sort_keys=True, default=str), 180)

def _truncate(text: str, limit: int) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 1)] + "…"

def _write_evidence(
    result: AgentRunResult,
    profile: AgentProfile,
    evidence_dir: str | Path | None,
) -> None:
    configured_dir = evidence_dir or os.environ.get("CI_AGENT_EVIDENCE_DIR", "")
    if not configured_dir and os.environ.get("GITHUB_ACTIONS", "").lower() == "true":
        configured_dir = "agent-evidence"
    if not configured_dir:
        return
    target_dir = Path(configured_dir)
    try:
        target_dir.mkdir(parents=True, exist_ok=True)
        evidence = {
            "profile": asdict(profile),
            "result": {key: value for key, value in asdict(result).items() if key not in {"stdout", "stderr"}},
            "stdout_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
            "stderr_sha256": hashlib.sha256(result.stderr.encode("utf-8")).hexdigest(),
        }
        path = target_dir / (
            f"{result.started_at.replace(':', '').replace('+', 'Z')}-{result.profile}-{result.prompt_sha256[:12]}.json"
        )
        path.write_text(json.dumps(evidence, indent=2, sort_keys=True), encoding="utf-8")
    except OSError:
        return

def _append_detail(parts: list[str], detail: str) -> None:
    if detail and detail not in parts:
        parts.append(detail)

def _empty_skip_reason(
    conflicting_files: list[ConflictedFile],
    resolutions: list[ResolutionResult],
) -> str:
    """A deterministic reason a resolved cherry-pick produced no net change.

    Derived only from provable facts, never from the resolver's prose. When the
    resolution of every conflicted file matched the target branch's existing
    content, the source PR's change does not apply on this branch (the code it
    modifies differs or is absent here), so the cherry-pick is a no-op.
    """
    target_by_path = {cf.path: cf.target_branch_content for cf in conflicting_files}
    matched_target = [
        r.path
        for r in resolutions
        if r.resolved_content is not None and r.path in target_by_path and r.resolved_content == target_by_path[r.path]
    ]
    if matched_target and len(matched_target) == len([r for r in resolutions if r.resolved_content is not None]):
        return (
            "The change does not apply to this branch: resolving the conflict "
            "matched the existing code, so the cherry-pick added nothing."
        )
    return "The cherry-pick produced no net change on this branch, so there is nothing to backport."

def _has_llm_resolutions(resolutions: list[ResolutionResult]) -> bool:
    return any(
        resolution.resolved_content is not None
        and resolution.source == "llm"
        for resolution in resolutions
    )

def _is_empty_cherry_pick(result: subprocess.CompletedProcess[str]) -> bool:
    output = f"{result.stdout}\n{result.stderr}".lower()
    return any(
        marker in output
        for marker in (
            "cherry-pick is now empty",
            "previous cherry-pick is now empty",
            "nothing to commit",
            "patch is empty",
        )
    )

def _safe_restore_path(root: Path, relative_path: str) -> Path:
    normalized = Path(*relative_path.replace("\\", "/").split("/"))
    if normalized.is_absolute() or ".." in normalized.parts:
        raise RuntimeError(f"unsafe worktree path: {relative_path}")
    root = root.resolve()
    current = root
    for part in normalized.parts[:-1]:
        current = current / part
        if current.is_symlink():
            raise RuntimeError(f"symlinked worktree parent: {relative_path}")
    destination = root / normalized
    if destination.is_symlink():
        destination.unlink()
    return destination

def _snapshot_untracked_files(
    repo_dir: str,
    paths: tuple[str, ...],
) -> dict[str, bytes]:
    snapshots: dict[str, bytes] = {}
    root = Path(repo_dir).resolve()
    for path in paths:
        if Path(root, path).is_symlink():
            continue
        candidate = _safe_restore_path(root, path)
        if not candidate.is_file():
            continue
        snapshots[path] = candidate.read_bytes()
    return snapshots

def _agent_result_text(stdout: str) -> str:
    """Extract Claude Code's final result text from its JSONL stream."""
    result_text = ""
    for line in stdout.strip().splitlines():
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, TypeError):
            continue
        if event.get("type") != "result" or "result" not in event:
            continue
        raw_result = event.get("result")
        if isinstance(raw_result, str):
            result_text = raw_result
        elif raw_result is not None:
            result_text = json.dumps(raw_result, sort_keys=True, default=str)
    return result_text.strip()

def _file_hash(path: str) -> str:
    """SHA-256 of file content, or empty string if unreadable."""
    try:
        return hashlib.sha256(Path(path).read_bytes()).hexdigest()
    except OSError:
        return ""

def _read_text(path: str) -> str:
    """Return file content as text, or empty string if unreadable."""
    try:
        return Path(path).read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""

def _unexpected_modified_paths(
    repo_dir: str,
    *,
    pre_changed_paths: set[str],
    protected_pre_hashes: dict[str, str],
    allowed_paths: set[str],
) -> list[str]:
    """Return any paths Claude touched that weren't in the allowed conflict set."""
    post_changed_paths = _git_changed_paths(repo_dir)
    unexpected = [
        p for p in post_changed_paths
        if p not in pre_changed_paths and p not in allowed_paths
    ]
    for path, pre_hash in protected_pre_hashes.items():
        if _file_hash(os.path.join(repo_dir, path)) != pre_hash:
            unexpected.append(path)
    return sorted(set(unexpected))

def _unresolved(files: list[ConflictedFile], summary: str) -> list[ResolutionResult]:
    """Mark every file in *files* as unresolved with the same summary."""
    return [
        ResolutionResult(path=cf.path, resolved_content=None, resolution_summary=summary)
        for cf in files
    ]

@dataclass(frozen=True)
class DiffCommentMarker:
    source_pr: int
    sha: str
    # Present only for legacy per-file comments. New grouped comments use None.
    path: str | None = None

def _comment_author(comment: Any) -> str | None:
    user = getattr(comment, "user", None)
    return getattr(user, "login", None) if user is not None else None

def _comment_sha(body: str) -> str | None:
    parsed = parse_marker(body)
    return parsed.sha if parsed else None

def _commentable_results(results: list[ResolutionResult]) -> list[ResolutionResult]:
    return [
        result for result in results
        if result.resolved_content is not None
        and (result.reviewer_diff or result.resolution_diff)
    ]

def _commit_file_url(repo_html_url: str, commit_sha: str, path: str) -> str | None:
    """Link to *path* within the resolution commit's native diff view."""
    if not repo_html_url or not commit_sha:
        return None
    digest = hashlib.sha256(path.encode("utf-8")).hexdigest()
    return f"{repo_html_url}/commit/{commit_sha}#diff-{digest}"

def _create_comment(pr: Any, body: str) -> Any:
    return retry_github_call(
        lambda: pr.create_issue_comment(body),
        retries=3,
        description="post AI-diff comment",
    )

def _delete_comment(comment: Any) -> None:
    retry_github_call(
        lambda: comment.delete(), retries=3, description="delete AI-diff comment",
    )

def _edit_comment(comment: Any, body: str) -> None:
    retry_github_call(
        lambda: comment.edit(body), retries=3, description="edit AI-diff comment",
    )

def _files_changed_url(pr_html_url: str, path: str) -> str | None:
    """Return a link to *path* in the PR's Files changed tab."""
    if not pr_html_url:
        return None
    digest = hashlib.sha256(path.encode("utf-8")).hexdigest()
    return f"{pr_html_url}/files#diff-{digest}"

def _owned_marked_comments(
    comments: list[Any],
    source_pr: int,
    *,
    bot_login: str | None,
) -> list[Any]:
    owned: list[Any] = []
    for comment in comments:
        parsed = parse_marker(getattr(comment, "body", "") or "")
        if parsed is None or parsed.source_pr != source_pr:
            continue
        if bot_login is not None and _comment_author(comment) != bot_login:
            continue
        owned.append(comment)
    return owned

def _payload_sha(payload: str) -> str:
    """Stable short hash of the exact rendered comment body reviewers see."""
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16]

def _safe_text(value: str, *, limit: int | None = None) -> str:
    text = " ".join(value.replace("\r\n", "\n").replace("\r", "\n").split())
    if limit is not None and len(text) > limit:
        text = text[:limit].rstrip() + "..."
    return html.escape(text, quote=False)

def _summary_block(results: list[ResolutionResult]) -> str:
    summary = next((r.llm_summary for r in results if r.llm_summary), None)
    if not summary:
        return ""
    text = summary.strip()
    if len(text) > _MAX_SUMMARY_CHARS:
        text = text[:_MAX_SUMMARY_CHARS].rstrip() + "\n... summary truncated."
    quoted = "\n".join(f"> {html.escape(line, quote=False)}" for line in text.splitlines())
    return f"**Claude Summary**\n\n{quoted}\n\n"

def list_marked_source_prs(pr: Any, *, bot_login: str | None = None) -> set[int]:
    """Return source PR numbers that have AI-diff comments on *pr*."""
    return set(marked_source_pr_urls(pr, bot_login=bot_login))

def marked_source_pr_urls(pr: Any, *, bot_login: str | None = None) -> dict[int, str]:
    """Return source PR numbers mapped to their marked comment URLs on *pr*.

    If both legacy per-file comments and a grouped comment exist for the same
    source PR, prefer the grouped comment URL because that is the canonical
    destination after migration.
    """
    existing = retry_github_call(
        lambda: list(pr.get_issue_comments()),
        retries=3,
        description="list PR comments for AI-diff source-PR scan",
    )
    found: dict[int, str] = {}
    for comment in existing:
        parsed = parse_marker(getattr(comment, "body", "") or "")
        if parsed is None:
            continue
        if bot_login is not None and _comment_author(comment) != bot_login:
            continue
        url = getattr(comment, "html_url", None)
        if not url:
            continue
        if parsed.source_pr not in found or parsed.path is None:
            found[parsed.source_pr] = url
    return found

def parse_marker(body: str) -> DiffCommentMarker | None:
    """Return marker data for a marked comment, else ``None``."""
    match = _MARKER_RE.search(body)
    if not match:
        return None
    path = match.group("path")
    return DiffCommentMarker(
        source_pr=int(match.group("source_pr")),
        sha=match.group("sha"),
        path=html.unescape(path) if path is not None else None,
    )

def has_staged_changes(
    repo_dir: str,
    *,
    run_process: RunProcess = subprocess.run,
) -> bool:
    result = run_process(
        ["git", "diff", "--cached", "--quiet"],
        cwd=repo_dir,
        capture_output=True,
        text=True,
    )
    if result.returncode == 0:
        return False
    if result.returncode == 1:
        return True
    raise RuntimeError(
        "could not inspect staged changes: "
        + ((result.stderr or "").strip()[:300] or "git diff failed")
    )

def head_sha(
    repo_dir: str,
    *,
    run_process: RunProcess = subprocess.run,
) -> str:
    """Return the commit currently checked out in *repo_dir*."""
    result = run_process(
        ["git", "rev-parse", "HEAD"],
        cwd=repo_dir,
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(
            "could not resolve candidate start: "
            + ((result.stderr or "").strip()[:300] or "git rev-parse failed")
        )
    return result.stdout.strip()

def index_stage_exists(
    repo_dir: str,
    path: str,
    stage: int,
    *,
    run_process: RunProcess = subprocess.run,
) -> bool:
    result = run_process(
        ["git", "cat-file", "-e", f":{stage}:{path}"],
        cwd=repo_dir,
        capture_output=True,
        text=True,
    )
    if result.returncode == 0:
        return True
    error = (result.stderr or "").strip().lower()
    if result.returncode == 1 or any(
        marker in error
        for marker in (
            "but not at stage",
            "does not exist",
        )
    ):
        return False
    raise RuntimeError(
        f"could not inspect index stage {stage} of {path}: "
        + (error[:300] or "git cat-file failed")
    )

def _post_comment(repo: object, pr_number: int, body: str) -> None:
    """Post a comment on a pull request (best-effort)."""
    try:
        pr = retry_github_call(
            lambda: repo.get_pull(pr_number),  # type: ignore[attr-defined]
            retries=3,
            description=f"get PR #{pr_number} for comment",
        )
        retry_github_call(
            lambda: pr.create_issue_comment(body),
            retries=3,
            description=f"post comment on PR #{pr_number}",
        )
        logger.info("Posted comment on PR #%d.", pr_number)
    except Exception as exc:
        logger.warning("Failed to post comment on PR #%d: %s", pr_number, exc)

def _skipped_existing_message(
    result: CandidateResult,
    target_branch: str,
) -> str:
    """Describe why a skipped candidate does not need a backport PR."""

    if result.detail == DETAIL_EMPTY_ON_TARGET:
        reason = (
            result.skip_reason
            or "The change produces no net change on this branch."
        )
        return (
            f"Source PR #{result.source_pr_number} does not require a "
            f"backport to `{target_branch}`; no backport PR was "
            f"created. {reason}"
        )
    return (
        f"Source PR #{result.source_pr_number} is already applied to "
        f"`{target_branch}`; no backport PR was created."
    )

def as_dict(self) -> dict[str, Any]:
    return {
        "requested": self.requested,
        "updated": self.updated,
        "already_done": self.already_done,
        "missing": self.missing,
        "skipped": {str(k): v for k, v in sorted(self.skipped.items())},
        "unverified": self.unverified,
    }

def _branch_commit_subjects(repo_dir: str) -> list[str]:
    result = subprocess.run(
        ["git", "log", "--format=%s", "HEAD"],
        cwd=repo_dir,
        capture_output=True,
        text=True,
        check=True,
    )
    return result.stdout.splitlines()

def _find_status_field_and_option(
    fields: list[dict[str, Any]],
    *,
    status_field: str,
    done_status: str,
) -> tuple[str, str]:
    for field_node in fields:
        if (
            field_node.get("__typename") != "ProjectV2SingleSelectField"
            or _normalize(field_node.get("name")) != _normalize(status_field)
        ):
            continue
        field_id = str(field_node.get("id") or "")
        for option in field_node.get("options") or []:
            if _normalize(option.get("name")) == _normalize(done_status):
                option_id = str(option.get("id") or "")
                if field_id and option_id:
                    return field_id, option_id
        raise RuntimeError(
            f"Project status field {status_field!r} has no {done_status!r} option"
        )
    raise RuntimeError(f"Project has no single-select status field {status_field!r}")

def _item_single_select_value(item: dict[str, Any], field_name: str) -> str:
    for field_value in (item.get("fieldValues") or {}).get("nodes") or []:
        if field_value.get("__typename") != "ProjectV2ItemFieldSingleSelectValue":
            continue
        if _normalize((field_value.get("field") or {}).get("name")) == _normalize(field_name):
            return str(field_value.get("name") or "")
    return ""

def _load_project(
    gql: GitHubGraphQLClient,
    *,
    project_owner: str,
    project_number: int,
    project_owner_type: str,
) -> dict[str, Any]:
    owner_field = "user" if project_owner_type == "user" else "organization"
    query = _project_query(owner_field)
    cursor = None
    project_id = ""
    fields: list[dict[str, Any]] = []
    items: list[dict[str, Any]] = []

    while True:
        data = gql.execute(
            query,
            {"owner": project_owner, "number": project_number, "cursor": cursor},
        )
        project = (data.get(owner_field) or {}).get("projectV2")
        if not project:
            raise RuntimeError(f"Project {project_owner}/{project_number} not found")

        project_id = project_id or str(project.get("id") or "")
        if not fields:
            fields = (project.get("fields") or {}).get("nodes") or []

        page = project.get("items") or {}
        items.extend(page.get("nodes") or [])
        page_info = page.get("pageInfo") or {}
        if not page_info.get("hasNextPage"):
            break
        cursor = page_info.get("endCursor")

    if not project_id:
        raise RuntimeError(f"Project {project_owner}/{project_number} has no id")
    return {"id": project_id, "fields": fields, "items": items}

def _markdown_section(body: str, heading: str) -> str:
    pattern = re.compile(
        rf"(?ims)^##\s+{re.escape(heading)}\s*$([\s\S]*?)(?=^##\s+|\Z)"
    )
    match = pattern.search(body)
    return match.group(1) if match else ""

def _pr_numbers_from_table_cells(markdown: str) -> set[int]:
    """Source PR numbers from the ``Source PR`` column of a markdown table.

    Only the ``Source PR`` column is read, so a ``#N`` appearing in a Title or
    Detail cell (e.g. a revert subject, or a "depends on #N" note) is never
    counted. Cells whose text wraps across newlines are reassembled first: a
    logical row begins at a line starting with ``|`` and absorbs the lines that
    follow until the next row. When no ``Source PR`` header is present the first
    column is used, since the sweep always lists the source PR first.
    """
    rows: list[str] = []
    for line in markdown.splitlines():
        if line.lstrip().startswith("|"):
            rows.append(line)
        elif rows:
            rows[-1] += " " + line.strip()

    pr_cell = re.compile(r"^(?:\[)?#(\d+)(?:\]\([^)]*\))?$")
    column: int | None = None
    numbers: set[int] = set()
    for row in rows:
        cells = [cell.strip() for cell in row.strip().strip("|").split("|")]
        if column is None:
            for index, cell in enumerate(cells):
                if _normalize(cell) == "source pr":
                    column = index
                    break
            else:
                column = 0  # no header row; sweep lists the source PR first
            if any(_normalize(cell) == "source pr" for cell in cells):
                continue  # consumed the header row itself
        if all(set(cell) <= set("-: ") for cell in cells if cell):
            continue  # separator row (|---|---|)
        if column < len(cells):
            match = pr_cell.match(cells[column])
            if match:
                numbers.add(int(match.group(1)))
    return numbers

def _project_query(owner_field: str) -> str:
    return f"""
query($owner: String!, $number: Int!, $cursor: String) {{
  {owner_field}(login: $owner) {{
    projectV2(number: $number) {{
      id
      fields(first: 100) {{
        nodes {{
          __typename
          ... on ProjectV2SingleSelectField {{
            id
            name
            options {{ id name }}
          }}
        }}
      }}
      items(first: 100, after: $cursor) {{
        pageInfo {{ hasNextPage endCursor }}
        nodes {{
          id
          content {{
            __typename
            ... on PullRequest {{
              number
              repository {{ nameWithOwner }}
            }}
          }}
          fieldValues(first: 50) {{
            nodes {{
              __typename
              ... on ProjectV2ItemFieldSingleSelectValue {{
                name
                field {{ ... on ProjectV2FieldCommon {{ name }} }}
              }}
            }}
          }}
        }}
      }}
    }}
  }}
}}
"""

def _set_project_item_status(
    gql: GitHubGraphQLClient,
    *,
    project_id: str,
    item_id: str,
    field_id: str,
    option_id: str,
) -> None:
    mutation = """
mutation($projectId: ID!, $itemId: ID!, $fieldId: ID!, $optionId: String!) {
  updateProjectV2ItemFieldValue(input: {
    projectId: $projectId
    itemId: $itemId
    fieldId: $fieldId
    value: { singleSelectOptionId: $optionId }
  }) {
    projectV2Item { id }
  }
}
"""
    gql.execute(
        mutation,
        {
            "projectId": project_id,
            "itemId": item_id,
            "fieldId": field_id,
            "optionId": option_id,
        },
    )

@dataclass(frozen=True)
class FileSnapshot:
    state: str
    digest: str = ""
    content: bytes | None = None

@dataclass
class MissingTestAdaptationResult:
    adapted_paths: list[str] = field(default_factory=list)
    summary: str = ""
    fatal: bool = False

def adapt_target_missing_tests_with_claude(
    repo_dir: str,
    candidate: BackportCandidate,
    missing_test_sources: dict[str, str],
    *,
    language: str,
    test_path_patterns: tuple[str, ...] | list[str] | None = None,
    run_git: RunGit = run_git_default,
    run_process: RunProcess = subprocess.run,
    run_agent_func: RunAgent = run_agent,
) -> MissingTestAdaptationResult:
    existing_test_paths = set(
        list_existing_test_paths(
            repo_dir,
            limit=None,
            test_path_patterns=test_path_patterns,
            run_process=run_process,
        )
    )
    prompt = build_test_adaptation_prompt(
        repo_dir,
        candidate,
        missing_test_sources,
        language=language,
        test_path_patterns=test_path_patterns,
        run_process=run_process,
    )

    try:
        with tempfile.TemporaryDirectory(
            prefix="valkey-test-adaptation-",
        ) as temp_dir:
            sandbox_dir = Path(temp_dir, "repo")
            copy_worktree_for_adaptation(repo_dir, sandbox_dir)
            sandbox_before = snapshot_regular_files(sandbox_dir)

            logger.info(
                "Calling Claude Code to adapt %d target-missing test file(s) "
                "for PR #%d onto %s...",
                len(missing_test_sources),
                candidate.source_pr_number,
                candidate.target_branch,
            )
            agent_result = run_agent_func(
                "test_adaptation_edit_only",
                prompt,
                cwd=str(sandbox_dir),
            )
            result_text = extract_agent_result_text(agent_result)
            logger.info(
                "Claude Code test adaptation finished (rc=%d). Result: %s",
                agent_result.returncode,
                result_text[:200] if result_text else "(no result text)",
            )

            sandbox_after = snapshot_regular_files(sandbox_dir)
            changed_paths = changed_snapshot_paths(
                sandbox_before,
                sandbox_after,
            )
            if agent_result.returncode != 0:
                detail = (
                    agent_result.stderr
                    or result_text
                    or "Claude Code returned non-zero"
                )
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation not applied: Claude Code failed: "
                        f"{detail[:200]}"
                    ),
                    fatal=True,
                )
            if not changed_paths:
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation not applied: no branch-native "
                        "test changes"
                    ),
                )

            removed_paths = [
                path
                for path in changed_paths
                if path in sandbox_before
                and not Path(sandbox_dir, path).exists()
                and not Path(sandbox_dir, path).is_symlink()
            ]
            if removed_paths:
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation not applied: removed existing test "
                        "path(s): " + ", ".join(removed_paths[:10])
                    ),
                    fatal=True,
                )

            invalid_paths = invalid_sandbox_test_paths(
                sandbox_dir,
                changed_paths,
                sandbox_before=sandbox_before,
                existing_test_paths=existing_test_paths,
                test_path_patterns=test_path_patterns,
            )
            if invalid_paths:
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation not applied: invalid generated "
                        "test path(s): " + ", ".join(invalid_paths[:10])
                    ),
                    fatal=True,
                )

            unsafe_destination_paths = [
                path
                for path in changed_paths
                if safe_regular_file(Path(repo_dir), path) is None
            ]
            if unsafe_destination_paths:
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation not applied: unsafe repository "
                        "test path(s): "
                        + ", ".join(unsafe_destination_paths[:10])
                    ),
                    fatal=True,
                )

            import_snapshots = {
                path: snapshot_path(
                    Path(repo_dir, path), include_content=True
                )
                for path in changed_paths
            }
            import_index_entries = index_entries_for_paths(
                repo_dir,
                set(changed_paths),
                run_process=run_process,
            )
            try:
                for path in changed_paths:
                    source = safe_regular_file(sandbox_dir, path)
                    destination = safe_regular_file(Path(repo_dir), path)
                    if source is None or destination is None:
                        raise RuntimeError(f"unsafe test adaptation path: {path}")
                    destination.write_bytes(source.read_bytes())
                    run_git(repo_dir, "add", path)
            except Exception as exc:  # noqa: BLE001
                restore_paths(
                    repo_dir,
                    import_snapshots,
                    index_entries=import_index_entries,
                    run_git=run_git,
                    run_process=run_process,
                )
                return MissingTestAdaptationResult(
                    summary=(
                        "test adaptation import failed: "
                        f"{str(exc)[:200]}"
                    ),
                    fatal=True,
                )

            return MissingTestAdaptationResult(
                adapted_paths=changed_paths,
                summary=(
                    f"{DETAIL_PORTED_TARGET_MISSING_TEST_PREFIX} "
                    + ", ".join(changed_paths)
                ),
            )
    except Exception as exc:  # noqa: BLE001
        return MissingTestAdaptationResult(
            summary=f"test adaptation failed unexpectedly: {str(exc)[:200]}",
            fatal=True,
        )

def build_missing_test_context(
    repo_dir: str,
    path: str,
    source_content: str,
    *,
    run_process: RunProcess = subprocess.run,
) -> str:
    if index_stage_exists(repo_dir, path, 1, run_process=run_process):
        base_content = read_index_stage(
            repo_dir,
            path,
            1,
            run_process=run_process,
        )
        diff = "".join(
            difflib.unified_diff(
                base_content.splitlines(keepends=True),
                source_content.splitlines(keepends=True),
                fromfile=f"a/{path}",
                tofile=f"b/{path}",
            )
        )
        return "Changed upstream test hunk:\n" + (
            diff or "(no textual diff)"
        )
    return "Full upstream test content for a new missing test file:\n" + source_content

def changed_snapshot_paths(
    before: dict[str, FileSnapshot],
    after: dict[str, FileSnapshot],
) -> list[str]:
    return sorted(
        path
        for path in set(before) | set(after)
        if before.get(path) != after.get(path)
    )

def extract_agent_result_text(agent_result: AgentRunResult) -> str:
    result_text = ""
    for line in agent_result.stdout.strip().splitlines():
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, TypeError):
            continue
        if event.get("type") != "result" or "result" not in event:
            continue
        raw_result = event.get("result")
        if isinstance(raw_result, str):
            result_text = raw_result
        elif raw_result is not None:
            result_text = json.dumps(
                raw_result,
                sort_keys=True,
                default=str,
            )
    return result_text

def index_entries_for_paths(
    repo_dir: str,
    paths: set[str],
    *,
    run_process: RunProcess = subprocess.run,
) -> dict[str, tuple[str, ...]]:
    entries: dict[str, tuple[str, ...]] = {}
    for path in sorted(paths):
        result = run_process(
            ["git", "ls-files", "--stage", "--", path],
            cwd=repo_dir,
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            raise RuntimeError(
                f"could not inspect index entry for {path}: "
                + (
                    (result.stderr or "").strip()[:300]
                    or "git ls-files failed"
                )
            )
        entries[path] = tuple(
            line for line in result.stdout.splitlines() if line
        )
    return entries

def is_test_path(
    path: str,
    test_path_patterns: tuple[str, ...] | list[str] | None = None,
) -> bool:
    normalized = path.replace("\\", "/").strip("/").lower()
    patterns = test_path_patterns or DEFAULT_TEST_PATH_PATTERNS
    return any(
        fnmatch.fnmatchcase(normalized, pattern.replace("\\", "/").lower())
        for pattern in patterns
    )

def list_existing_test_paths(
    repo_dir: str,
    *,
    limit: int | None = MAX_EXISTING_TEST_PATHS,
    test_path_patterns: tuple[str, ...] | list[str] | None = None,
    run_process: RunProcess = subprocess.run,
) -> list[str]:
    result = run_process(
        ["git", "ls-files"],
        cwd=repo_dir,
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        return []
    paths = [
        line.strip()
        for line in result.stdout.splitlines()
        if line.strip() and is_test_path(line.strip(), test_path_patterns)
    ]
    return paths if limit is None else paths[:limit]

def restore_index_entries(
    repo_dir: str,
    entries_by_path: dict[str, tuple[str, ...]],
    *,
    run_git: RunGit = run_git_default,
    run_process: RunProcess = subprocess.run,
) -> None:
    for path, entries in entries_by_path.items():
        current_entries = index_entries_for_paths(
            repo_dir,
            {path},
            run_process=run_process,
        ).get(path, ())
        if current_entries:
            run_git(repo_dir, "reset", "-q", "HEAD", "--", path)
        if not entries:
            continue
        result = run_process(
            ["git", "update-index", "--index-info"],
            cwd=repo_dir,
            input="\n".join(entries) + "\n",
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            raise RuntimeError(
                f"could not restore index entry for {path}: "
                + (
                    (result.stderr or "").strip()[:300]
                    or "git update-index failed"
                )
            )

def restore_paths(
    repo_dir: str,
    snapshots: dict[str, FileSnapshot],
    *,
    index_entries: dict[str, tuple[str, ...]],
    run_git: RunGit = run_git_default,
    run_process: RunProcess = subprocess.run,
) -> None:
    for path, snapshot in snapshots.items():
        file_path = Path(repo_dir, path)
        if snapshot.state == "file" and snapshot.content is not None:
            file_path.parent.mkdir(parents=True, exist_ok=True)
            file_path.write_bytes(snapshot.content)
        elif snapshot.state == "absent" and file_path.exists():
            if file_path.is_dir():
                shutil.rmtree(file_path)
            else:
                file_path.unlink()
    restore_index_entries(
        repo_dir,
        index_entries,
        run_git=run_git,
        run_process=run_process,
    )

def safe_regular_file(root: Path, relative_path: str) -> Path | None:
    """Return a non-symlink regular file contained by *root*, or ``None``."""
    normalized = Path(*relative_path.replace("\\", "/").split("/"))
    if normalized.is_absolute() or ".." in normalized.parts:
        return None
    candidate = root / normalized
    current = root
    for part in normalized.parts:
        current = current / part
        if current.is_symlink():
            return None
    try:
        resolved = candidate.resolve(strict=True)
        resolved.relative_to(root.resolve(strict=True))
    except (OSError, ValueError):
        return None
    return candidate if candidate.is_file() else None

def snapshot_path(path: Path, *, include_content: bool = False) -> FileSnapshot:
    """Snapshot a path for change detection or restoration.

    Change detection across a whole worktree only needs a digest, so file
    contents are hashed in chunks instead of being buffered in memory.
    ``include_content`` additionally captures the bytes; it is meant for the
    small set of paths that ``restore_paths`` may need to write back.
    """
    if not path.exists():
        return FileSnapshot("absent")
    if not path.is_file():
        return FileSnapshot("special")
    try:
        if include_content:
            content = path.read_bytes()
            return FileSnapshot(
                "file",
                hashlib.sha256(content).hexdigest(),
                content,
            )
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1 << 20), b""):
                digest.update(chunk)
        return FileSnapshot("file", digest.hexdigest())
    except OSError:
        return FileSnapshot("unreadable")

def snapshot_regular_files(root: Path) -> dict[str, FileSnapshot]:
    snapshots: dict[str, FileSnapshot] = {}
    for path in root.rglob("*"):
        if not path.is_symlink() and path.is_file():
            snapshots[path.relative_to(root).as_posix()] = snapshot_path(path)
    return snapshots

def to_pr_context(self) -> BackportPRContext:
    """Return the resolver and PR-publication view of this candidate."""

    return BackportPRContext(
        source_pr_number=self.source_pr_number,
        source_pr_title=self.source_pr_title,
        source_pr_url=self.source_pr_url,
        source_pr_diff=self.source_pr_diff,
        target_branch=self.target_branch,
        commits=list(self.commit_shas),
    )

@dataclass
class BackportConfig:
    """Configuration for the backport agent, derived from the registry."""

    backport_label: str = "backport"
    llm_conflict_label: str = "ai-resolved-conflicts"
    max_conflicting_files: int = 100

@dataclass
class ConflictedFile:
    """A file with merge conflict markers after cherry-pick."""

    path: str
    target_branch_content: str
    source_branch_content: str

def _ensure_label_exists(self, repo: Any, label: str) -> None:
    """Create *label* on *repo* if it does not already exist.

    Best-effort: a failure here is logged and swallowed so the PR
    creation flow continues. The subsequent ``add_to_labels`` call
    will surface the same problem if it persists.
    """
    try:
        retry_github_call(
            lambda: repo.get_label(label),
            retries=3,
            description=f"check label {label!r}",
        )
        return
    except GithubException as exc:
        if exc.status != 404:
            logger.warning(
                "Could not verify label %r on %s: %s",
                label, self._base_repo, exc,
            )
            return
    except Exception as exc:
        # Best-effort: a transport/parse failure must not abort PR creation.
        logger.warning(
            "Could not verify label %r on %s: %s",
            label, self._base_repo, exc,
        )
        return

    color, description = _LABEL_DEFAULTS.get(
        label, ("ededed", f"Created by valkey-ci-agent for label {label!r}"),
    )
    try:
        logger.info("Creating missing label %r on %s", label, self._base_repo)
        retry_github_call(
            lambda: repo.create_label(
                name=label, color=color, description=description,
            ),
            retries=3,
            description=f"create label {label!r}",
        )
    except GithubException as exc:
        # 422 means the label was created concurrently — fine.
        if exc.status == 422:
            return
        logger.error(
            "Failed to create label %r on %s: %s",
            label, self._base_repo, exc,
        )
    except Exception as exc:
        # Best-effort: a transport/parse failure must not abort PR creation.
        logger.error(
            "Failed to create label %r on %s: %s",
            label, self._base_repo, exc,
        )

@staticmethod
def build_pr_body(
    context: BackportPRContext,
    had_conflicts: bool,
    resolution_results: list[ResolutionResult] | None,
    *,
    applied_commits: list[str] | None = None,
    comment_links: dict[str, str] | None = None,
    ai_involved: bool = False,
    ai_summary: str = "",
) -> str:
    """Build the PR body with links, commit list, conflict info.

    *comment_links* maps a resolved file path to the URL of its AI-diff
    comment. When provided, each resolved file's status line links to its
    comment. The body is built once before comments exist (no links), then
    rebuilt after reconcile with the links filled in.
    """
    links = comment_links or {}
    sections: list[str] = []
    results = resolution_results or []
    resolved_count = sum(result.resolved_content is not None for result in results)
    unresolved_count = len(results) - resolved_count
    any_ai_changes = ai_involved or bool(
        results and any(_was_llm_resolved(result) for result in results)
    )

    if had_conflicts:
        if unresolved_count > 0:
            verdict = (
                "Cherry-pick encountered conflicts and some files still need "
                "manual follow-up."
            )
        elif resolved_count > 0:
            verdict = (
                "Cherry-pick encountered conflicts and the conflicted files were "
                "resolved automatically."
            )
        else:
            verdict = "Cherry-pick encountered conflicts."
    else:
        verdict = "Cherry-pick applied cleanly with no conflicts."

    sections.append("## Backport Summary\n\n" + verdict)
    sections.append(
        "\n".join([
            "| Field | Value |",
            "|---|---|",
            f"| Source PR | [#{context.source_pr_number}]({context.source_pr_url}) |",
            f"| Source title | {_escape_table_cell(context.source_pr_title)} |",
            f"| Target branch | `{context.target_branch}` |",
            f"| Cherry-picked commits | {len(applied_commits or context.commits)} |",
            f"| Conflicts detected | {'yes' if had_conflicts else 'no'} |",
            f"| Auto-resolved files | {resolved_count} |",
            f"| Unresolved files | {unresolved_count} |",
        ])
    )
    checklist = [
        "- Compare this backport against the source PR before merge.",
    ]
    if any_ai_changes:
        checklist.append(
            "- Review the AI-authored changes carefully for semantic drift."
        )
    elif resolved_count > 0:
        checklist.append(
            "- Review the automatically resolved files carefully for semantic drift."
        )
    if unresolved_count > 0:
        checklist.append(
            "- Resolve the remaining conflicted files or close the PR if the backport is not viable."
        )
    sections.append("### Reviewer Checklist\n\n" + "\n".join(checklist))

    commits_list = "\n".join(f"- `{sha}`" for sha in (applied_commits or context.commits))
    sections.append(f"### Cherry-Picked Commits\n\n{commits_list}")

    # Per-file resolution summaries.
    if results:
        file_lines: list[str] = []
        for result in results:
            status = (
                "Resolved automatically" if result.resolved_content is not None
                else "Needs manual resolution"
            )
            link = links.get(result.path)
            suffix = f" ([view diff]({link}))" if link else ""
            file_lines.append(
                f"- `{result.path}`: {status}. {result.resolution_summary}{suffix}"
            )
        conflict_details = "\n".join(file_lines)
        if any(_was_llm_resolved(r) for r in results):
            conflict_details += (
                "\n\nAI resolution details are posted as a comment on this "
                "PR when available."
            )
        sections.append(
            "### Conflict Details\n\n" + conflict_details
        )

    if ai_summary and any_ai_changes:
        sections.append("### AI Adaptation\n\n" + ai_summary)

    if any_ai_changes:
        sections.append(
            "### Human Review Required\n\n"
            "AI was used to resolve conflicts or adapt this backport. "
            "These changes require careful human review. Verify that they "
            "match the intent of the original pull request."
        )

    return "\n\n".join(sections)

def _escape_table_cell(value: object) -> str:
    """Return markdown-table-safe text."""
    text = str(value).replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return ""
    return text.replace("|", "\\|").replace("\n", "<br>")

def build_pull_create_head_ref(
    base_repo: str,
    push_repo: str | None,
    branch_name: str,
) -> str:
    """Return the head ref used when creating a pull request."""
    if not push_repo or push_repo == base_repo:
        return branch_name
    owner = push_repo.split("/")[0]
    return f"{owner}:{branch_name}"

@dataclass(frozen=True)
class BranchEntry:
    branch: str
    project_number: int

@dataclass(frozen=True)
class Registry:
    repos: tuple[RepoEntry, ...]

    def get_repo(self, repo_full_name: str) -> RepoEntry:
        for entry in self.repos:
            if entry.repo == repo_full_name:
                return entry
        raise KeyError(f"Repository '{repo_full_name}' not found in registry")

    def get_branch(self, repo_full_name: str, branch: str) -> tuple[RepoEntry, BranchEntry]:
        repo_entry = self.get_repo(repo_full_name)
        for b in repo_entry.branches:
            if b.branch == branch:
                return repo_entry, b
        raise KeyError(
            f"Branch '{branch}' not found for '{repo_full_name}' in registry"
        )

def get_branch(self, repo_full_name: str, branch: str) -> tuple[RepoEntry, BranchEntry]:
    repo_entry = self.get_repo(repo_full_name)
    for b in repo_entry.branches:
        if b.branch == branch:
            return repo_entry, b
    raise KeyError(
        f"Branch '{branch}' not found for '{repo_full_name}' in registry"
    )

def get_repo(self, repo_full_name: str) -> RepoEntry:
    for entry in self.repos:
        if entry.repo == repo_full_name:
            return entry
    raise KeyError(f"Repository '{repo_full_name}' not found in registry")

@property
def effective_push_repo(self) -> str:
    return self.push_repo or self.repo

@dataclass(frozen=True)
class ValidationRule:
    paths: tuple[str, ...]
    commands: tuple[str, ...]

def _parse_branch_entry(
    raw: Any, repo_idx: int, branch_idx: int,
    seen_branches: set[str], seen_projects: set[int],
) -> BranchEntry:
    if not isinstance(raw, dict):
        raise ValueError(f"repos[{repo_idx}].branches[{branch_idx}] must be a mapping")

    branch = raw.get("branch")
    if not isinstance(branch, str) or not branch:
        raise ValueError(f"repos[{repo_idx}].branches[{branch_idx}].branch is required")
    if branch in seen_branches:
        raise ValueError(f"Duplicate branch '{branch}' in repos[{repo_idx}]")
    seen_branches.add(branch)

    project_number = raw.get("project_number")
    if not isinstance(project_number, int) or project_number < 0:
        raise ValueError(
            f"repos[{repo_idx}].branches[{branch_idx}].project_number must be a non-negative integer"
        )
    if project_number in seen_projects:
        raise ValueError(
            f"Duplicate project_number {project_number} in repos[{repo_idx}]"
        )
    seen_projects.add(project_number)

    return BranchEntry(branch=str(branch), project_number=project_number)

def _parse_registry(raw: dict[str, Any]) -> Registry:
    # repos
    repos_raw = raw.get("repos", [])
    if not isinstance(repos_raw, list) or not repos_raw:
        raise ValueError("repos must be a non-empty list")

    seen_repos: set[str] = set()
    entries: list[RepoEntry] = []
    for i, repo_raw in enumerate(repos_raw):
        entries.append(_parse_repo_entry(repo_raw, i, seen_repos))

    return Registry(
        repos=tuple(entries),
    )

def _parse_repo_entry(raw: Any, index: int, seen_repos: set[str]) -> RepoEntry:
    if not isinstance(raw, dict):
        raise ValueError(f"repos[{index}] must be a mapping")

    repo = raw.get("repo")
    if not isinstance(repo, str) or not _REPO_RE.match(repo):
        raise ValueError(f"repos[{index}].repo must be a valid 'owner/name' string, got {repo!r}")
    if repo in seen_repos:
        raise ValueError(f"Duplicate repo in registry: {repo!r}")
    seen_repos.add(repo)

    project_owner = raw.get("project_owner")
    if not isinstance(project_owner, str) or not project_owner:
        raise ValueError(f"repos[{index}].project_owner is required")

    project_owner_type = raw.get("project_owner_type", "organization")
    if project_owner_type not in _VALID_OWNER_TYPES:
        raise ValueError(
            f"repos[{index}].project_owner_type must be one of {_VALID_OWNER_TYPES}, "
            f"got {project_owner_type!r}"
        )

    language = raw.get("language")
    if not isinstance(language, str) or not language:
        raise ValueError(f"repos[{index}].language is required")

    push_repo = raw.get("push_repo")
    if push_repo is not None:
        if not isinstance(push_repo, str) or not _REPO_RE.match(push_repo):
            raise ValueError(
                f"repos[{index}].push_repo must be a valid 'owner/name' string"
            )
        if push_repo.split("/", 1)[0] == repo.split("/", 1)[0]:
            raise ValueError(
                f"repos[{index}].push_repo must be a different-owner fork; "
                "omit push_repo for direct upstream pushes"
            )

    build_commands = raw.get("build_commands", [])
    if not isinstance(build_commands, list):
        raise ValueError(f"repos[{index}].build_commands must be a list")
    for j, cmd in enumerate(build_commands):
        if not isinstance(cmd, str) or not cmd.strip():
            raise ValueError(
                f"repos[{index}].build_commands[{j}] must be a non-empty string"
            )

    validation_setup_commands = raw.get("validation_setup_commands", [])
    if not isinstance(validation_setup_commands, list):
        raise ValueError(f"repos[{index}].validation_setup_commands must be a list")
    for j, cmd in enumerate(validation_setup_commands):
        if not isinstance(cmd, str) or not cmd.strip():
            raise ValueError(
                f"repos[{index}].validation_setup_commands[{j}] "
                "must be a non-empty string"
            )

    validation_rules = _parse_validation_rules(raw.get("validation_rules", []), index)
    test_path_patterns = raw.get("test_path_patterns", [])
    if not isinstance(test_path_patterns, list):
        raise ValueError(f"repos[{index}].test_path_patterns must be a list")
    for j, pattern in enumerate(test_path_patterns):
        if not isinstance(pattern, str) or not pattern.strip():
            raise ValueError(
                f"repos[{index}].test_path_patterns[{j}] "
                "must be a non-empty string"
            )
    repair_validation_failures = raw.get("repair_validation_failures", False)
    if not isinstance(repair_validation_failures, bool):
        raise ValueError(
            f"repos[{index}].repair_validation_failures must be a boolean"
        )

    backport_label = raw.get("backport_label", "backport")
    if not isinstance(backport_label, str) or not backport_label.strip():
        raise ValueError(f"repos[{index}].backport_label must be a non-empty string")
    llm_conflict_label = raw.get("llm_conflict_label", "ai-resolved-conflicts")
    if not isinstance(llm_conflict_label, str) or not llm_conflict_label.strip():
        raise ValueError(f"repos[{index}].llm_conflict_label must be a non-empty string")
    max_conflicting_files = raw.get("max_conflicting_files", 100)
    if not isinstance(max_conflicting_files, int) or max_conflicting_files < 1:
        raise ValueError(f"repos[{index}].max_conflicting_files must be a positive integer")

    branches_raw = raw.get("branches", [])
    if not isinstance(branches_raw, list) or not branches_raw:
        raise ValueError(f"repos[{index}].branches must be a non-empty list")

    seen_branches: set[str] = set()
    seen_projects: set[int] = set()
    branches: list[BranchEntry] = []
    for j, b_raw in enumerate(branches_raw):
        branches.append(_parse_branch_entry(b_raw, index, j, seen_branches, seen_projects))

    return RepoEntry(
        repo=repo,
        project_owner=project_owner,
        project_owner_type=project_owner_type,
        language=language,
        push_repo=push_repo,
        build_commands=tuple(build_commands),
        validation_setup_commands=tuple(validation_setup_commands),
        validation_rules=tuple(validation_rules),
        test_path_patterns=tuple(test_path_patterns),
        repair_validation_failures=repair_validation_failures,
        backport_label=backport_label,
        llm_conflict_label=llm_conflict_label,
        max_conflicting_files=max_conflicting_files,
        branches=tuple(branches),
    )

def _parse_validation_rules(raw: Any, repo_idx: int) -> list[ValidationRule]:
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise ValueError(f"repos[{repo_idx}].validation_rules must be a list")

    rules: list[ValidationRule] = []
    for rule_idx, rule_raw in enumerate(raw):
        if not isinstance(rule_raw, dict):
            raise ValueError(
                f"repos[{repo_idx}].validation_rules[{rule_idx}] must be a mapping"
            )
        paths = rule_raw.get("paths")
        if not isinstance(paths, list) or not paths:
            raise ValueError(
                f"repos[{repo_idx}].validation_rules[{rule_idx}].paths "
                "must be a non-empty list"
            )
        for path_idx, pattern in enumerate(paths):
            if not isinstance(pattern, str) or not pattern.strip():
                raise ValueError(
                    f"repos[{repo_idx}].validation_rules[{rule_idx}]"
                    f".paths[{path_idx}] must be a non-empty string"
                )

        commands = rule_raw.get("commands")
        if not isinstance(commands, list) or not commands:
            raise ValueError(
                f"repos[{repo_idx}].validation_rules[{rule_idx}].commands "
                "must be a non-empty list"
            )
        for cmd_idx, command in enumerate(commands):
            if not isinstance(command, str) or not command.strip():
                raise ValueError(
                    f"repos[{repo_idx}].validation_rules[{rule_idx}]"
                    f".commands[{cmd_idx}] must be a non-empty string"
                )

        rules.append(
            ValidationRule(
                paths=tuple(str(pattern) for pattern in paths),
                commands=tuple(str(command) for command in commands),
            )
        )
    return rules

def load_registry(path: str) -> Registry:
    """Load and validate the registry from a YAML file."""
    text = Path(path).read_text(encoding="utf-8")
    raw = yaml.safe_load(text)
    if not isinstance(raw, dict):
        raise ValueError(f"Registry file must be a YAML mapping, got {type(raw).__name__}")
    return _parse_registry(raw)

def _git(repo_dir: str, *args: str) -> str:
    return subprocess.run(
        ["git", *args], cwd=repo_dir, capture_output=True, text=True, check=True,
    ).stdout.strip()

def _in_branch_range(repo_dir: str, base_branch: str, commit_sha: str) -> bool:
    """True if commit_sha is unique to the agent branch (not on the base)."""
    resolved = subprocess.run(
        ["git", "rev-parse", "--verify", "--quiet", f"{commit_sha}^{{commit}}"],
        cwd=repo_dir, capture_output=True, text=True,
    )
    if resolved.returncode != 0:
        return False
    revs = _git(repo_dir, "rev-list", f"origin/{base_branch}..HEAD").splitlines()
    return resolved.stdout.strip() in revs

def _is_merge(repo_dir: str, commit_sha: str) -> bool:
    parents = _git(repo_dir, "rev-list", "--parents", "-n", "1", commit_sha).split()
    return len(parents) > 2

def __post_init__(self) -> None:
    if len(self.commits) != 1:
        raise ValueError(
            "source-change plans must contain exactly one authoritative commit"
        )

def _commit_parents(repo_dir: str, sha: str) -> tuple[str, ...]:
    result = _git(repo_dir, "rev-list", "--parents", "-n", "1", sha)
    fields = result.stdout.strip().split()
    if not fields or fields[0] != sha:
        raise SourceChangeError(f"could not resolve commit {sha}")
    return tuple(fields[1:])

def _git_bytes(
    repo_dir: str,
    *args: str,
) -> subprocess.CompletedProcess[bytes]:
    result = subprocess.run(
        ["git", *args],
        cwd=repo_dir,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        raise SourceChangeError(
            f"git {' '.join(args)} failed: "
            f"{result.stderr.decode('utf-8', errors='replace').strip()[:300]}"
        )
    return result

def _unique_merge_base(repo_dir: str, left: str, right: str) -> str:
    result = _git(repo_dir, "merge-base", "--all", left, right)
    bases = tuple(line for line in result.stdout.splitlines() if line)
    if not bases:
        raise SourceChangeError(
            f"no merge base exists for {left} and {right}; source history is "
            "disconnected"
        )
    if len(bases) > 1:
        raise SourceChangeError(
            f"ambiguous merge base for {left} and {right}: found {len(bases)}; "
            "cannot safely classify this pull request as squash or rebase"
        )
    return bases[0]

class ProjectBackportDiscovery:
    def __init__(
        self,
        gql: GitHubGraphQLClient,
        *,
        project_owner: str,
        project_number: int,
        source_repo: str,
        project_owner_type: str = "organization",
        status_field: str = _DEFAULT_STATUS_FIELD,
        status_value: str = _DEFAULT_STATUS_VALUE,
        branch_fields: list[str] | None = None,
        implicit_target_branch: str | None = None,
    ) -> None:
        self._gql = gql
        self._owner = project_owner
        self._number = project_number
        self._owner_type = project_owner_type
        self._source_repo = source_repo
        self._status_field = status_field
        self._status_value = status_value
        self._branch_fields = branch_fields or list(_DEFAULT_BRANCH_FIELDS)
        self._implicit_target = implicit_target_branch

    def discover(
        self,
        release_branches: list[str],
    ) -> dict[str, list[ProjectBackportCandidate]]:
        by_branch: dict[str, list[ProjectBackportCandidate]] = {
            branch: [] for branch in release_branches
        }
        for item in self._iter_items():
            candidate = self._candidate_from_item(item, release_branches)
            if candidate:
                by_branch.setdefault(candidate.target_branch, []).append(candidate)
        return by_branch

    def _iter_items(self) -> list[dict[str, Any]]:
        owner_field = "user" if self._owner_type == "user" else "organization"
        query = _project_items_query(owner_field)
        cursor = None
        items: list[dict[str, Any]] = []
        while True:
            data = self._gql.execute(
                query,
                {"owner": self._owner, "number": self._number, "cursor": cursor},
            )
            project = (data.get(owner_field) or {}).get("projectV2")
            if not project:
                raise RuntimeError(f"Project {self._owner}/{self._number} not found")
            page = project.get("items") or {}
            items.extend(page.get("nodes") or [])
            page_info = page.get("pageInfo") or {}
            if not page_info.get("hasNextPage"):
                return items
            cursor = page_info.get("endCursor")

    def _candidate_from_item(
        self,
        item: dict[str, Any],
        branches: list[str],
    ) -> ProjectBackportCandidate | None:
        content = item.get("content") or {}
        if content.get("__typename") != "PullRequest" or not content.get("merged"):
            return None

        item_repo = (content.get("repository") or {}).get("nameWithOwner")
        if item_repo and item_repo != self._source_repo:
            logger.debug(
                "Skipping project item PR #%s from %s (sweep target is %s)",
                content.get("number"),
                item_repo,
                self._source_repo,
            )
            return None

        fields = _extract_field_values(item)
        if not _field_has_value(fields, self._status_field, self._status_value):
            return None

        if self._implicit_target is not None:
            target_branch = self._implicit_target
        else:
            matched_branch = _matching_release_branch(
                fields,
                self._branch_fields,
                branches,
            )
            if not matched_branch:
                return None
            target_branch = matched_branch

        commits = [
            node.get("commit", {}).get("oid", "")
            for node in (content.get("commits", {}).get("nodes") or [])
        ]
        commits_page = content.get("commits") or {}
        merge_sha = (content.get("mergeCommit") or {}).get("oid")
        return ProjectBackportCandidate(
            source_pr_number=int(content["number"]),
            source_pr_title=str(content.get("title") or ""),
            source_pr_url=str(content.get("url") or ""),
            target_branch=target_branch,
            merge_commit_sha=merge_sha,
            commit_shas=[sha for sha in commits if sha],
            merged_at=str(content.get("mergedAt") or ""),
            source_commits_complete=not bool(
                (commits_page.get("pageInfo") or {}).get("hasNextPage")
            ),
        )

