            ("git", "ls-files", "--others", "--exclude-standard", "-z"),
        ),
        run_process=run_process,
    )

class GitHubGraphQLClient:
    def __init__(self, token: str) -> None:
        self._token = token

    def execute(self, query: str, variables: dict[str, Any]) -> dict[str, Any]:
        payload = json.dumps({"query": query, "variables": variables}).encode()
        last_exc: Exception | None = None
        for attempt in range(4):
            request = urllib.request.Request(
                "https://api.github.com/graphql",
                data=payload,
                headers={
                    "Authorization": f"Bearer {self._token}",
                    "Content-Type": "application/json",
                },
                method="POST",
            )
            try:
                with urllib.request.urlopen(request, timeout=60) as response:
                    body = response.read().decode("utf-8")
                data = json.loads(body)
                errors = data.get("errors")
                if errors and _is_transient_graphql_error(errors) and attempt < 3:
                    wait = random.uniform(0, min(8.0, 1.0 * (2 ** attempt)))
                    logger.warning("GraphQL transient error retry after %.2fs: %s", wait, errors)
                    time.sleep(wait)
                    continue
                if errors:
                    msgs = "; ".join(str(e.get("message", e)) for e in errors)
                    raise RuntimeError(f"GraphQL errors: {msgs}")
                return data.get("data", {})
            except urllib.error.HTTPError as exc:
                details = exc.read().decode("utf-8", errors="replace")
                if exc.code in (429, 500, 502, 503, 504) and attempt < 3:
                    last_exc = exc
                    wait = random.uniform(0, min(8.0, 1.0 * (2 ** attempt)))
                    logger.warning(
                        "GraphQL %d retry after %.2fs: %s",
                        exc.code, wait, details[:200],
                    )
                    time.sleep(wait)
                    continue
                raise RuntimeError(f"GraphQL failed: {exc.code} {details}") from exc
            except urllib.error.URLError as exc:
                if attempt < 3:
                    last_exc = exc
                    wait = random.uniform(0, min(8.0, 1.0 * (2 ** attempt)))
                    logger.warning("GraphQL URL error retry after %.2fs: %s", wait, exc)
                    time.sleep(wait)
                    continue
                raise

        raise RuntimeError("GraphQL request failed after retries") from last_exc

def _is_transient_graphql_error(errors: list[dict[str, Any]]) -> bool:
    """True if any GraphQL error is a rate-limit or transient service failure.

    GitHub returns these in a 200 body, so they bypass HTTP-level retries.
    """
    for error in errors:
        if error.get("type") in _TRANSIENT_GRAPHQL_ERROR_TYPES:
            return True
        message = str(error.get("message", "")).lower()
        if "rate limit" in message or "secondary rate limit" in message or "timeout" in message:
            return True
    return False

@dataclass
class BranchSweepResult:
    target_branch: str
    candidates_found: int = 0
    results: list[CandidateResult] = field(default_factory=list)
    pr_url: str = ""
    error: str = ""

    @property
    def applied_count(self) -> int:
        """Number of candidates that were cherry-picked onto the branch."""
        return sum(1 for item in self.results if item.outcome == "applied")

@property
def applied_count(self) -> int:
    """Number of candidates that were cherry-picked onto the branch."""
    return sum(1 for item in self.results if item.outcome == "applied")

def _reconcile_sweep_diff_comments(
    pr: Any,
    result: BranchSweepResult,
    *,
    branch_applied: list[CandidateResult] | None = None,
) -> dict[int, str]:
    """Reconcile AI-resolution diff comments on the sweep PR.

    Each currently-applied source PR's comments are reconciled against its
    fresh resolutions. A prior comment group is deleted only when its source
    PR is no longer on the sweep branch at all. A source PR that is still on
    the branch but was not freshly re-resolved this run (e.g. it shows up as
    already-on-branch) keeps its comments untouched, so reruns do not wipe
    still-relevant diffs. The marker identity is the source PR number.

    Returns ``{source_pr: comment_url}`` so the PR body can link each row to its
    AI-resolution comment. Best-effort: a comment failure must never fail the
    sweep.
    """
    # Fresh resolutions by source PR, only for candidates on the branch this run.
    desired_by_pr: dict[int, CandidateResult] = {
        c.source_pr_number: c
        for c in result.results
        if c.outcome == "applied" and c.resolutions
    }
    # Every source PR still represented on the sweep branch (applied this run or
    # already on the branch from a prior sweep). Their comments must be kept.
    on_branch = {
        c.source_pr_number
        for c in result.results
        if result_is_on_backport_branch(c)
    }
    if branch_applied is not None:
        on_branch.update(
            c.source_pr_number
            for c in branch_applied
            if result_is_on_backport_branch(c)
        )

    try:
        prior_urls = marked_source_pr_urls(pr, bot_login=DIFF_COMMENT_LOGIN)
        prior = set(prior_urls)
    except Exception as exc:
        logger.warning("Could not list prior AI-diff comment groups on sweep PR: %s", exc)
        prior_urls = {}
        prior = set()

    # Reconcile fresh resolutions; delete only groups whose source PR has left
    # the branch entirely.
    stale = {pr_num for pr_num in prior if pr_num not in on_branch and pr_num not in desired_by_pr}
    comment_urls: dict[int, str] = {
        pr_num: url
        for pr_num, url in prior_urls.items()
        if pr_num in on_branch and pr_num not in desired_by_pr
    }
    for source_pr in sorted(desired_by_pr.keys() | stale):
        candidate = desired_by_pr.get(source_pr)
        try:
            links = reconcile_diff_comments(
                pr,
                source_pr,
                candidate.resolutions if candidate else [],
                source_title=candidate.source_pr_title if candidate else None,
                resolved_commit_sha=candidate.resolved_commit_sha if candidate else None,
                bot_login=DIFF_COMMENT_LOGIN,
            )
            # All paths for a source PR point at the same grouped comment.
            if links:
                comment_urls[source_pr] = next(iter(links.values()))
        except Exception as exc:
            logger.warning(
                "Failed to reconcile diff comments for source PR #%d on sweep PR: %s",
                source_pr, exc,
            )
    return comment_urls

def delete_stale_backport_branch(gh: Any, push_repo: str, branch: str) -> None:
    repo = retry_github_call(lambda: gh.get_repo(push_repo), retries=2, description=f"get {push_repo}")
    try:
        ref = retry_github_call(
            lambda: repo.get_git_ref(f"heads/{branch}"),
            retries=1,
            description=f"check ref {branch}",
        )
    except GithubException as exc:
        if exc.status == 404:
            return
        logger.warning("Could not prune stale backport branch %s: %s", branch, exc)
        return
    logger.info("Deleting stale backport branch %s on %s (no open PR)", branch, push_repo)
    retry_github_call(lambda: ref.delete(), retries=2, description=f"delete ref {branch}")

def find_existing_pr(gh: Any, base_repo: str, push_repo: str, branch: str) -> Any | None:
    repo = retry_github_call(lambda: gh.get_repo(base_repo), retries=2, description=f"get {base_repo}")
    head_ref = build_pull_search_head_ref(base_repo, push_repo, branch)
    pulls = retry_github_call(
        lambda: list(repo.get_pulls(state="open", head=head_ref)),
        retries=2, description="list PRs",
    )
    for pull in pulls:
        if pull_matches_push_repo(pull, push_repo):
            return pull
    return None

def mark_pr_ready_for_review(gql: GitHubGraphQLClient, pr_node_id: str) -> None:
    mutation = """
    mutation($id: ID!) {
      markPullRequestReadyForReview(input: {pullRequestId: $id}) {
        pullRequest { isDraft }
      }
    }
    """
    gql.execute(mutation, {"id": pr_node_id})

def _failure_outcome(value: str) -> CandidateOutcome:
    outcome = value.strip()
    if outcome in {"skipped-conflict", "skipped-validation-failed", "error"}:
        return cast(CandidateOutcome, outcome)
    return "error"

def _is_ai_resolved(result: CandidateResult | None) -> bool:
    """Whether *result* records AI-authored changes, durably or by detail."""
    if result is None:
        return False
    return result.resolved_by_ai or _detail_records_ai(result.detail)

def _parse_section_rows(body: str, heading: str, *, min_cells: int) -> Iterator[tuple[int, list[str]]]:
    in_section = False
    for line in body.splitlines():
        stripped = line.strip()
        if stripped == heading:
            in_section = True
            continue
        if in_section and stripped.startswith("## "):
            break
        if not in_section or not stripped.startswith("|"):
            continue

        cells = _split_markdown_table_row(stripped)
        if len(cells) < min_cells:
            continue
        source = cells[0]
        if source.lower() == "source pr" or set(source) <= {"-"}:
            continue
        match = re.search(r"#(\d+)", source)
        if not match:
            continue
        yield int(match.group(1)), cells

def build_pr_body(
    result: BranchSweepResult,
    *,
    branch_applied: list[CandidateResult] | None = None,
    previous_body: str | None = None,
    comment_urls: dict[int, str] | None = None,
) -> str:
    comment_urls = comment_urls or {}
    lines = [
        f"# Backport sweep for {result.target_branch}",
        "",
        'Automated cherry-picks from PRs marked "To be backported".',
        "",
    ]

    applied = merge_applied_results(
        [r for r in result.results if result_is_on_backport_branch(r)],
        branch_applied=branch_applied,
        previous_body=previous_body,
    )
    resolved = {r.source_pr_number for r in applied}
    failed_now = []
    skipped_empty = []
    for r in result.results:
        if r.outcome in {"applied", "skipped-existing"}:
            resolved.add(r.source_pr_number)
            if (
                r.outcome == "skipped-existing"
                and r.detail == DETAIL_EMPTY_ON_TARGET
                and r.source_pr_number not in {a.source_pr_number for a in applied}
            ):
                skipped_empty.append(r)
        else:
            failed_now.append(r)
    failed = merge_failed_results(failed_now, resolved=resolved, previous_body=previous_body)

    if applied:
        lines.extend(["## Applied", "", "| Source PR | Title | Detail |", "|---|---|---|"])
        for r in applied:
            detail = _esc(r.detail)
            url = comment_urls.get(r.source_pr_number)
            if url and _is_ai_resolved(r):
                detail = f"[{detail}]({url})"
            lines.append(
                f"| #{r.source_pr_number} | {_esc(r.source_pr_title)} | {detail} |",
            )
        lines.append("")
        if any(_is_ai_resolved(r) for r in applied):
            lines.extend(
                [
                    "AI resolution details are posted as comments on this PR when available.",
                    "",
                ]
            )

    if skipped_empty:
        lines.extend(
            [
                "## Skipped",
                "",
                "These candidates were evaluated but contribute no change to this "
                "branch, e.g. the fix targets code that does not exist here. No "
                "backport commit was created for them.",
                "",
                "| Source PR | Title | Reason |",
                "|---|---|---|",
            ]
        )
        for r in skipped_empty:
            lines.append(
                f"| #{r.source_pr_number} | {_esc(r.source_pr_title)} | {_esc(_skip_reason(r))} |",
            )
        lines.append("")

    if failed:
        lines.extend(
            [
                "## Needs attention",
                "",
                "These candidates could not be applied automatically and need a maintainer to follow up.",
                "",
                f"<details><summary>{len(failed)} candidate(s)</summary>",
                "",
                "| Source PR | Title | Outcome | Reason |",
                "|---|---|---|---|",
            ]
        )
        for r in failed:
            lines.append(
                f"| #{r.source_pr_number} | {_esc(r.source_pr_title)} | {r.outcome} | {_esc(r.detail)} |",
            )
        lines.extend(["", "</details>", ""])

    lines.extend(["---", "*Generated by valkey-ci-agent using Claude Code.*"])
    return "\n".join(lines)

def build_summary(results: list[BranchSweepResult]) -> str:
    lines = ["## Backport Sweep", ""]
    for r in results:
        applied = sum(1 for c in r.results if result_is_on_backport_branch(c))
        suffix = f" -- [PR]({r.pr_url})" if r.pr_url else ""
        if r.error:
            suffix += f" -- error: {r.error}"
        lines.append(f"- `{r.target_branch}`: {applied}/{r.candidates_found} applied" + suffix)
    return "\n".join(lines)

def compact_validation_output(output: str, *, limit: int = 500) -> str:
    text = output.strip()
    if len(text) <= limit:
        return text
    return text[-limit:]

def merge_applied_results(
    current: list[CandidateResult],
    *,
    branch_applied: list[CandidateResult] | None = None,
    previous_body: str | None = None,
) -> list[CandidateResult]:
    previous_by_pr = {r.source_pr_number: r for r in parse_previous_applied(previous_body or "")}
    current_by_pr = {r.source_pr_number: r for r in current}
    membership = branch_applied if branch_applied is not None else current

    merged: list[CandidateResult] = []
    seen: set[int] = set()
    for base in membership:
        if base.source_pr_number in seen:
            continue
        seen.add(base.source_pr_number)
        merged.append(
            _merge_applied_result(
                base,
                current_result=current_by_pr.get(base.source_pr_number),
                previous_result=previous_by_pr.get(base.source_pr_number),
            )
        )
    return merged

def merge_failed_results(
    current: list[CandidateResult],
    *,
    resolved: set[int],
    previous_body: str | None = None,
) -> list[CandidateResult]:
    current_by_pr = {r.source_pr_number: r for r in current}

    merged: list[CandidateResult] = []
    seen: set[int] = set()
    for base in [*current, *parse_previous_failed(previous_body or "")]:
        pr_number = base.source_pr_number
        if pr_number in seen or pr_number in resolved:
            continue
        seen.add(pr_number)
        merged.append(current_by_pr.get(pr_number, base))
    return merged

def parse_previous_failed(body: str) -> list[CandidateResult]:
    return [
        CandidateResult(pr_number, cells[1], _failure_outcome(cells[2]), cells[3])
        for pr_number, cells in _parse_section_rows(body, "## Needs attention", min_cells=4)
    ]

def repair_diagnosis_from_detail(detail: str) -> str:
    prefix = "Claude repair diagnosis:\n"
    if not detail.startswith(prefix):
        return ""
    body = detail[len(prefix) :]
    return body.split("\n\nValidation output:\n", 1)[0].strip()

def result_is_on_backport_branch(result: CandidateResult) -> bool:
    return result.outcome == "applied" or (
        result.outcome == "skipped-existing" and result.detail == DETAIL_ALREADY_ON_SWEEP_BRANCH
    )

def validation_failure_detail(output: str) -> str:
    """Preserve AI diagnosis while keeping routine validation logs compact."""
    diagnosis = repair_diagnosis_from_detail(output)
    if not diagnosis:
        return compact_validation_output(output)
    marker = "\n\nValidation output:\n"
    validation_tail = output.split(marker, 1)[1] if marker in output else ""
    return (
        "Claude repair diagnosis:\n"
        f"{diagnosis[:1500]}\n\n"
        "Validation output:\n"
        f"{compact_validation_output(validation_tail)}"
    )

def _read_text_file(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""

def extract_agent_result_text(stdout: str) -> str:
    result_text = ""
    for line in stdout.strip().splitlines():
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, TypeError):
            continue
        if not isinstance(event, dict):
            continue
        if event.get("type") != "result" or "result" not in event:
            continue
        raw_result = event.get("result")
        if isinstance(raw_result, str):
            result_text = raw_result.strip()
        elif raw_result is not None:
            result_text = json.dumps(raw_result, sort_keys=True, default=str)
    return result_text

def remove_validation_log_path(log_path: str | None) -> None:
    if not log_path:
        return
    try:
        os.unlink(log_path)
    except OSError:
        pass

def repair_validation_failure_with_claude(
    repo_dir: str,
    target_branch: str,
    test_commands: list[str],
    validation_rules: list[Any],
    validation_output: str,
    *,
    validation_log_path: str | None = None,
    run_git: RunGit = run_git_default,
    run_agent_func: RunAgent = run_agent,
    validate_func: ValidateBranch = validate_backport_branch,
    changed_paths_func: ChangedPaths = worktree_changed_paths,
    changed_paths_since_base_func: ChangedPathsSinceBase = changed_paths_since_base,
    has_staged_changes_func: HasStagedChanges = has_staged_changes,
) -> ValidationOutcome:
    changed_paths = tuple(changed_paths_since_base_func(repo_dir, f"origin/{target_branch}"))
    if not changed_paths:
        return ValidationOutcome(False, validation_output)

    before_contents = {
        path: _read_text_file(Path(repo_dir, path))
        for path in changed_paths
    }

    owns_log_path = validation_log_path is None
    log_path = validation_log_path or create_validation_log_path()
    try:
        if owns_log_path:
            Path(log_path).write_text(validation_output, encoding="utf-8")

        prompt = build_validation_repair_prompt(
            target_branch,
            changed_paths,
            log_path,
        )
        logger.info(
            "Calling Claude Code to repair validation failure on %s "
            "(%d changed path(s), log=%s)",
            target_branch,
            len(changed_paths),
            log_path,
        )
        agent_result = run_agent_func(
            "validation_repair_edit_only",
            prompt,
            cwd=repo_dir,
        )
        diagnosis = extract_agent_result_text(getattr(agent_result, "stdout", ""))
        if agent_result.returncode != 0:
            run_git(repo_dir, "reset", "--hard", "HEAD")
            detail = (
                agent_result.stderr
                or diagnosis
                or "Claude Code validation repair failed"
            )
            return ValidationOutcome(False, detail[:500] or validation_output)

        edited_paths = changed_paths_func(repo_dir)
        unexpected_paths = sorted(set(edited_paths) - set(changed_paths))
        if unexpected_paths:
            run_git(repo_dir, "reset", "--hard", "HEAD")
            return ValidationOutcome(
                False,
                "Claude Code validation repair edited files outside the backport "
                "diff: " + ", ".join(unexpected_paths[:10]),
            )
        if not edited_paths:
            return ValidationOutcome(
                False,
                validation_output_with_diagnosis(validation_output, diagnosis),
            )

        run_git(repo_dir, "add", *edited_paths)
        if not has_staged_changes_func(repo_dir):
            return ValidationOutcome(
                False,
                validation_output_with_diagnosis(validation_output, diagnosis),
            )
        run_git(repo_dir, "commit", "-m", "Repair backport validation failure")

        ok, output = validate_func(
            repo_dir,
            target_branch,
            test_commands,
            validation_rules,
        )
        if ok:
            logger.info("Claude Code validation repair passed for %s", target_branch)
            summary = diagnosis or "Claude Code repaired the validation failure."
            resolutions = tuple(
                _validation_repair_resolution(
                    path,
                    before_contents.get(path, ""),
                    _read_text_file(Path(repo_dir, path)),
                    summary,
                )
                for path in edited_paths
            )
            return ValidationOutcome(
                True,
                output,
                resolutions=resolutions,
                ai_summary=summary,
            )

        logger.warning(
            "Claude Code validation repair did not fix %s; removing repair commit.",
            target_branch,
        )
        run_git(repo_dir, "reset", "--hard", "HEAD^")
        return ValidationOutcome(
            False,
            validation_output_with_diagnosis(output, diagnosis),
        )
    finally:
        if owns_log_path:
            remove_validation_log_path(log_path)

def run_test_commands(
    repo_dir: str,
    test_commands: list[str],
    log_path: str | None = None,
) -> tuple[bool, str]:
    return run_build_commands(repo_dir, test_commands, log_path=log_path)

def validate_backport_branch(
    repo_dir: str,
    target_branch: str,
    test_commands: list[str],
    validation_rules: list[Any],
    log_path: str | None = None,
) -> tuple[bool, str]:
    commands = select_validation_commands(
        test_commands,
        validation_rules,
        changed_paths_since_base(repo_dir, f"origin/{target_branch}"),
    )
    return run_test_commands(repo_dir, commands, log_path=log_path)

def validation_output_with_diagnosis(
    validation_output: str,
    diagnosis: str,
) -> str:
    diagnosis = diagnosis.strip()
    if not diagnosis:
        return validation_output
    return (
        "Claude repair diagnosis:\n"
        f"{diagnosis[:1200]}\n\n"
        "Validation output:\n"
        f"{validation_output}"
    )

def _terminal_trailer_block(lines: list[str]) -> list[str]:
    """Return the final RFC-822-style trailer block, if structurally present."""
    end = len(lines)
    while end > 0 and not lines[end - 1].strip():
        end -= 1
    start = end
    while start > 0 and _TRAILER_LINE.match(lines[start - 1]):
        start -= 1
    if start == end:
        return []
    if start > 0 and lines[start - 1].strip():
        return []
    return lines[start:end]

def has_conflict_markers(content: str) -> bool:
    """Return ``True`` if *content* contains git conflict markers."""
    return bool(_CONFLICT_MARKERS.search(content))

def is_whitespace_only_conflict(target_content: str, source_content: str) -> bool:
    """Return ``True`` when the two contents differ only in whitespace."""
    return _strip_all_whitespace(target_content) == _strip_all_whitespace(source_content)

def pr_numbers_from_commit_messages(messages: list[str]) -> set[int]:
    """Source PR numbers from subjects or durable backport trailers."""
    numbers: set[int] = set()
    for message in messages:
        lines = message.splitlines()
        if lines:
            numbers.update(pr_numbers_from_commit_subjects([lines[0]]))
        for line in _terminal_trailer_block(lines):
            trailer = re.match(
                r"Backport-Source-PR:\s*#?(\d+)\s*$",
                line,
                re.IGNORECASE,
            )
            if trailer:
                numbers.add(int(trailer.group(1)))
    return numbers

def changed_paths_since_base(repo_dir: str, base_ref: str) -> tuple[str, ...]:
    result = subprocess.run(
        ["git", "diff", "--name-only", f"{base_ref}...HEAD"],
        cwd=repo_dir,
        check=True,
        capture_output=True,
        text=True,
    )
    return tuple(line.strip() for line in result.stdout.splitlines() if line.strip())

def select_validation_commands(
    base_commands: Iterable[str],
    validation_rules: Iterable["ValidationRule"],
    changed_paths: Iterable[str],
) -> list[str]:
    commands: list[str] = []
    seen: set[str] = set()
    for command in base_commands:
        if command not in seen:
            commands.append(command)
            seen.add(command)

    paths = tuple(changed_paths)
    for rule in validation_rules:
        if not _rule_matches(rule.paths, paths):
            continue
        for command in rule.commands:
            if command not in seen:
                commands.append(command)
                seen.add(command)
    return commands

def _backend_label(outcome: FixOutcome) -> str:
    backend = outcome.verify_backend
    if backend == "local":
        return "targeted verification on a Linux runner"
    if backend.startswith("docker:"):
        return f"targeted verification in the `{backend[len('docker:'):]}` container"
    if backend == "macos":
        run = f" ([run]({outcome.macos_run_url}))" if outcome.macos_run_url else ""
        return f"targeted verification on a macOS runner{run}"
    if backend == "upstream-port":
        return "ported upstream fix; awaiting this PR's normal CI"
    return backend

def _remaining_checks(outcome: FixOutcome) -> list[str]:
    if not outcome.other_failing_checks:
        return []
    listed = "\n".join(f"- `{name}`" for name in outcome.other_failing_checks)
    return [
        "Other checks also failed in that run; re-invoke with the same command to "
        "address the next one:",
        listed,
        "",
    ]

def _render_handoff(outcome: FixOutcome) -> str:
    proposal = outcome.proposal
    lines = [
        "I diagnosed this and prepared a fix, but I could not verify it in my "
        "environment, so I am handing it off rather than pushing it unverified.",
        "",
    ]
    if outcome.failing_run_url:
        lines += [f"From the failure in [this run]({outcome.failing_run_url}).", ""]
    if proposal is not None and proposal.root_cause:
        lines += [f"**Root cause:** {proposal.root_cause}", ""]
    lines += [f"**Why not verified:** {outcome.summary}", ""]
    if outcome.review is not None and outcome.review.reasoning:
        lines += [f"**Review:** {outcome.review.reasoning}", ""]
    if outcome.handoff_patch:
        lines += [
            "Proposed patch (apply and let this PR's CI judge it):",
            "",
            _fenced(outcome.handoff_patch, lang="diff"),
            "",
        ]
    lines += _remaining_checks(outcome)
    lines.append("_I did not push this; a human should apply it. I do not merge._")
    return "\n".join(lines)

def _render_pushed(outcome: FixOutcome) -> str:
    proposal = outcome.proposal
    run = outcome.run_result
    review = outcome.review
    lines = [
        f"Fixed **{proposal.failing_check if proposal else 'the failing check'}** "
        f"and pushed `{outcome.commit_sha[:12]}` to this PR's branch.",
        "",
    ]
    if outcome.failing_run_url:
        lines += [f"Fixing the failure from [this run]({outcome.failing_run_url}).", ""]
    lines += [
        f"**Root cause:** {proposal.root_cause if proposal else ''}",
        "",
    ]
    if run is not None:
        check_name = proposal.failing_check if proposal else ""
        highlight = _result_lines_for(run.output_tail, check_name)
        if highlight:
            lines += [
                "The previously-failing check now passes:",
                "",
                _fenced(highlight),
                "",
            ]
        block = f"$ {run.command}\nexit {run.exit_code}\n{run.output_tail[-_OUTPUT_TAIL_IN_COMMENT:]}"
        lines += [
            "<details><summary>Full verification output</summary>",
            "",
            _fenced(block),
            "</details>",
            "",
        ]
    if outcome.verify_backend:
        where = _backend_label(outcome)
        lines += [f"**Verified by:** {where}", ""]
    if review is not None and review.reasoning:
        lines += [f"**Review:** {review.reasoning}", ""]
    lines += _remaining_checks(outcome)
    if outcome.verify_backend == "upstream-port":
        lines.append(
            "_This is a port of an upstream fix; this PR's normal CI is the "
            "verification authority. I do not merge._"
        )
    else:
        lines.append(
            "_The fix passed targeted verification of the failing check; this PR's "
            "full CI will confirm. I do not merge._"
        )
    return "\n".join(lines)

def _render_refused(outcome: FixOutcome) -> str:
    lines = [f"I did not push a fix: {outcome.summary}", ""]
    if outcome.failing_run_url:
        lines += [f"Looked at the failure from [this run]({outcome.failing_run_url}).", ""]
    if outcome.run_result is not None and outcome.run_result.output_tail:
        lines += [
            "<details><summary>Evidence</summary>",
            "",
            _fenced(outcome.run_result.output_tail[-_OUTPUT_TAIL_IN_COMMENT:]),
            "</details>",
            "",
        ]
    lines += _remaining_checks(outcome)
    return "\n".join(lines)

def render_comment(outcome: FixOutcome) -> str:
    if outcome.kind is OutcomeKind.PUSHED:
        return _render_pushed(outcome)
    if outcome.kind is OutcomeKind.REFUSED:
        return _render_refused(outcome)
    if outcome.kind is OutcomeKind.HANDOFF:
        return _render_handoff(outcome)
    return _render_failed(outcome)

def _already_claimed(comment: Any, bot_login: str) -> bool:
    """True if the bot's own App identity already reacted to this comment."""
    reactions = retry_github_call(
        lambda: comment.get_reactions(),
        retries=2,
        description=f"read reactions on comment {comment.id}",
    )
    return any(r.content == _CLAIM_REACTION and r.user.login == bot_login for r in reactions)

def _issue_number_from_url(url: str) -> int | None:
    tail = url.rstrip("/").rsplit("/", 1)[-1]
    return int(tail) if tail.isdigit() else None

def _lookback_minutes() -> int:
    return env_int(
        "CI_FIX_POLL_LOOKBACK_MINUTES",
        _DEFAULT_LOOKBACK_MINUTES,
        minimum=1,
        maximum=_MAX_LOOKBACK_MINUTES,
    )

def _poll_duration_seconds() -> int:
    return env_seconds(
        "CI_FIX_POLL_DURATION_SECONDS",
        0,
        minimum=0,
        maximum=_MAX_LOOP_SECONDS,
    )

def _coerce_path(value: Any) -> FixPath:
    try:
        return FixPath(str(value).strip().lower())
    except ValueError:
        # An unrecognized path is treated as a refusal: we never act on an
        # ambiguous plan.
        return FixPath.REFUSE

def _confidence(value: Any) -> float:
    try:
        return max(0.0, min(1.0, float(value)))
    except (TypeError, ValueError):
        return 0.0

def _last_agent_text(stdout: str, *, limit: int = 500) -> str:
    """Best-effort extraction of the final assistant text from the stream.

    The stream is JSONL; we scan for the last result/assistant ``text`` field.
    Returns an empty string if nothing parseable is found.
    """
    last = ""
    for line in stdout.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            event = json.loads(line)
        except (ValueError, TypeError):
            continue
        if isinstance(event, dict):
            text = event.get("result") or event.get("text")
            if isinstance(text, str) and text.strip():
                last = text.strip()
    return last[:limit]

def _parse_proposal(stdout: str) -> FixProposal:
    payload = extract_json_object(stdout, required_key="path")
    if payload is None:
        raise ValueError("no diagnosis JSON object in agent response")
    return _proposal_from_payload(payload)

def _str_tuple(value: Any) -> tuple[str, ...]:
    if not isinstance(value, list):
        return ()
    return tuple(item.strip() for item in value if isinstance(item, str) and item.strip())

@dataclass(frozen=True)
class GateRejection:
    """A refusal with a human-readable reason for the PR comment."""

    reason: str

@dataclass(frozen=True)
class ParsedCommand:
    run_owner: str
    run_repo: str
    run_id: int
    hint: str

def _auth_allowlist() -> frozenset[str]:
    raw = os.environ.get("CI_FIX_AUTH_ALLOWLIST", "")
    return frozenset(login.strip() for login in raw.split(",") if login.strip())

def build_fix_request(
    gh: Any,
    *,
    command: ParsedCommand,
    pr_repo_full_name: str,
    pr_number: int,
    commenter: str,
    org: str = "valkey-io",
    auth_team: str = _DEFAULT_AUTH_TEAM,
    retries: int = 2,
) -> FixRequest | GateRejection:
    """Run all gate checks and return a FixRequest or a GateRejection.

    Assumes the comment was already confirmed to be on a pull request by the
    caller (the GitHub Actions event guarantees this for ``issue_comment`` on
    a PR); this function enforces authorization, run ownership, and SHA
    binding.
    """
    if not is_authorized(gh, org, auth_team, commenter, retries=retries):
        return GateRejection(
            reason=f"@{commenter} is not an active member of {org}/{auth_team}; refusing."
        )

    run_repo_full_name = f"{command.run_owner}/{command.run_repo}"
    if run_repo_full_name != pr_repo_full_name:
        return GateRejection(
            reason=(
                f"The linked run belongs to {run_repo_full_name}, not this PR's "
                f"repository {pr_repo_full_name}; refusing."
            )
        )

    try:
        pr = retry_github_call(
            lambda: gh.get_repo(pr_repo_full_name).get_pull(pr_number),
            retries=retries, description=f"get PR #{pr_number}",
        )
        run = retry_github_call(
            lambda: gh.get_repo(pr_repo_full_name).get_workflow_run(command.run_id),
            retries=retries, description=f"get run {command.run_id}",
        )
    except Exception as exc:  # noqa: BLE001 - fail closed
        return GateRejection(reason=f"Could not load PR or run: {exc}")

    run_status = str(getattr(run, "status", "") or "")
    if run_status != "completed":
        return GateRejection(
            reason=(
                f"The linked run is not finished yet (status: {run_status or 'unknown'}). "
                "Its logs are only available once it completes - re-run me when it has."
            )
        )
    # We deliberately do NOT gate on the run's overall conclusion. A run can be
    # "cancelled" overall (a manual stop, or fail-fast after one job failed) yet
    # still contain genuine job failures worth fixing. Whether there is a real
    # failure to act on is decided per-job downstream: the pipeline lists the
    # jobs that actually failed and requires the AI's hinted job to be one of
    # them, refusing otherwise. Run-level conclusion is noise; the job is truth.

    pr_head_sha = str(getattr(pr.head, "sha", "") or "")
    pr_head_ref = str(getattr(pr.head, "ref", "") or "")
    pr_head_repo = str(getattr(getattr(pr.head, "repo", None), "full_name", "") or "")
    run_head_sha = str(getattr(run, "head_sha", "") or "")
    run_head_branch = str(getattr(run, "head_branch", "") or "")

    if not pr_head_sha or not run_head_sha:
        return GateRejection(
            reason="Could not determine the PR or run head commit; refusing."
        )
    if run_head_sha != pr_head_sha:
        return GateRejection(
            reason=(
                "The PR branch has moved since this run "
                f"(run built {run_head_sha[:12] or 'unknown'}, PR head is "
                f"{pr_head_sha[:12] or 'unknown'}); re-run CI and try again."
            )
        )
    if run_head_branch and pr_head_ref and run_head_branch != pr_head_ref:
        return GateRejection(
            reason=(
                f"The run's branch ({run_head_branch}) does not match the PR head "
                f"branch ({pr_head_ref}); refusing."
            )
        )
    if not pr_head_repo:
        return GateRejection(
            reason="Could not determine the PR head repository; refusing.",
        )
    if pr_head_repo != pr_repo_full_name:
        return GateRejection(
            reason=(
                f"The PR head is on {pr_head_repo}, not {pr_repo_full_name}; "
                "ci_fix only pushes to branches on the PR's own repository."
            )
        )

    return FixRequest(
        repo_full_name=pr_repo_full_name,
        pr_number=pr_number,
        head_repo_full_name=pr_repo_full_name,
        head_branch=pr_head_ref,
        head_sha=pr_head_sha,
        run_id=command.run_id,
        requested_by=commenter,
        hint=command.hint,
    )

def parse_command(body: str) -> ParsedCommand | None:
    """Parse a comment body into a command, or None if it isn't one."""
    if not body:
        return None
    match = _COMMAND_RE.search(body)
    if not match:
        return None
    url_match = _RUN_URL_RE.search(match.group("url"))
    if not url_match:
        return None
    hint = (match.group("hint") or "").strip()
    return ParsedCommand(
        run_owner=url_match.group("owner"),
        run_repo=url_match.group("repo"),
        run_id=int(url_match.group("run_id")),
        hint=hint,
    )

def _parse_event(event: dict) -> tuple[str, int, str, str, int] | None:
    """Extract (repo_full_name, pr_number, commenter, body, comment_id) from the event.

    Returns None when the event is not a created comment on a pull request.
    """
    if event.get("action") != "created":
        return None
    issue = event.get("issue") or {}
    if "pull_request" not in issue:
        return None
    comment = event.get("comment") or {}
    body = comment.get("body") or ""
    commenter = (comment.get("user") or {}).get("login") or ""
    comment_id = comment.get("id") or 0
    pr_number = issue.get("number")
    repo_full_name = (event.get("repository") or {}).get("full_name") or ""
    if not (body and commenter and isinstance(pr_number, int) and repo_full_name):
        return None
    return repo_full_name, pr_number, commenter, body, comment_id

def _post_comment(gh: Github, repo_full_name: str, pr_number: int, body: str) -> None:
    def _post() -> None:
        issue = gh.get_repo(repo_full_name).get_issue(pr_number)
        issue.create_comment(body)

    retry_github_call(_post, retries=3, description=f"comment on #{pr_number}")

def _request_from_dispatch(args: argparse.Namespace) -> tuple[str, int, str, ParsedCommand, int] | None:
    if not (args.repo and args.pr and args.commenter):
        return None
    command = parse_command(f"@{BOT_LOGIN} fix {args.run_url} {args.hint}".strip())
    if command is None:
        return None
    return args.repo, args.pr, args.commenter, command, args.comment_id

def _request_from_event(args: argparse.Namespace) -> tuple[str, int, str, ParsedCommand, int] | None:
    if not args.event_path:
        return None
    event = json.loads(Path(args.event_path).read_text(encoding="utf-8"))
    parsed = _parse_event(event)
    if parsed is None:
        return None
    repo_full_name, pr_number, commenter, body, comment_id = parsed
    command = parse_command(body)
    if command is None:
        return None
    return repo_full_name, pr_number, commenter, command, comment_id

def _verify_runs() -> int:
    """Return the local/Docker verification repeat count."""
    return env_int(
        "CI_FIX_VERIFY_RUNS",
        DEFAULT_VERIFY_RUNS,
        minimum=1,
        maximum=_MAX_VERIFY_RUNS,
    )

@dataclass(frozen=True)
class ReviewVerdict:
    """The AI skeptic's judgment on an already-passing fix."""

    approved: bool
    reasoning: str

def _canonical_candidate_sha(
    chosen: str, candidates: tuple[PortCandidate, ...],
) -> str | None:
    """Resolve the model's chosen commit to a discovered candidate's full SHA.

    The diagnosis prompt renders candidates as short (12-char) SHAs, so the
    model echoes back a short SHA while the candidate set carries full 40-char
    SHAs. Match by prefix in either direction and return the candidate's full
    SHA, which the push path then ancestry-verifies. Returns None when the
    chosen SHA matches no candidate, or when a short prefix is ambiguous across
    more than one candidate (refuse rather than guess).
    """
    chosen = chosen.strip().lower()
    if not chosen:
        return None
    matches = {
        c.sha
        for c in candidates
        if c.sha.lower().startswith(chosen) or chosen.startswith(c.sha.lower())
    }
    if len(matches) == 1:
        return next(iter(matches))
    return None  # zero matches, or an ambiguous prefix

def _classify_failing_job(repo_dir: Path, failing_job: str) -> JobEnvironment:
    """Classify the failed job's environment from the repo's own workflows.

    Code (not the AI) decides the environment. Job names are not unique across
    workflow files: if the same name appears in more than one workflow with
    different environments, we cannot tell which produced the failure, so we
    refuse rather than guess. If all matches agree, that environment is used.
    """
    base = failing_job.split(" (")[0]  # strip matrix suffix; jobs: key is the base name
    workflows = repo_dir / ".github" / "workflows"
    if not workflows.is_dir():
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason="no .github/workflows in the repo")

    matches: list[JobEnvironment] = []
    for path in sorted(workflows.glob("*.y*ml")):
        content = _read_workflow_safely(path)
        if content is None:
            continue
        env = classify_job_environment(content, base)
        if env.env is not VerifyEnv.UNSUPPORTED:
            matches.append(env)
    if not matches:
        return JobEnvironment(
            VerifyEnv.UNSUPPORTED,
            reason=f"job {base!r} not found in any workflow, or its environment is unsupported",
        )
    if len({(m.env, m.image) for m in matches}) > 1:
        return JobEnvironment(
            VerifyEnv.UNSUPPORTED,
            reason=(
                f"job {base!r} appears in multiple workflows with different "
                "environments; cannot determine which failed, refusing"
            ),
        )
    return matches[0]

def _loop_and_push(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, plan: VerificationPlan,
    *, run_loop_func: RunLoop, git_env: dict[str, str], push_func: Push,
    verify_runs: int,
) -> FixOutcome:
    """Local/Docker: apply, verify in-loop (retry on fail), review, push on green."""
    loop = run_loop_func(
        str(repo_dir), proposal, container_image=plan.image, verify_runs=verify_runs,
    )
    if loop.handoff:
        return FixOutcome(
            kind=OutcomeKind.HANDOFF, summary=loop.detail, proposal=proposal,
            run_result=loop.run_result, review=loop.review,
            handoff_patch=loop.handoff_patch,
            other_failing_checks=proposal.other_failing_checks,
        )
    if not loop.success:
        return FixOutcome(
            kind=OutcomeKind.REFUSED, summary=loop.detail, proposal=proposal,
            run_result=loop.run_result, review=loop.review,
            other_failing_checks=proposal.other_failing_checks,
        )
    backend = backend_label(plan.env, plan.image)
    return _push(
        repo_dir, request, proposal, loop.changed_paths,
        review=loop.review, run_result=loop.run_result,
        verify_backend=backend, git_env=git_env, push_func=push_func,
    )

def _macos_fix_loop(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, plan: VerificationPlan,
    *, verifier: VerifyBackend, git_env: dict[str, str], push_func: Push,
) -> FixOutcome:
    """Apply, review, and remotely verify the fix up to N times with feedback.

    Each attempt starts from a clean tree and feeds the previous rejection or
    failed run's log tail back to the agent. The caller resets the worktree on
    exit, so this loop never has to.
    """
    feedback = ""
    last_review: Any = None
    last_summary = "no macOS verification attempt made"
    last_run_url = ""

    for _attempt in range(1, _MACOS_FIX_MAX_ATTEMPTS + 1):
        reset_worktree(str(repo_dir))

        applied, changed = apply_fix(str(repo_dir), proposal, feedback=feedback)
        if not applied:
            return _refuse(proposal, "fix not applied (agent declined or made no edits)")

        reviewed = build_and_review_patch(str(repo_dir), changed, proposal)
        last_review = reviewed.review
        if not reviewed.ok:
            if reviewed.review is None:
                return FixOutcome(
                    kind=OutcomeKind.REFUSED, summary=reviewed.detail,
                    proposal=proposal, review=reviewed.review,
                    other_failing_checks=proposal.other_failing_checks,
                )
            feedback = (
                f"A reviewer rejected your previous fix: {reviewed.review.reasoning}\n\n"
                f"Your previous diff was:\n{reviewed.patch}\n\n"
                "Address the rejection; do not reproduce the same change."
            )
            last_summary = reviewed.detail
            continue

        result = verifier.verify(str(repo_dir), plan, reviewed.patch)
        last_run_url = result.run_url
        if result.verified:
            return _push(
                repo_dir, request, proposal, changed,
                review=reviewed.review, verify_backend=backend_label(VerifyEnv.MACOS),
                macos_run_url=result.run_url, git_env=git_env, push_func=push_func,
            )
        if not result.ran:
            return FixOutcome(
                kind=OutcomeKind.REFUSED, summary=result.detail,
                proposal=proposal, review=reviewed.review, macos_run_url=result.run_url,
                other_failing_checks=proposal.other_failing_checks,
            )
        feedback = _macos_retry_feedback(result)
        last_summary = result.detail

    return FixOutcome(
        kind=OutcomeKind.REFUSED, summary=last_summary,
        proposal=proposal, review=last_review, macos_run_url=last_run_url,
        other_failing_checks=proposal.other_failing_checks,
    )

def _macos_retry_feedback(result: VerificationResult) -> str:
    lines = [
        f"The previous macOS verification run failed: {result.detail}",
    ]
    if result.run_url:
        lines.append(f"Run URL: {result.run_url}")
    if result.output_tail:
        lines.append("Output tail:")
        lines.append(result.output_tail)
    else:
        lines.append("No macOS log tail was available; inspect the run URL if needed.")
    return "\n".join(lines)

def _plan_verification(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, failed_jobs: tuple[str, ...],
) -> VerificationPlan | str:
    """Select the verification backend from the real failed job, or return a refusal reason.

    The AI's ``failing_job_hint`` must match a job that actually failed in the
    linked run; code then classifies that job's workflow environment. The AI
    never selects the environment.
    """
    job = _match_failed_job(proposal.failing_job_hint, failed_jobs)
    if job is None:
        return (
            f"The named job {proposal.failing_job_hint or '(none)'!r} is not among the failed "
            f"jobs of the linked run ({', '.join(failed_jobs) or 'none found'}); "
            "refusing rather than verifying a job that did not fail."
        )
    env = _classify_failing_job(repo_dir, job)
    if env.env is VerifyEnv.UNSUPPORTED:
        return (
            f"Cannot verify the {job!r} job in a controlled environment "
            f"({env.reason}); refusing rather than pushing an unverified fix."
        )
    return VerificationPlan(
        env=env.env,
        command=combined_command(proposal),
        workdir=proposal.workdir,
        image=env.image,
        job_name=job,
        head_sha=request.head_sha,
        target_repo=request.head_repo_full_name,
    )

def _port_and_push(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, failed_jobs: tuple[str, ...],
    *, git_env: dict[str, str], port_push_func: PortPush = commit_and_push_port,
    port_candidates: tuple[PortCandidate, ...] = (),
) -> FixOutcome:
    """Apply an already-merged upstream fix and publish it.

    PORT is the only path allowed to rely on the PR's normal CI as the
    authoritative verifier. That trust is bounded by code: the SHA must be one
    of the candidates discovered from this failure's logs (so the model cannot
    point at an arbitrary default-branch commit), the hinted job must be a real
    failed job, and the push path independently re-verifies the commit's
    ancestry. Original authorship is preserved.
    """
    job = _match_failed_job(proposal.failing_job_hint, failed_jobs)
    if job is None:
        return _refuse(
            proposal,
            f"The named job {proposal.failing_job_hint or '(none)'!r} is not among the failed "
            f"jobs of the linked run ({', '.join(failed_jobs) or 'none found'}); "
            "refusing rather than porting a fix for a job that did not fail.",
        )
    if not proposal.unstable_fix_commit.strip():
        return _refuse(proposal, "diagnosis chose PORT but did not name an upstream fix commit")

    chosen = proposal.unstable_fix_commit.strip()
    full_sha = _canonical_candidate_sha(chosen, port_candidates)
    if full_sha is None:
        return _refuse(
            proposal,
            f"The chosen commit {chosen[:12]} is not among the "
            "fixes discovered for this failure; refusing to port a commit the code "
            "did not surface as a candidate.",
        )

    try:
        commit_sha = port_push_func(
            str(repo_dir),
            head_repo_full_name=request.head_repo_full_name,
            head_branch=request.head_branch,
            head_sha=request.head_sha,
            unstable_fix_commit=full_sha,
            git_env=git_env,
        )
    except PushRefused as exc:
        return _refuse(proposal, str(exc))

    review = ReviewVerdict(
        approved=True,
        reasoning=(
            f"Ported upstream commit {full_sha[:12]} with its original "
            "authorship; this PORT path relies on the PR's normal CI as the verification authority."
        ),
    )
    return FixOutcome(
        kind=OutcomeKind.PUSHED,
        summary=f"Ported upstream fix for {proposal.failing_check}",
        proposal=proposal, review=review, commit_sha=commit_sha,
        verify_backend="upstream-port",
        other_failing_checks=proposal.other_failing_checks,
    )

def _push(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, changed_paths: tuple[str, ...],
    *, review: Any = None, run_result: Any = None, verify_backend: str = "",
    macos_run_url: str = "", git_env: dict[str, str], push_func: Push,
) -> FixOutcome:
    try:
        commit_sha = push_func(
            str(repo_dir),
            head_repo_full_name=request.head_repo_full_name,
            head_branch=request.head_branch,
            head_sha=request.head_sha,
            proposal=proposal,
            changed_paths=changed_paths,
            git_env=git_env,
        )
    except PushRefused as exc:
        return FixOutcome(
            kind=OutcomeKind.REFUSED, summary=str(exc),
            proposal=proposal, run_result=run_result, review=review, macos_run_url=macos_run_url,
            other_failing_checks=proposal.other_failing_checks,
        )
    return FixOutcome(
        kind=OutcomeKind.PUSHED,
        summary=f"Pushed fix for {proposal.failing_check}",
        proposal=proposal, run_result=run_result, review=review, commit_sha=commit_sha,
        verify_backend=verify_backend, macos_run_url=macos_run_url,
        other_failing_checks=proposal.other_failing_checks,
    )

def _read_workflow_safely(path: Path) -> str | None:
    """Read a workflow file from an untrusted checkout, or return ``None``.

    The checkout is PR-controlled, so skip symlinks (which could point outside
    the tree), cap the size, and swallow ``OSError`` rather than letting a
    crafted entry abort classification.
    """
    try:
        if path.is_symlink() or not path.is_file():
            return None
        if path.stat().st_size > _MAX_WORKFLOW_BYTES:
            return None
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None

def _refuse(proposal: FixProposal, summary: str) -> FixOutcome:
    return FixOutcome(
        kind=OutcomeKind.REFUSED, summary=summary, proposal=proposal,
        other_failing_checks=proposal.other_failing_checks,
    )

def _run_in_workspace(
    workdir: Path,
    request: FixRequest,
    failed_jobs: tuple[str, ...],
    *,
    artifact_client: ArtifactClient,
    git_env: dict[str, str],
    diagnose_func: Diagnose,
    run_loop_func: RunLoop,
    push_func: Push,
    port_push_func: PortPush,
    macos_verifier: VerifyBackend | None,
    verify_runs: int,
) -> FixOutcome:
    logs = artifact_client.download_run_logs(request.repo_full_name, request.run_id)
    if not logs:
        return FixOutcome(
            kind=OutcomeKind.REFUSED,
            summary="The run's logs have expired and can no longer be downloaded; cannot diagnose.",
        )
    logs_dir = write_logs_to_workspace(logs, workdir)

    repo_dir = workdir / "repo"
    if not shallow_clone_at_sha(request.repo_full_name, repo_dir, request.head_sha):
        return FixOutcome(
            kind=OutcomeKind.FAILED,
            summary=f"Could not clone {request.repo_full_name} at {request.head_sha[:12]}.",
        )

    port_candidates = discover_port_candidates(str(repo_dir), str(logs_dir))
    proposal = diagnose_func(
        str(logs_dir), str(repo_dir), hint=request.hint,
        port_candidates=port_candidates,
    )
    if proposal.path is FixPath.REFUSE:
        return _refuse(proposal, proposal.reasoning or "No safe fix found.")

    if proposal.path is FixPath.PORT:
        return _port_and_push(
            repo_dir, request, proposal, failed_jobs, git_env=git_env,
            port_push_func=port_push_func, port_candidates=port_candidates,
        )

    plan = _plan_verification(repo_dir, request, proposal, failed_jobs)
    if isinstance(plan, str):  # a refusal reason
        return _refuse(proposal, plan)

    if plan.env is VerifyEnv.MACOS:
        return _verify_once_and_push(
            repo_dir, request, proposal, plan,
            verifier=macos_verifier, git_env=git_env, push_func=push_func,
        )
    return _loop_and_push(
        repo_dir, request, proposal, plan,
        run_loop_func=run_loop_func, git_env=git_env, push_func=push_func,
        verify_runs=verify_runs,
    )

def _verify_once_and_push(
    repo_dir: Path, request: FixRequest, proposal: FixProposal, plan: VerificationPlan,
    *, verifier: VerifyBackend | None, git_env: dict[str, str], push_func: Push,
) -> FixOutcome:
    """macOS: apply, review, and remotely verify with bounded feedback retries.

    Any unexpected error becomes a FAILED outcome so the invocation always
    produces a PR comment.
    """
    if verifier is None:
        return _refuse(proposal, "macOS verification is not configured for this run; refusing.")
    try:
        precheck = precheck_command(proposal)
        if precheck:
            return _refuse(proposal, precheck)

        # The push path extracts an approved patch and applies it in a separate
        # clean clone, so resetting this worktree on the way out is safe
        # for every outcome, including a successful push.
        try:
            return _macos_fix_loop(
                repo_dir, request, proposal, plan,
                verifier=verifier, git_env=git_env, push_func=push_func,
            )
        finally:
            try:
                reset_worktree(str(repo_dir))
            except Exception:  # noqa: BLE001 - cleanup failure must not mask the real outcome
                logger.warning(
                    "failed to reset worktree after macOS verification", exc_info=True,
                )
    except Exception:  # noqa: BLE001 - every outcome must become a comment
        logger.exception("macOS verification raised unexpectedly")
        return FixOutcome(
            kind=OutcomeKind.FAILED,
            summary=(
                "An internal error stopped macOS verification before a fix could "
                "be confirmed; see the bot run logs for details."
            ),
            proposal=proposal, other_failing_checks=proposal.other_failing_checks,
        )

@dataclass(frozen=True)
class PortCandidate:
    """A default-branch commit that may be the missing backport fix."""

    sha: str
    subject: str
    paths: tuple[str, ...] = ()

def _candidate_from_line(repo_dir: str, line: str) -> PortCandidate:
    sha, _, subject = line.partition("\0")
    return PortCandidate(sha=sha, subject=subject, paths=_changed_paths(repo_dir, sha))

def _changed_paths(repo_dir: str, sha: str) -> tuple[str, ...]:
    try:
        out = git_output(repo_dir, "diff-tree", "--no-commit-id", "--name-only", "-r", sha)
    except subprocess.CalledProcessError:
        return ()
    return tuple(path for path in out.splitlines() if path)

def _distinctive_terms(text: str) -> tuple[str, ...]:
    seen: set[str] = set()
    terms: list[str] = []
    for raw in _TOKEN_RE.findall(text):
        term = raw.lower().replace("-", "")
        if term in _NOISY_TOKENS or term in seen:
            continue
        seen.add(term)
        terms.append(raw)
        if len(terms) >= _MAX_TERMS:
            break
    return tuple(terms)

def _ensure_default_ref(repo_dir: str, default_branch: str) -> str:
    ref = f"origin/{default_branch}"
    try:
        git_output(repo_dir, "rev-parse", "--verify", ref)
        return ref
    except subprocess.CalledProcessError:
        run_git(
            repo_dir, "fetch", "origin",
            f"refs/heads/{default_branch}:refs/remotes/origin/{default_branch}",
        )
        return ref

def _extract_repo_paths(repo_dir: str, text: str) -> tuple[str, ...]:
    root = Path(repo_dir)
    found: set[str] = set()
    for match in _PATH_RE.findall(text):
        path = match.strip("`'\".,:;()[]{}")
        if path and (root / path).exists():
            found.add(path)
    return tuple(sorted(found))

def _grep_candidates(
    repo_dir: str, base: str, ref: str, terms: tuple[str, ...], *, limit: int,
) -> tuple[PortCandidate, ...]:
    if limit <= 0:
        return ()
    candidates: list[PortCandidate] = []
    for term in terms:
        try:
            out = git_output(
                repo_dir, "log", "--format=%H%x00%s", "--regexp-ignore-case",
                f"--grep={term}", f"{base}..{ref}",
            )
        except subprocess.CalledProcessError:
            continue
        for line in out.splitlines():
            if not line:
                continue
            candidates.append(_candidate_from_line(repo_dir, line))
            if len(candidates) >= limit:
                return tuple(candidates)
    return tuple(candidates)

def _path_candidates(
    repo_dir: str, base: str, ref: str, paths: tuple[str, ...], *, limit: int,
) -> tuple[PortCandidate, ...]:
    if not paths or limit <= 0:
        return ()
    try:
        out = git_output(
            repo_dir, "log", "--format=%H%x00%s", f"{base}..{ref}", "--", *paths,
        )
    except subprocess.CalledProcessError:
        return ()
    lines = [line for line in out.splitlines() if line][:limit]
    return tuple(_candidate_from_line(repo_dir, line) for line in lines)

def _read_logs(logs_dir: str) -> str:
    root = Path(logs_dir)
    chunks: list[str] = []
    remaining = _MAX_LOG_BYTES
    for path in sorted(p for p in root.iterdir() if p.is_file()):
        if remaining <= 0:
            break
        data = path.read_bytes()[:remaining]
        chunks.append(data.decode("utf-8", errors="replace"))
        remaining -= len(data)
    return "\n".join(chunks)

def discover_port_candidates(
    repo_dir: str,
    logs_dir: str,
    *,
    default_branch: str = "",
    max_candidates: int = _MAX_CANDIDATES,
) -> tuple[PortCandidate, ...]:
    """Return likely upstream-fix candidates from ``default_branch``.

    Candidates come from two deterministic signals extracted from the failing
    logs: repository paths mentioned in the output, and distinctive words in
    the failure text. Path history is preferred, then subject/body grep fills in
    cases where a validator failure names a subsystem rather than a source file.
    Any git failure yields no candidates; diagnosis can still proceed normally.

    ``default_branch`` defaults to the clone's actual default (resolved from
    ``origin/HEAD``), so this works for repos whose default is ``main`` as well
    as ``unstable``.
    """
    try:
        branch = default_branch or resolve_default_branch(repo_dir)
        ref = _ensure_default_ref(repo_dir, branch)
        base = git_output(repo_dir, "merge-base", "HEAD", ref).strip()
    except (subprocess.CalledProcessError, OSError) as exc:
        logger.info("Could not prepare default-branch candidate search: %s", exc)
        return ()

    log_text = _read_logs(logs_dir)
    paths = _extract_repo_paths(repo_dir, log_text)
    terms = _distinctive_terms(log_text)

    candidates: dict[str, PortCandidate] = {}
    for candidate in _path_candidates(repo_dir, base, ref, paths, limit=max_candidates):
        candidates.setdefault(candidate.sha, candidate)
        if len(candidates) >= max_candidates:
            return tuple(candidates.values())
    remaining = max_candidates - len(candidates)
    for candidate in _grep_candidates(repo_dir, base, ref, terms, limit=remaining):
        candidates.setdefault(candidate.sha, candidate)
        if len(candidates) >= max_candidates:
            break
    return tuple(candidates.values())

def resolve_default_branch(repo_dir: str) -> str:
    """Resolve the remote's default branch, e.g. ``main`` or ``unstable``.

    Reads ``origin/HEAD`` (the symbolic ref a clone records for the remote's
    default). Falls back to a query against the remote, then to ``unstable`` so
    a detached or unusual clone still degrades to the common case.
    """
    try:
        ref = git_output(repo_dir, "rev-parse", "--abbrev-ref", "origin/HEAD").strip()
        if ref.startswith("origin/"):
            return ref[len("origin/"):]
    except subprocess.CalledProcessError:
        pass
    try:
        # origin/HEAD is not always populated by a shallow clone; ask the remote.
        out = git_output(repo_dir, "remote", "show", "origin")
        for line in out.splitlines():
            if "HEAD branch:" in line:
                return line.split("HEAD branch:", 1)[1].strip()
    except subprocess.CalledProcessError:
        pass
    return DEFAULT_BRANCH_FALLBACK

def _apply_patch(repo_dir: str, patch: str) -> None:
    try:
        run_git(repo_dir, "apply", "--index", "--whitespace=nowarn", "-", input=patch)
    except subprocess.CalledProcessError as exc:
        raise PushRefused(
            f"Refusing to push: approved patch did not apply cleanly: {(exc.stderr or '')[:300]}"
        ) from exc

def _clone_clean(head_repo_full_name: str, dest: Path) -> None:
    url = github_https_url(head_repo_full_name)
    try:
        run_git(None, "clone", "--filter=blob:none", url, str(dest))
    except subprocess.CalledProcessError as exc:
        raise PushRefused(f"Refusing to push: clone failed: {(exc.stderr or '')[:300]}") from exc

def _commit_subject(proposal: FixProposal) -> str:
    source = _source_file_from_root_cause(proposal.root_cause)
    if source and _looks_like_build_failure(proposal):
        return _fit_subject(f"Fix {source} build failure")

    check = _clean_failing_check(proposal.failing_check)
    if not check:
        return "Fix CI failure"
    return _fit_subject(f"Fix {check}")

def _fit_subject(subject: str) -> str:
    """Trim to Git's conventional 72-char subject length at a word boundary."""
    subject = " ".join(subject.split())
    if len(subject) <= 72:
        return subject
    clipped = subject[:72].rstrip()
    if " " in clipped:
        clipped = clipped.rsplit(" ", 1)[0]
    return clipped.rstrip(" .")

def _format_commit_body(body: str) -> str:
    return "\n\n".join(
        textwrap.fill(
            paragraph.strip(),
            width=72,
            break_long_words=False,
            break_on_hyphens=False,
        )
        for paragraph in body.strip().split("\n\n")
        if paragraph.strip()
    )

def _is_ancestor(repo_dir: str, maybe_ancestor: str, descendant: str) -> bool:
    """True if ``maybe_ancestor`` is an ancestor of ``descendant`` (or equal)."""
    try:
        git_output(repo_dir, "merge-base", "--is-ancestor", maybe_ancestor, descendant)
        return True
    except subprocess.CalledProcessError:
        return False

def _is_valid_branch_name(branch: str) -> bool:
    try:
        run_git(None, "check-ref-format", "--branch", branch)
    except subprocess.CalledProcessError:
        return False
    return True

def _looks_like_build_failure(proposal: FixProposal) -> bool:
    check = proposal.failing_check.strip().lower()
    if check.startswith(("make ", "cmake ", "ninja ", "clang ", "gcc ", "cc ")):
        return True
    text = f"{check} {proposal.root_cause}".lower()
    return any(
        marker in text
        for marker in (
            "compile",
            "compiler",
            "clang",
            "gcc",
            "-werror",
        )
    )

def _source_file_from_root_cause(root_cause: str) -> str:
    match = _SOURCE_LOCATION_RE.search(root_cause)
    if not match:
        return ""
    return Path(match.group(1)).name

def _staged_paths(repo_dir: str) -> tuple[str, ...]:
    out = git_output(repo_dir, "diff", "--cached", "--name-only", "-z", "HEAD")
    return tuple(sorted(path for path in out.split("\0") if path))

def _needs_shell_grouping(command: str) -> bool:
    """True when a command has list separators that would bind looser than &&."""
    return ";" in command or "\n" in command

def _shell_group(command: str) -> str:
    """Group a shell command so its whole exit status participates in ``&&``."""
    return "(\n" + command.strip() + "\n)"

def build_and_review_patch(
    repo_dir: str,
    changed: tuple[str, ...],
    proposal: FixProposal,
    *,
    review_func: ReviewFix = review_fix,
) -> PatchReview:
    """Build the approved patch and skeptically review it, with shared guards.

    Enforces the same patch-size ceiling and skeptic review for every backend,
    so a fix verified on macOS gets exactly the safety the local path gets.
    Returns ``ok=False`` with a reason for an empty or oversized patch or a
    rejected review.
    """
    try:
        patch = build_approved_patch(repo_dir, changed)
    except EmptyPatch:
        return PatchReview(ok=False, detail="fix produced no change to review")
    if len(patch) > MAX_REVIEWABLE_PATCH_CHARS:
        return PatchReview(
            ok=False,
            detail=(
                f"fix is too large to review safely "
                f"({len(patch)} > {MAX_REVIEWABLE_PATCH_CHARS} chars); refusing"
            ),
        )
    review = review_func(repo_dir, proposal, patch)
    if not review.approved:
        return PatchReview(ok=False, patch=patch, review=review,
                           detail=f"review rejected the fix: {review.reasoning}")
    return PatchReview(ok=True, patch=patch, review=review)

def combined_command(proposal: FixProposal) -> str:
    """Chain build + test into one recipe for the runner."""
    parts = [p for p in (proposal.build_command, proposal.verify_command) if p.strip()]
    if len(parts) > 1 and any(_needs_shell_grouping(p) for p in parts):
        return " && ".join(_shell_group(p) for p in parts)
    return " && ".join(parts)

def precheck_command(proposal: FixProposal) -> str:
    """Return a refusal reason if the proposal's verify command is unusable.

    Empty string means the command is acceptable to run. Shared by every
    backend so the same guards (a verify command must exist, and it must not be
    a no-op that proves nothing) apply regardless of where verification runs.
    """
    if not proposal.verify_command.strip():
        return "no command to verify the fix; refusing to push an unverified change"
    combined = combined_command(proposal)
    if _is_noop_command(combined):
        return (
            "verification command has no build or test signal "
            f"({combined!r}); refusing to push on a no-op check"
        )
    return ""

def reproduced_the_named_failure(proposal: FixProposal, result: RunResult) -> bool:
    """Return True when the failed baseline output names the intended check.

    The match is evidence only. Build and lint failures often omit the job or
    check name from compiler output, so absence is logged by the caller rather
    than treated as a hard mismatch.
    """
    check = proposal.failing_check.strip()
    if len(check) < _MIN_MATCHABLE_CHECK_CHARS:
        return False
    return check.lower() in result.output_tail.lower()

def review_fix(repo_dir: str, proposal: FixProposal, diff: str) -> ReviewVerdict:
    """Run the read-only skeptic review over the complete applied diff.

    The caller guarantees ``diff`` is within ``MAX_REVIEWABLE_PATCH_CHARS``, so
    the reviewer always sees the entire change that will be pushed - never a
    truncation that could hide edits past a byte limit.
    """
    prompt = _REVIEW_PROMPT_TEMPLATE.format(
        failing_check=proposal.failing_check,
        root_cause=proposal.root_cause,
        diff=diff,
    )
    result = run_agent("ci_fix_diagnose_readonly", prompt, cwd=repo_dir)
    if result.returncode != 0:
        return ReviewVerdict(approved=False, reasoning=f"review agent failed (rc={result.returncode})")
    payload = extract_json_object(result.stdout, required_key="approved")
    if payload is None:
        return ReviewVerdict(approved=False, reasoning="review returned no verdict")
    approved = payload.get("approved") is True
    reasoning = payload.get("reasoning")
    return ReviewVerdict(
        approved=approved,
        reasoning=reasoning.strip() if isinstance(reasoning, str) else "",
    )

def _resolve_workdir(repo_dir: str, workdir: str) -> Path | None:
    """Resolve ``workdir`` under ``repo_dir``, rejecting any escape."""
    repo_root = Path(repo_dir).resolve()
    if not repo_root.is_dir():
        return None
    candidate = (repo_root / workdir).resolve() if workdir else repo_root
    if repo_root != candidate and repo_root not in candidate.parents:
        return None
    if not candidate.is_dir():
        return None
    return candidate

def _tail(text: str) -> str:
    text = strip_ansi(text)
    if len(text) <= _OUTPUT_TAIL_CHARS:
        return text
    return "…[truncated]…\n" + text[-_OUTPUT_TAIL_CHARS:]

def _verification_shell() -> tuple[str, ...]:
    """Return the local shell used for non-container verification commands."""
    bash = shutil.which("bash")
    if bash:
        return (bash, "-c")
    return ("/bin/sh", "-c")

@dataclass(frozen=True)
class FailedJob:
    """A job that did not succeed in the linked CI run (owned by code)."""

    name: str
    conclusion: str

class MacosVerifier:
    """Dispatches and waits on the agent-owned ``verify-macos`` job."""

    def __init__(
        self,
        github_client: Any,
        *,
        agent_repo_full_name: str,
        ref: str = "main",
        timeout: int = _DEFAULT_TIMEOUT_S,
        artifact_client: ArtifactClient | None = None,
    ) -> None:
        self._gh = github_client
        self._agent_repo = agent_repo_full_name
        self._ref = ref
        self._timeout = timeout
        self._artifact_client = artifact_client

    def verify(self, repo_dir: str, plan: VerificationPlan, patch: str) -> VerificationResult:
        """Verify ``patch`` against ``plan.head_sha`` on a macOS runner."""
        encoded = base64.b64encode(patch.encode("utf-8")).decode("ascii")
        if len(encoded) > _MAX_PATCH_BYTES:
            return VerificationResult(
                verified=False, ran=False,
                detail=(
                    f"patch is too large for macOS dispatch verification "
                    f"({len(encoded)} > {_MAX_PATCH_BYTES} bytes); refusing"
                ),
            )

        token = uuid.uuid4().hex
        dispatched_at = time.time()
        if not self._dispatch(plan, encoded, token):
            return VerificationResult(
                verified=False, ran=False,
                detail="could not dispatch the macOS verification job",
            )

        run = self._await_run(token, since=dispatched_at)
        if run is None:
            return VerificationResult(
                verified=False, ran=False,
                detail=f"macOS verification did not complete within {self._timeout}s",
            )
        url = str(getattr(run, "html_url", "") or "")
        conclusion = str(getattr(run, "conclusion", "") or "")
        if conclusion == "success":
            return VerificationResult(
                verified=True, ran=True, detail="targeted macOS verification passed", run_url=url,
            )
        output_tail = self._run_log_tail(run)
        return VerificationResult(
            verified=False, ran=True,
            detail=f"targeted macOS verification did not pass ({conclusion})", run_url=url,
            output_tail=output_tail,
        )

    def _run_log_tail(self, run: Any) -> str:
        """Best-effort tail of a failed run's logs for retry feedback.

        Uses ``ArtifactClient.download_run_logs``, which follows GitHub's 302 to
        blob storage without leaking the token and caps the uncompressed size.
        Returns an empty string when no client is configured or the logs are
        unavailable; log feedback is helpful, not required.
        """
        if self._artifact_client is None:
            return ""
        run_id = getattr(run, "id", None)
        if not isinstance(run_id, int):
            return ""
        try:
            logs = self._artifact_client.download_run_logs(self._agent_repo, run_id)
        except Exception as exc:  # noqa: BLE001 - log feedback is helpful, not required
            logger.warning("downloading verify-macos logs failed: %s", exc)
            return ""
        return _tail_log_map(logs)

    def _dispatch(self, plan: VerificationPlan, encoded_patch: str, token: str) -> bool:
        command = plan.command
        if not plan.workdir.strip():
            command = normalize_macos_verify_command(plan.command)
        if command != plan.command:
            logger.info("Normalized macOS verification command: %s", command)
        inputs = {
            "target_repo": plan.target_repo,
            "head_sha": plan.head_sha,
            "patch_b64": encoded_patch,
            "verify_command": command,
            "workdir": plan.workdir,
            "correlation": token,
        }

        def _do() -> bool:
            repo = self._gh.get_repo(self._agent_repo)
            workflow = repo.get_workflow(VERIFY_MACOS_WORKFLOW)
            return bool(workflow.create_dispatch(self._ref, inputs))

        try:
            return retry_github_call(_do, retries=2, description="dispatch verify-macos")
        except Exception as exc:  # noqa: BLE001 - dispatch failure is a clean refusal
            logger.warning("verify-macos dispatch failed: %s", exc)
            return False

    def _await_run(self, token: str, *, since: float) -> Any | None:
        """Find the run carrying ``token`` and poll it to completion."""
        deadline = time.time() + self._timeout
        run = None
        while time.time() < deadline:
            if run is None:
                run = self._find_run(token, since=since)
            else:
                run = self._reload(run)
            if run is not None and str(getattr(run, "status", "")) == "completed":
                return run
            time.sleep(_POLL_INTERVAL_S)
        if run is not None:
            run = self._reload(run)
            if str(getattr(run, "status", "")) == "completed":
                return run
        return None

    def _find_run(self, token: str, *, since: float) -> Any | None:
        marker = f"[token:{token}]"

        def _list() -> list[Any]:
            repo = self._gh.get_repo(self._agent_repo)
            workflow = repo.get_workflow(VERIFY_MACOS_WORKFLOW)
            return list(workflow.get_runs()[:20])

        try:
            runs = retry_github_call(_list, retries=2, description="list verify-macos runs")
        except Exception as exc:  # noqa: BLE001
            logger.warning("listing verify-macos runs failed: %s", exc)
            return None
        for run in runs:
            # GitHub exposes the custom run-name as display_title; name is the
            # workflow name. The token marker lives in the run-name.
            haystack = (
                f"{getattr(run, 'display_title', '') or ''} "
                f"{getattr(run, 'name', '') or ''}"
            )
            if marker not in haystack:
                continue
            if not _run_created_after(run, since):
                # A run bearing the token but created before we dispatched is
                # not ours; never trust a pre-existing run's conclusion.
                continue
            return run
        return None

    def _reload(self, run: Any) -> Any:
        def _get() -> Any:
            return self._gh.get_repo(self._agent_repo).get_workflow_run(run.id)

        try:
            return retry_github_call(_get, retries=2, description="reload verify-macos run")
        except Exception as exc:  # noqa: BLE001
            logger.warning("reloading verify-macos run failed: %s", exc)
            return run

def _await_run(self, token: str, *, since: float) -> Any | None:
    """Find the run carrying ``token`` and poll it to completion."""
    deadline = time.time() + self._timeout
    run = None
    while time.time() < deadline:
        if run is None:
            run = self._find_run(token, since=since)
        else:
            run = self._reload(run)
        if run is not None and str(getattr(run, "status", "")) == "completed":
            return run
        time.sleep(_POLL_INTERVAL_S)
    if run is not None:
        run = self._reload(run)
        if str(getattr(run, "status", "")) == "completed":
            return run
    return None

def _dispatch(self, plan: VerificationPlan, encoded_patch: str, token: str) -> bool:
    command = plan.command
    if not plan.workdir.strip():
        command = normalize_macos_verify_command(plan.command)
    if command != plan.command:
        logger.info("Normalized macOS verification command: %s", command)
    inputs = {
        "target_repo": plan.target_repo,
        "head_sha": plan.head_sha,
        "patch_b64": encoded_patch,
        "verify_command": command,
        "workdir": plan.workdir,
        "correlation": token,
    }

    def _do() -> bool:
        repo = self._gh.get_repo(self._agent_repo)
        workflow = repo.get_workflow(VERIFY_MACOS_WORKFLOW)
        return bool(workflow.create_dispatch(self._ref, inputs))

    try:
        return retry_github_call(_do, retries=2, description="dispatch verify-macos")
    except Exception as exc:  # noqa: BLE001 - dispatch failure is a clean refusal
        logger.warning("verify-macos dispatch failed: %s", exc)
        return False

def _find_run(self, token: str, *, since: float) -> Any | None:
    marker = f"[token:{token}]"

    def _list() -> list[Any]:
        repo = self._gh.get_repo(self._agent_repo)
        workflow = repo.get_workflow(VERIFY_MACOS_WORKFLOW)
        return list(workflow.get_runs()[:20])

    try:
        runs = retry_github_call(_list, retries=2, description="list verify-macos runs")
    except Exception as exc:  # noqa: BLE001
        logger.warning("listing verify-macos runs failed: %s", exc)
        return None
    for run in runs:
        # GitHub exposes the custom run-name as display_title; name is the
        # workflow name. The token marker lives in the run-name.
        haystack = (
            f"{getattr(run, 'display_title', '') or ''} "
            f"{getattr(run, 'name', '') or ''}"
        )
        if marker not in haystack:
            continue
        if not _run_created_after(run, since):
            # A run bearing the token but created before we dispatched is
            # not ours; never trust a pre-existing run's conclusion.
            continue
        return run
    return None

def _reload(self, run: Any) -> Any:
    def _get() -> Any:
        return self._gh.get_repo(self._agent_repo).get_workflow_run(run.id)

    try:
        return retry_github_call(_get, retries=2, description="reload verify-macos run")
    except Exception as exc:  # noqa: BLE001
        logger.warning("reloading verify-macos run failed: %s", exc)
        return run

def verify(self, repo_dir: str, plan: VerificationPlan, patch: str) -> VerificationResult:
    """Verify ``patch`` against ``plan.head_sha`` on a macOS runner."""
    encoded = base64.b64encode(patch.encode("utf-8")).decode("ascii")
    if len(encoded) > _MAX_PATCH_BYTES:
        return VerificationResult(
            verified=False, ran=False,
            detail=(
                f"patch is too large for macOS dispatch verification "
                f"({len(encoded)} > {_MAX_PATCH_BYTES} bytes); refusing"
            ),
        )

    token = uuid.uuid4().hex
    dispatched_at = time.time()
    if not self._dispatch(plan, encoded, token):
        return VerificationResult(
            verified=False, ran=False,
            detail="could not dispatch the macOS verification job",
        )

    run = self._await_run(token, since=dispatched_at)
    if run is None:
        return VerificationResult(
            verified=False, ran=False,
            detail=f"macOS verification did not complete within {self._timeout}s",
        )
    url = str(getattr(run, "html_url", "") or "")
    conclusion = str(getattr(run, "conclusion", "") or "")
    if conclusion == "success":
        return VerificationResult(
            verified=True, ran=True, detail="targeted macOS verification passed", run_url=url,
        )
    output_tail = self._run_log_tail(run)
    return VerificationResult(
        verified=False, ran=True,
        detail=f"targeted macOS verification did not pass ({conclusion})", run_url=url,
        output_tail=output_tail,
    )

def _has_make_directory(tokens: list[str]) -> bool:
    for index, token in enumerate(tokens[1:], start=1):
        if token == "-C" and index + 1 < len(tokens):
            return True
        if token.startswith("-C") and token != "-C":
            return True
        if token == "--directory" and index + 1 < len(tokens):
            return True
        if token.startswith("--directory="):
            return True
    return False

def _rewrite_make_command(match: re.Match[str]) -> str:
    prefix = match.group("prefix")
    make_command = match.group("command")
    try:
        tokens = shlex.split(make_command)
    except ValueError:
        return match.group(0)
    if len(tokens) < 2 or tokens[0] != "make" or _has_make_directory(tokens):
        return match.group(0)

    rewritten = False
    args: list[str] = []
    for token in tokens[1:]:
        target = _ROOT_SRC_OBJECT_RE.match(token)
        if target:
            args.append(target.group("target"))
            rewritten = True
        else:
            args.append(token)
    if not rewritten:
        return match.group(0)
    return f"{prefix}{shlex.join(['make', '-C', 'src', *args])}"

def _run_created_after(run: Any, since: float) -> bool:
    """True if ``run`` was plausibly created for this dispatch (token + recency).

    Allows ``_CREATED_AT_TOLERANCE_S`` of skew before ``since`` so a same-second
    or slightly-skewed run is not wrongly judged stale. Runs whose creation time
    cannot be read are treated as not-after (the token match still gates).
    """
    created = getattr(run, "created_at", None)
    if created is None:
        return False
    try:
        return created.timestamp() >= since - _CREATED_AT_TOLERANCE_S
    except (AttributeError, TypeError, ValueError):
        return False

def _tail_log_map(logs: dict[str, bytes]) -> str:
    """Return a bounded tail of the verify step's log for retry feedback.

    The step that runs the candidate command is what a retry needs, so its log
    is tailed directly; joining other (possibly large) members first would push
    the actual failure out of the ``_MAX_LOG_TAIL_CHARS`` window. Only when that
    step is absent do we fall back to the remaining members as context.
    """
    if not logs:
        return ""

    step = next((name for name in sorted(logs) if _VERIFY_STEP_MARKER in name), None)
    if step is not None:
        return _tail_text(logs[step].decode("utf-8", errors="replace"))

    combined = "\n".join(
        f"===== {name} =====\n{logs[name].decode('utf-8', errors='replace')}"
        for name in sorted(logs)
    )
    return _tail_text(combined)

def _tail_text(text: str) -> str:
    if len(text) <= _MAX_LOG_TAIL_CHARS:
        return text
    return "[truncated]\n" + text[-_MAX_LOG_TAIL_CHARS:]

def _container_image(job: dict[str, Any]) -> str:
    container = job.get("container")
    if isinstance(container, str):
        image = container.strip()
    elif isinstance(container, dict) and isinstance(container.get("image"), str):
        image = container["image"].strip()
    else:
        return ""
    if "${{" in image or not _IMAGE_RE.fullmatch(image):
        return ""
    return image

def classify_job_environment(workflow_yaml: str, job_id: str) -> JobEnvironment:
    """Classify the runner environment of ``job_id`` in ``workflow_yaml``.

    Returns a ``JobEnvironment``; ``env`` is UNSUPPORTED (with a reason)
    whenever the job's environment cannot be determined safely. Never raises for
    malformed input - a parse failure is reported as UNSUPPORTED.
    """
    try:
        doc = yaml.safe_load(workflow_yaml)
    except yaml.YAMLError as exc:
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason=f"workflow YAML did not parse: {exc}")
    if not isinstance(doc, dict):
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason="workflow root is not a mapping")

    jobs = doc.get("jobs")
    if not isinstance(jobs, dict) or job_id not in jobs:
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason=f"job {job_id!r} not found in workflow")
    job = jobs[job_id]
    if not isinstance(job, dict):
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason=f"job {job_id!r} is not a mapping")

    env = _classify_env(job)
    if env is VerifyEnv.UNSUPPORTED:
        return JobEnvironment(VerifyEnv.UNSUPPORTED, reason=f"unsupported runner: {job.get('runs-on')!r}")
    if env is VerifyEnv.DOCKER:
        image = _container_image(job)
        if not image:
            return JobEnvironment(
                VerifyEnv.UNSUPPORTED,
                reason="container image is dynamic or malformed; cannot run it safely",
            )
        return JobEnvironment(VerifyEnv.DOCKER, image=image)
    return JobEnvironment(env)

def _build() -> None:
    graph = write_graph(REPO_ROOT, GRAPH_PATH)
    meta = graph["meta"]
    confidence = meta["edgeConfidence"]
    print(f"wrote {GRAPH_PATH.relative_to(REPO_ROOT)}")
    print(
        f"  {meta['moduleCount']} modules, {meta['nodeCount']} symbols, "
        f"{meta['edgeCount']} call edges"
    )
    for level in ("exact", "inferred", "ambiguous"):
        if level in confidence:
            print(f"  {level:<10} {confidence[level]}")

def _serve(port: int) -> None:
    handler = functools.partial(
        http.server.SimpleHTTPRequestHandler, directory=str(SITE_DIR)
    )
    socketserver.TCPServer.allow_reuse_address = True
    with socketserver.TCPServer(("127.0.0.1", port), handler) as httpd:
        print(f"code map on http://127.0.0.1:{port}/ (ctrl-c to stop)")
        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            print()

class CallResolver:
    """Resolves call sites to internal definitions, with a confidence label."""

    def __init__(self, modules: dict[str, ModuleInfo]) -> None:
        self.modules = modules
        self.by_name: dict[str, list[Definition]] = {}
        for module in modules.values():
            for definition in module.definitions.values():
                self.by_name.setdefault(definition.name, []).append(definition)

    def resolve_name(self, module: ModuleInfo, name: str) -> tuple[list[str], str]:
        """Resolve a bare ``name(...)`` call."""
        if name in module.definitions:
            return [module.definitions[name].node_id], "exact"

        target = module.imports.get(name)
        if target and ":" in target:
            target_module, symbol = target.split(":", 1)
            owner = self.modules.get(target_module)
            if owner and symbol in owner.definitions:
                return [owner.definitions[symbol].node_id], "exact"
        elif target and target in self.modules:
            owner = self.modules[target]
            if name in owner.definitions:
                return [owner.definitions[name].node_id], "exact"

        return [], "external"

    def resolve_attribute(
        self,
        module: ModuleInfo,
        node: ast.Attribute,
        class_name: str | None,
    ) -> tuple[list[str], str]:
        """Resolve ``something.attr(...)``."""
        attr = node.attr
        value = node.value

        if isinstance(value, ast.Name):
            base = value.id

            if base == "self" and class_name:
                owned = module.definitions.get(f"{class_name}.{attr}")
                if owned:
                    return [owned.node_id], "exact"
                inherited = self._resolve_inherited(module, class_name, attr)
                if inherited:
                    return [inherited], "exact"

            dotted = module.imports.get(base)
            if dotted:
                owner = self.modules.get(dotted)
                if owner and attr in owner.definitions:
                    return [owner.definitions[attr].node_id], "exact"
                if ":" in dotted:
                    target_module, symbol = dotted.split(":", 1)
                    owner = self.modules.get(target_module)
                    if owner:
                        member = owner.definitions.get(f"{symbol}.{attr}")
                        if member:
                            return [member.node_id], "exact"
                    submodule = self.modules.get(f"{target_module}.{symbol}")
                    if submodule and attr in submodule.definitions:
                        return [submodule.definitions[attr].node_id], "exact"

        flattened = _unparse(value)
        if flattened in self.modules and attr in self.modules[flattened].definitions:
            return [self.modules[flattened].definitions[attr].node_id], "exact"

        return self._infer_by_name(attr)

    def _resolve_inherited(
        self, module: ModuleInfo, class_name: str, attr: str
    ) -> str | None:
        owner = module.definitions.get(class_name)
        if not owner:
            return None
        for base in owner.bases:
            candidate = module.definitions.get(f"{base}.{attr}")
            if candidate:
                return candidate.node_id
        return None

    def _infer_by_name(self, attr: str) -> tuple[list[str], str]:
        """Last resort: match the attribute against known method names."""
        candidates = [d for d in self.by_name.get(attr, []) if d.kind == "method"]
        if len(candidates) == 1:
            return [candidates[0].node_id], "inferred"
        if 1 < len(candidates) <= MAX_AMBIGUOUS_EDGES:
            return [d.node_id for d in candidates], "ambiguous"
        return [], "external"

def __init__(self, modules: dict[str, ModuleInfo]) -> None:
    self.modules = modules
    self.by_name: dict[str, list[Definition]] = {}
    for module in modules.values():
        for definition in module.definitions.values():
            self.by_name.setdefault(definition.name, []).append(definition)

def _infer_by_name(self, attr: str) -> tuple[list[str], str]:
    """Last resort: match the attribute against known method names."""
    candidates = [d for d in self.by_name.get(attr, []) if d.kind == "method"]
    if len(candidates) == 1:
        return [candidates[0].node_id], "inferred"
    if 1 < len(candidates) <= MAX_AMBIGUOUS_EDGES:
        return [d.node_id for d in candidates], "ambiguous"
    return [], "external"

def _resolve_inherited(
    self, module: ModuleInfo, class_name: str, attr: str
) -> str | None:
    owner = module.definitions.get(class_name)
    if not owner:
        return None
    for base in owner.bases:
        candidate = module.definitions.get(f"{base}.{attr}")
        if candidate:
            return candidate.node_id
    return None

def resolve_attribute(
    self,
    module: ModuleInfo,
    node: ast.Attribute,
    class_name: str | None,
) -> tuple[list[str], str]:
    """Resolve ``something.attr(...)``."""
    attr = node.attr
    value = node.value

    if isinstance(value, ast.Name):
        base = value.id

        if base == "self" and class_name:
            owned = module.definitions.get(f"{class_name}.{attr}")
            if owned:
                return [owned.node_id], "exact"
            inherited = self._resolve_inherited(module, class_name, attr)
            if inherited:
                return [inherited], "exact"

        dotted = module.imports.get(base)
        if dotted:
            owner = self.modules.get(dotted)
            if owner and attr in owner.definitions:
                return [owner.definitions[attr].node_id], "exact"
            if ":" in dotted:
                target_module, symbol = dotted.split(":", 1)
                owner = self.modules.get(target_module)
                if owner:
                    member = owner.definitions.get(f"{symbol}.{attr}")
                    if member:
                        return [member.node_id], "exact"
                submodule = self.modules.get(f"{target_module}.{symbol}")
                if submodule and attr in submodule.definitions:
                    return [submodule.definitions[attr].node_id], "exact"

    flattened = _unparse(value)
    if flattened in self.modules and attr in self.modules[flattened].definitions:
        return [self.modules[flattened].definitions[attr].node_id], "exact"

    return self._infer_by_name(attr)

def resolve_name(self, module: ModuleInfo, name: str) -> tuple[list[str], str]:
    """Resolve a bare ``name(...)`` call."""
    if name in module.definitions:
        return [module.definitions[name].node_id], "exact"

    target = module.imports.get(name)
    if target and ":" in target:
        target_module, symbol = target.split(":", 1)
        owner = self.modules.get(target_module)
        if owner and symbol in owner.definitions:
            return [owner.definitions[symbol].node_id], "exact"
    elif target and target in self.modules:
        owner = self.modules[target]
        if name in owner.definitions:
            return [owner.definitions[name].node_id], "exact"

    return [], "external"

def _definition_ast(
    module: ModuleInfo, definition: Definition
) -> ast.FunctionDef | ast.AsyncFunctionDef | None:
    """Find the AST node for an already-indexed definition."""
    for node in ast.walk(module.tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        if node.name != definition.name:
            continue
        if _definition_start(node) == definition.line:
            return node
    return None

def _definition_start(
    node: ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef,
) -> int:
    """First line of a definition, counting any decorators above it."""
    lines = [node.lineno] + [decorator.lineno for decorator in node.decorator_list]
    return min(lines)

def _external_label(node: ast.Call) -> str | None:
    """Human-readable label for a call that leaves the agent's own code."""
    func = node.func
    if isinstance(func, ast.Name):
        if func.id in NOISE_EXTERNALS:
            return None
        return func.id
    if isinstance(func, ast.Attribute):
        root = func.value
        while isinstance(root, ast.Attribute):
            root = root.value
        if isinstance(root, ast.Name):
            if root.id == "self":
                return None
            label = f"{root.id}.{func.attr}"
            if root.id in NOTABLE_EXTERNAL_ROOTS:
                return label
            return label
        return func.attr
    return None

def _first_paragraph(docstring: str | None) -> str:
    if not docstring:
        return ""
    lines: list[str] = []
    for raw in docstring.strip().splitlines():
        stripped = raw.strip()
        if not stripped:
            break
        lines.append(stripped)
    return " ".join(lines)

def _format_argument(arg: ast.arg, default: ast.expr | None) -> str:
    rendered = arg.arg
    annotation = _unparse(arg.annotation)
    if annotation:
        rendered += f": {annotation}"
    if default is not None:
        separator = " = " if annotation else "="
        rendered += f"{separator}{_unparse(default)}"
    return rendered

def _format_signature(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
    args = node.args
    positional = list(getattr(args, "posonlyargs", [])) + list(args.args)
    defaults: list[ast.expr | None] = list(args.defaults)
    padding: list[ast.expr | None] = [None] * (len(positional) - len(defaults))
    positional_defaults = padding + defaults

    parts: list[str] = []
    posonly_count = len(getattr(args, "posonlyargs", []))
    for index, (arg, default) in enumerate(zip(positional, positional_defaults)):
        parts.append(_format_argument(arg, default))
        if posonly_count and index == posonly_count - 1:
            parts.append("/")

    if args.vararg is not None:
        parts.append(f"*{_format_argument(args.vararg, None)}")
    elif args.kwonlyargs:
        parts.append("*")

    for arg, default in zip(args.kwonlyargs, args.kw_defaults):
        parts.append(_format_argument(arg, default))

    if args.kwarg is not None:
        parts.append(f"**{_format_argument(args.kwarg, None)}")

    returns = _unparse(node.returns)
    suffix = f" -> {returns}" if returns else ""
    return f"{node.name}({', '.join(parts)}){suffix}"

def _is_main_guard(node: ast.If) -> bool:
    test = node.test
    if not isinstance(test, ast.Compare) or not isinstance(test.left, ast.Name):
        return False
    if test.left.id != "__name__":
        return False
    return any(
        isinstance(comparator, ast.Constant) and comparator.value == "__main__"
        for comparator in test.comparators
    )

def _module_name(path: Path, root: Path) -> str:
    relative = path.relative_to(root).with_suffix("")
    parts = list(relative.parts)
    if parts and parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)

def _package_of(module: str) -> str:
    parts = module.split(".")
    return parts[1] if len(parts) > 1 else parts[0]

def _unparse(node: ast.AST | None) -> str:
    if node is None:
        return ""
    try:
        return ast.unparse(node)
    except Exception:  # pragma: no cover - defensive, unparse is total in 3.9+
        return "..."

def build_edges(
    modules: dict[str, ModuleInfo], resolver: CallResolver
) -> tuple[list[dict[str, Any]], dict[str, list[str]]]:
    """Walk every definition body and record its outgoing calls."""
    edges: dict[tuple[str, str], dict[str, Any]] = {}
    externals: dict[str, list[str]] = {}

    for module in modules.values():
        for definition in module.definitions.values():
            if definition.kind == "class":
                continue
            body = _definition_ast(module, definition)
            if body is None:
                continue
            seen_externals: list[str] = []
            for call in ast.walk(body):
                if not isinstance(call, ast.Call):
                    continue
                if isinstance(call.func, ast.Name):
                    targets, confidence = resolver.resolve_name(module, call.func.id)
                elif isinstance(call.func, ast.Attribute):
                    targets, confidence = resolver.resolve_attribute(
                        module, call.func, definition.class_name
                    )
                else:
                    targets, confidence = [], "external"

                if not targets:
                    label = _external_label(call)
                    if label and label not in seen_externals:
                        seen_externals.append(label)
                    continue

                for target in targets:
                    if target == definition.node_id:
                        continue  # skip self-recursion, it clutters the layout
                    key = (definition.node_id, target)
                    existing = edges.get(key)
                    if existing is None:
                        edges[key] = {
                            "source": definition.node_id,
                            "target": target,
                            "confidence": confidence,
                            "lines": [call.lineno],
                        }
                    else:
                        if call.lineno not in existing["lines"]:
                            existing["lines"].append(call.lineno)
                        if _confidence_rank(confidence) < _confidence_rank(
                            existing["confidence"]
                        ):
                            existing["confidence"] = confidence

            if seen_externals:
                externals[definition.node_id] = sorted(seen_externals)

    ordered = sorted(edges.values(), key=lambda edge: (edge["source"], edge["target"]))
    for edge in ordered:
        edge["lines"].sort()
    return ordered, externals

def build_graph(repo_root: Path) -> dict[str, Any]:
    """Produce the full graph payload consumed by the code-map page."""
    source_root = repo_root / "scripts"
    modules = discover_modules(source_root, repo_root)
    for module in modules.values():
        collect_imports(module)
        collect_definitions(module)

    entries = find_entrypoints(repo_root / ".github" / "workflows")
    for module_name, workflows in entries.items():
        entry_module = modules.get(module_name)
        if entry_module is not None:
            entry_module.entry_workflows = workflows

    resolver = CallResolver(modules)
    edges, externals = build_edges(modules, resolver)

    definitions: dict[str, Definition] = {}
    for module in modules.values():
        for definition in module.definitions.values():
            definitions[definition.node_id] = definition

    incoming: dict[str, int] = {}
    outgoing: dict[str, int] = {}
    for edge in edges:
        outgoing[edge["source"]] = outgoing.get(edge["source"], 0) + 1
        incoming[edge["target"]] = incoming.get(edge["target"], 0) + 1

    node_payload: list[dict[str, Any]] = []
    for node_id, definition in sorted(definitions.items()):
        payload = definition.to_json()
        payload["callers"] = incoming.get(node_id, 0)
        payload["callees"] = outgoing.get(node_id, 0)
        if node_id in externals:
            payload["externals"] = externals[node_id]
        module = modules[definition.module]
        if module.entry_workflows and definition.name == "main":
            payload["entryWorkflows"] = module.entry_workflows
        node_payload.append(payload)

    module_payload = [
        {
            "id": module.name,
            "package": module.package,
            "file": module.file,
            "doc": module.doc,
            "loc": module.loc,
            "symbols": sorted(
                d.node_id for d in module.definitions.values() if d.kind != "method"
            ),
            "symbolCount": len(module.definitions),
            "entryWorkflows": module.entry_workflows,
            "hasMainGuard": module.has_main_guard,
        }
        for module in sorted(modules.values(), key=lambda m: m.name)
        if module.definitions or module.entry_workflows
    ]

    packages = sorted({module.package for module in modules.values()})
    confidence_counts: dict[str, int] = {}
    for edge in edges:
        confidence_counts[edge["confidence"]] = (
            confidence_counts.get(edge["confidence"], 0) + 1
        )

    return {
        "meta": {
            "moduleCount": len(module_payload),
            "nodeCount": len(node_payload),
            "edgeCount": len(edges),
            "edgeConfidence": confidence_counts,
            "packages": [
                {"name": name, "color": PACKAGE_COLORS.get(name, "#8b95a5")}
                for name in packages
            ],
        },
        "modules": module_payload,
        "moduleEdges": build_module_edges(edges, definitions),
        "nodes": node_payload,
        "edges": edges,
    }

def build_module_edges(
    edges: list[dict[str, Any]], nodes: dict[str, Definition]
) -> list[dict[str, Any]]:
    """Aggregate function-level edges into module-level ones."""
    weights: dict[tuple[str, str], int] = {}
    for edge in edges:
        source = nodes.get(edge["source"])
        target = nodes.get(edge["target"])
        if source is None or target is None:
            continue
        if source.module == target.module:
            continue
        key = (source.module, target.module)
        weights[key] = weights.get(key, 0) + 1
    return [
        {"source": source, "target": target, "weight": weight}
        for (source, target), weight in sorted(weights.items())
    ]

def collect_imports(module: ModuleInfo) -> None:
    """Map every local alias in a module to the dotted target it refers to."""
    for node in ast.walk(module.tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                local = alias.asname or alias.name.split(".")[0]
                target = alias.name if alias.asname else alias.name.split(".")[0]
                module.imports[local] = target
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                # Relative import: rebuild the absolute package path.
                base_parts = module.name.split(".")
                trimmed = base_parts[: max(0, len(base_parts) - node.level)]
                prefix = ".".join(trimmed + ([node.module] if node.module else []))
            else:
                prefix = node.module or ""
            for alias in node.names:
                local = alias.asname or alias.name
                module.imports[local] = f"{prefix}:{alias.name}" if prefix else alias.name

def discover_modules(root: Path, repo_root: Path) -> dict[str, ModuleInfo]:
    """Parse every source file under ``root`` into a :class:`ModuleInfo`."""
    modules: dict[str, ModuleInfo] = {}
    for path in sorted(root.rglob("*.py")):
        if _is_excluded(path):
            continue
        text = path.read_text(encoding="utf-8")
        try:
            tree = ast.parse(text)
        except SyntaxError:
            continue
        name = _module_name(path, repo_root)
        lines = text.splitlines()
        modules[name] = ModuleInfo(
            name=name,
            package=_package_of(name),
            file=str(path.relative_to(repo_root)),
            doc=_first_paragraph(ast.get_docstring(tree)),
            loc=len(lines),
            tree=tree,
            source_lines=lines,
        )
    return modules

def extract_json_object(stdout: str, *, required_key: str) -> dict[str, Any] | None:
    """Return the first ``{...}`` object containing ``required_key``, or None.

    Prefers the last stream-json ``result`` event's text, then scans for a
    JSON object carrying ``required_key`` so we ignore unrelated braces in
    surrounding prose.
    """
    text = stdout
    for line in stdout.strip().splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict) and event.get("type") == "result":
            result = event.get("result")
            if isinstance(result, str):
                text = result

    decoder = json.JSONDecoder()
    start = text.find("{")
    while start != -1:
        try:
            obj, _ = decoder.raw_decode(text[start:])
        except ValueError:
            start = text.find("{", start + 1)
            continue
        if isinstance(obj, dict) and required_key in obj:
            return obj
        start = text.find("{", start + 1)
    return None

def _decode(value: str | bytes | None) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value

def _full_log_section(command: str, returncode: int | None, stdout: str, stderr: str) -> str:
    rc_label = "timeout" if returncode is None else str(returncode)
    parts = [f"$ {command}", f"# exit code: {rc_label}"]
    if stdout:
        parts.append("# stdout:")
        parts.append(stdout)
    if stderr:
        parts.append("# stderr:")
        parts.append(stderr)
    return "\n".join(parts)

def _tail_text(value: str | bytes | None) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        value = value.decode("utf-8", errors="replace")
    return value[-2000:]

@dataclass
class GitAuth:
    """Context manager that supplies Git credentials via GIT_ASKPASS."""

    token: str
    username: str = "x-access-token"
    prefix: str = "ci-agent-git-askpass-"
    _askpass_path: str = ""

    def __enter__(self) -> "GitAuth":
        if not self.token:
            return self
        fd, path = tempfile.mkstemp(prefix=self.prefix, suffix=".sh")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(
                    "#!/bin/sh\n"
                    "case \"$1\" in\n"
                    f"  *Username*) echo {shlex.quote(self.username)} ;;\n"
                    "  *) echo \"$GIT_PASSWORD\" ;;\n"
                    "esac\n"
                )
            os.chmod(path, stat.S_IRWXU)
        except Exception:
            # If write/chmod fails, clean up the temp file so we don't
            # leak files in /tmp on partial init.
            try:
                Path(path).unlink()
            except OSError:
                pass
            raise
        self._askpass_path = path
        return self

    def __exit__(self, *_exc_info: object) -> None:
        self.cleanup()

    @property
    def askpass_path(self) -> str:
        return self._askpass_path

    def env(self, base: dict[str, str] | None = None) -> dict[str, str]:
        env = dict(base) if base is not None else filter_env(_GIT_AUTH_ENV_ALLOWLIST)
        if self.token:
            env["GIT_TERMINAL_PROMPT"] = "0"
            env["GIT_CONFIG_NOSYSTEM"] = "1"
            env["GIT_CONFIG_GLOBAL"] = os.devnull
            env["GIT_PASSWORD"] = self.token
            if self._askpass_path:
                env["GIT_ASKPASS"] = self._askpass_path
        return env

    def cleanup(self) -> None:
        if not self._askpass_path:
            return
        try:
            Path(self._askpass_path).unlink()
        except OSError:
            pass
        self._askpass_path = ""

@property
def askpass_path(self) -> str:
    return self._askpass_path

def cleanup(self) -> None:
    if not self._askpass_path:
        return
    try:
        Path(self._askpass_path).unlink()
    except OSError:
        pass
    self._askpass_path = ""

def env(self, base: dict[str, str] | None = None) -> dict[str, str]:
    env = dict(base) if base is not None else filter_env(_GIT_AUTH_ENV_ALLOWLIST)
    if self.token:
        env["GIT_TERMINAL_PROMPT"] = "0"
        env["GIT_CONFIG_NOSYSTEM"] = "1"
        env["GIT_CONFIG_GLOBAL"] = os.devnull
        env["GIT_PASSWORD"] = self.token
        if self._askpass_path:
            env["GIT_ASKPASS"] = self._askpass_path
    return env

def _is_retryable_error(exc: Exception) -> bool:
    if not isinstance(exc, GithubException):
        return False
    if exc.status in RETRYABLE_HTTP_STATUS:
        return True
    # Only retry 403 when it's clearly rate-limiting, not a permission error.
    if exc.status == 403:
        msg = str(exc).lower()
        return any(indicator in msg for indicator in _RATE_LIMIT_403_INDICATORS)
    return False

def retry_github_call(
    operation: Callable[[], _T],
    *,
    retries: int,
    description: str,
) -> _T:
    """Retry transient GitHub API failures with exponential backoff."""
    for attempt in range(retries):
        try:
            return operation()
        except Exception as exc:
            if not _is_retryable_error(exc) or attempt == retries - 1:
                raise
            wait_seconds = transient_backoff_delay(attempt)
            logger.warning(
                "Retrying GitHub API call for %s after %.2fs: %s",
                description,
                wait_seconds,
                exc,
            )
            time.sleep(wait_seconds)
    raise RuntimeError("unreachable: retry loop exited without returning or raising")

def transient_backoff_delay(attempt: int) -> float:
    """Jittered, capped exponential backoff for transient-failure retries."""
    return random.uniform(0, min(_MAX_DELAY_SECONDS, _BASE_DELAY_SECONDS * (2 ** attempt)))

def _find_by_title(self, repo: Any, repo_name: str, title: str) -> Any:
    """Find an open issue whose title exactly equals ``title``, or None.

    Migration fallback for when the marker match misses. The comparison
    is exact and case-sensitive.
    """
    for issue in self._open_issues_for(repo, repo_name):
        if issue.title == title:
            return self._reload(repo, issue.number)
    return None

def _find_existing(self, repo: Any, repo_name: str, marker: str) -> Any:
    """Find an open issue containing the marker, or None."""
    for issue in self._open_issues_for(repo, repo_name):
        if marker in (issue.body or ""):
            return self._reload(repo, issue.number)
    return None

def _find_recently_closed(
    self, repo: Any, repo_name: str, marker: str, title_fallback: str | None,
) -> Any:
    """Find an issue that was closed within the lookback window and
    matches the marker or, for legacy issues, ``title_fallback`` exactly.
    Returns None when nothing matches or the check is disabled.

    Guards against re-filing an issue for a failure that was already fixed
    and whose issue was closed between the CI run and the detector run.
    """
    if self._closed_lookback is None:
        return None
    closed_issues = self._recently_closed_for(repo, repo_name)
    for issue in closed_issues:
        if marker in (issue.body or ""):
            return issue

    # A legacy issue carries an older (or no) marker, so the marker match
    # misses it. Fall back to an exact title match, mirroring the open-issue
    # migration path, so a just-closed legacy issue is not duplicated.
    if title_fallback is None:
        return None
    for issue in closed_issues:
        if issue.title == title_fallback:
            logger.info(
                "Matched recently closed legacy issue #%s via title fallback",
                issue.number,
            )
            return issue
    return None

def _reload(self, repo: Any, number: int) -> Any:
    """Reload an issue so the update path edits a fresh, mutable handle."""
    return retry_github_call(
        lambda: repo.get_issue(number),
        retries=2, description=f"get issue #{number}",
    )

def _occurrence_re(namespace: str) -> re.Pattern[str]:
    """A namespaced occurrence-counter regex: ``<!-- <ns>:occurrences:<n> -->``."""
    return re.compile(rf"<!-- {re.escape(namespace)}:occurrences:(\d+) -->")

class PollLoopError(RuntimeError):
    """Raised after a sustained poll loop had one or more failed iterations."""

    def __init__(self, *, results: list[Any], last_error: BaseException) -> None:
        super().__init__(f"one or more poll iterations failed; last error: {last_error}")
        self.results = results
        self.last_error = last_error

def format_poll_results(results: list[Any]) -> Any:
    """Preserve old one-shot JSON while wrapping sustained runs."""
    return results[0] if len(results) == 1 else {"runs": results}

def nonnegative_int(value: str) -> int:
    """Argparse type for integer knobs where 0 is a meaningful value."""
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be an integer >= 0") from exc
    if parsed < 0:
        raise argparse.ArgumentTypeError("must be >= 0")
    return parsed

def strip_ansi(text: str) -> str:
    """Remove ANSI SGR color codes from text."""
    return _ANSI_ESCAPE_RE.sub("", text)

class ArtifactClient:
    """Fetches workflow artifacts and logs from GitHub Actions."""

    def __init__(self, github_client: Github, *, token: str, retries: int = 3) -> None:
        if not token:
            raise ValueError("GitHub token is required")
        self._gh = github_client
        self._token = token
        self._retries = retries

    def list_recent_runs(
        self, repo_full_name: str, workflow_file: str,
        *, event: str = "schedule", max_runs: int = 1,
    ) -> list[Any]:
        def _fetch() -> list[Any]:
            repo = self._gh.get_repo(repo_full_name)
            workflow = repo.get_workflow(workflow_file)
            return list(islice(workflow.get_runs(event=event, status="completed"), max_runs))

        return retry_github_call(
            _fetch, retries=self._retries, description=f"list runs {workflow_file}",
        )

    def list_run_artifacts(self, repo_full_name: str, run_id: int) -> list[WorkflowArtifact]:
        repo = self._gh.get_repo(repo_full_name)

        def _fetch() -> Any:
            _, data = repo._requester.requestJsonAndCheck(
                "GET", f"/repos/{repo_full_name}/actions/runs/{run_id}/artifacts",
            )
            return data

        payload = retry_github_call(_fetch, retries=self._retries,
                                    description=f"list artifacts {run_id}")
        if not isinstance(payload, dict):
            return []
        return [
            WorkflowArtifact(
                artifact_id=a["id"], name=a["name"],
                size_in_bytes=a.get("size_in_bytes", 0),
                expired=a.get("expired", False),
            )
            for a in payload.get("artifacts", [])
            if isinstance(a, dict)
            and isinstance(a.get("id"), int)
            and isinstance(a.get("name"), str)
        ]

    def download_artifact(
        self,
        repo_full_name: str,
        artifact_id: int,
        damaged: list[str] | None = None,
    ) -> dict[str, bytes]:
        """Download and extract an artifact zip to ``{name: bytes}``.

        Pass ``damaged`` to learn which members were unreadable, so a caller
        that reports on the artifact can say the extraction was incomplete.
        """
        return _extract_zip(
            self._download(
                f"/repos/{repo_full_name}/actions/artifacts/{artifact_id}/zip"
            ),
            damaged,
        )

    def download_run_logs(self, repo_full_name: str, run_id: int) -> dict[str, bytes]:
        """Download a workflow run's console logs as a ``{path: bytes}`` map.

        GitHub returns the whole run's logs as a zip whose members are the
        per-step text logs (one file per job step, plus per-job rollups).
        Unlike ``download_artifact`` this is the raw CI console output, not a
        user-uploaded artifact bundle. Shares the same token-redirect, retry,
        and uncompressed-size-cap discipline as artifact downloads. Returns an
        empty map if the logs have expired (404) or the zip is unreadable.
        """
        return _extract_zip(self._download(
            f"/repos/{repo_full_name}/actions/runs/{run_id}/logs"
        ))

    def _download(self, path: str) -> bytes:
        url = f"https://api.github.com{path}"
        req = Request(url, headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "valkey-ci-agent",
        })
        # Use an unredirected header for the token: urllib forwards normal
        # headers on cross-host redirects, but GitHub redirects to signed S3
        # URLs that must not receive our token. add_unredirected_header keeps
        # the Authorization off the redirected request.
        req.add_unredirected_header("Authorization", f"Bearer {self._token}")
        # Hand-rolled retry rather than retry_github_call: this is a raw urllib
        # call (not a PyGithub operation) and needs HTTP-status-specific
        # handling for the 404/expired case below. Retry classification and
        # backoff are shared with retry_github_call so behavior stays uniform.
        for attempt in range(self._retries + 1):
            try:
                with urlopen(req, timeout=120) as resp:
                    return resp.read()
            except HTTPError as exc:
                if exc.code == 404:
                    logger.warning("Artifact not found at %s (likely expired)", path)
                    return b""
                if exc.code in RETRYABLE_HTTP_STATUS and attempt < self._retries:
                    time.sleep(transient_backoff_delay(attempt))
                    continue
                raise
            except (URLError, TimeoutError, ConnectionError):
                if attempt < self._retries:
                    time.sleep(transient_backoff_delay(attempt))
                    continue
                raise
        raise AssertionError("unreachable: retry loop must return or raise")

