def build_prompt_payload(prs: Sequence[MergedPR], *, diffs: dict[int, str] | None = None) -> str:
    """Render factual PR metadata and optional bounded diffs as a JSON array."""
    diffs = diffs or {}
    payload = []
    for pr in prs:
        entry = {
            "number": pr.number,
            "title": pr.title,
            "author": pr.author,
            "url": pr.url,
            "body": pr.body,
        }
        diff = diffs.get(pr.number)
        if diff:
            entry["diff"] = diff
        payload.append(entry)
    return json.dumps(payload, indent=2)

def exact_pr_number(value: object) -> "int | None":
    """Return *value* iff it is an exact non-bool int, else None."""
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value

def _applied_rows(body: str) -> list[tuple[int, str]]:
    """Return ``(source_pr, title)`` for each row of the ``## Applied`` table.

    Title is "" when the table has no Title column.
    """
    applied = _markdown_section(body, "Applied")
    if not applied:
        return []
    rows: list[str] = []
    for line in applied.splitlines():
        if line.lstrip().startswith("|"):
            rows.append(line)
        elif rows:
            rows[-1] += " " + line.strip()  # fold wrapped cell

    column: int | None = None
    title_column = 1  # fallback: sweep lists title second
    parsed: list[tuple[int, str]] = []
    for row in rows:
        cells = [cell.strip() for cell in row.strip().strip("|").split("|")]
        if column is None:
            for index, cell in enumerate(cells):
                if cell.strip().lower() == "source pr":
                    column = index
                    break
            else:
                column = 0  # fallback: sweep lists source PR first
            for index, cell in enumerate(cells):
                if cell.strip().lower() == "title":
                    title_column = index
                    break
            if any(cell.strip().lower() == "source pr" for cell in cells):
                continue  # skip the header row
        if all(set(cell) <= set("-: ") for cell in cells if cell):
            continue  # separator row (|---|---|)
        if column < len(cells):
            match = _PR_CELL_RE.match(cells[column])
            if match:
                title = cells[title_column] if title_column < len(cells) else ""
                parsed.append((int(match.group(1)), title))
    return parsed

def _summary_value_cell(body: str, label: str) -> str | None:
    """Return the value cell for *label* in the ``## Backport Summary`` table, or None."""
    summary = _markdown_section(body, "Backport Summary")
    if not summary:
        return None
    rows: list[str] = []
    for line in summary.splitlines():
        if line.lstrip().startswith("|"):
            rows.append(line)
        elif rows:
            rows[-1] += " " + line.strip()  # fold wrapped cell
    for row in rows:
        cells = _split_table_row(row)
        if len(cells) < 2 or cells[0].strip().lower() != label:
            continue
        return cells[1]
    return None

def applied_revert_source_prs_from_body(body: str) -> dict[int, str]:
    """Return ``{source_pr: title}`` for Revert-titled ``## Applied`` rows."""
    return {
        number: title
        for number, title in _applied_rows(body)
        if _REVERT_TITLE_RE.match(title)
    }

def applied_source_prs_from_body(body: str) -> set[int]:
    """Extract source PR numbers from the ``## Applied`` markdown table in *body*.

    Rows whose Title begins with ``Revert`` are excluded: the sweep shipped a
    revert of that PR, so attributing the original PR's change to this range
    would note a change the range does not contain. Those rows are available via
    :func:`applied_revert_source_prs_from_body` for maintainer review.
    """
    return {
        number
        for number, title in _applied_rows(body)
        if not _REVERT_TITLE_RE.match(title)
    }

def cherry_pick_source_shas(commit_message: str) -> list[str]:
    """Return source SHAs from ``(cherry picked from commit <sha>)`` trailers.

    Returned in file order (oldest hop first). Empty list if no trailer present.
    """
    return _CHERRY_PICK_TRAILER_RE.findall(commit_message)

def is_backport_title(title: str) -> bool:
    """True if *title* has a backport or release-line prefix."""
    return bool(_BACKPORT_TITLE_RE.match(title))

def source_pr_from_branch(head_ref: str) -> int | None:
    """Extract the source PR number from a per-PR backport branch name, or None."""
    if not head_ref:
        return None
    match = _BACKPORT_BRANCH_RE.match(head_ref)
    return int(match.group(1)) if match else None

def source_prs_from_backport_body(body: str) -> tuple[int, ...]:
    """Return ordered ``#N`` sources from an explicit leading Backport(s) line.

    This handles container PRs that intentionally carry several source changes.
    A single source is returned too, but callers that expand containers should
    require multiple entries plus corroborating commit subjects.
    """
    first_line = next((line.strip() for line in (body or "").splitlines() if line.strip()), "")
    if not _BACKPORTS_BODY_LINE_RE.match(first_line):
        return ()
    return tuple(dict.fromkeys(int(number) for number in _INLINE_PR_RE.findall(first_line)))

def _api_get(url: str, token: Optional[str]) -> object:
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "valkey-release-tools",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    if token:
        headers["Authorization"] = "Bearer {}".format(token)
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=30) as resp:  # noqa: S310 (trusted host)
        return json.loads(resp.read().decode("utf-8"))

def _api_get_with_retry(url: str, token: Optional[str], label: str) -> object:
    """Call ``_api_get`` with bounded retries for transient HTTP errors."""
    for attempt in range(_API_RETRIES):
        try:
            return _api_get(url, token)
        except urllib.error.HTTPError as exc:
            if exc.code in _RETRYABLE_HTTP_CODES and attempt < _API_RETRIES - 1:
                delay = min(8.0, 1.0 * (2**attempt))
                logger.warning("Retrying %s after %.1fs (HTTP %d)", label, delay, exc.code)
                time.sleep(delay)
                continue
            raise
    raise RuntimeError("unreachable")

def _display_name(repo_login: str, token: Optional[str]) -> Optional[str]:
    """Resolve a login to its profile full name, or ``None`` if unavailable."""
    try:
        data = _api_get_with_retry(
            "{}/users/{}".format(_API_ROOT, repo_login),
            token,
            "/users/{}".format(repo_login),
        )
    except (OSError, urllib.error.URLError, urllib.error.HTTPError, ValueError):
        return None
    if isinstance(data, dict):
        name = data.get("name")
        if isinstance(name, str) and name.strip():
            return name.strip()
    return None

def _is_bot(identity: str) -> bool:
    """True if *identity* is a bot account (ends in ``[bot]``)."""
    return identity.strip().casefold().endswith("[bot]")

def _fetch_pull(repo: Any, number: int, cache: dict[int, Any]) -> Any:
    """Fetch and cache PR number, returning None on 404. Non-404 errors propagate."""
    if number in cache:
        return cache[number]
    try:
        pull = retry_github_call(
            lambda: repo.get_pull(number), retries=3, description=f"get PR #{number}"
        )
    except UnknownObjectException:
        logger.warning("Skipping PR #%s (not found; likely an issue or cross-repo ref)", number)
        pull = None
    except GithubException as exc:
        if exc.status == 404:
            logger.warning("Skipping PR #%s (not found; likely an issue or cross-repo ref)", number)
            pull = None
        else:
            raise
    cache[number] = pull
    return pull

def _is_distinctive_title(normalized: str) -> bool:
    """True if the normalized title is specific enough to serve as match evidence."""
    if len(normalized) < _MIN_DISTINCTIVE_TITLE_CHARS:
        return False
    if len(normalized.split()) < _MIN_DISTINCTIVE_TITLE_WORDS:
        return False
    if normalized in _GENERIC_TITLES:
        return False
    if _GENERIC_TITLE_PREFIX_RE.match(normalized):
        return False
    return True

def _is_merged_pull(pull: Any) -> bool:
    """True unless *pull* is known-unmerged. An open or closed-unmerged PR (e.g.
    an in-flight sweep containing an already-landed commit) must never be
    credited for a range commit: the note would reference a PR that shipped
    nothing. Follows the same truthiness convention as _source_is_trusted."""
    return bool(
        getattr(pull, "merged", None)
        or getattr(pull, "merged_at", None) is not None
    )

def _norm_title(title: Any) -> str:
    """Normalize a title for comparison: collapse whitespace and casefold."""
    if not isinstance(title, str):
        return ""
    return re.sub(r"\s+", " ", title).strip().casefold()

def _pr_from_commit_api(
    repo: Any,
    sha: str,
    *,
    pulls_cache: dict[str, list[Any]] | None = None,
) -> int | None:
    """Return the first merged PR number associated with sha via Commit.get_pulls(), or None."""
    pulls = _pulls_from_commit_api(repo, sha, cache=pulls_cache)
    for pull in pulls or ():
        if _is_merged_pull(pull):
            return int(pull.number)
    return None

def _pr_numbers_from_subjects(subjects: list[str]) -> set[int]:
    """Extract PR numbers from subjects via trailing (#N) or merge-commit prefix."""
    numbers: set[int] = set()
    for line in subjects:
        m = _TRAILING_REF_RE.search(line)
        if m is None:
            m = _MERGE_COMMIT_RE.search(line)
        if m:
            numbers.add(int(m.group(1)))
    return numbers

def _pull_changed_files(pull: Any) -> tuple[str, ...]:
    """Return the PR's changed file paths from the files API, or () on failure.

    A miss degrades to an empty tuple: callers that gate on file paths (the
    test-only guardrail exemption) must treat "unknown" as "not exempt".
    """
    try:
        files = retry_github_call(
            lambda: list(pull.get_files()), retries=3,
            description=f"files of PR #{pull.number}",
        )
        return tuple(f.filename for f in files if getattr(f, "filename", None))
    except Exception as exc:  # noqa: BLE001 - a lookup miss must not abort discovery
        logger.warning("Could not read files of PR #%s: %s", pull.number, exc)
        return ()

def _pulls_from_commit_api(
    repo: Any,
    sha: str,
    *,
    cache: dict[str, list[Any]] | None = None,
) -> list[Any] | None:
    """Return associated PRs, or ``None`` when the API lookup itself failed.

    Successful and empty responses may be cached for one discovery pass. Failures
    are not cached so a later reference to the same SHA can retry a transient error.
    """
    if cache is not None and sha in cache:
        return cache[sha]

    def _lookup() -> list[Any]:
        commit = repo.get_commit(sha)
        return list(commit.get_pulls())

    try:
        pulls = retry_github_call(
            _lookup, retries=3, description=f"PRs for commit {sha[:12]}"
        )
    except Exception as exc:  # noqa: BLE001 - a lookup miss must not abort discovery
        logger.warning("Could not resolve PR for commit %s: %s", sha[:12], exc)
        return None
    if cache is not None:
        cache[sha] = pulls
    return pulls

def _reconcile_cherry_pick_suspects(
    suspects: dict[int, UnresolvedCherryPick],
    prs: list[MergedPR],
    unresolved_backports: list[UnresolvedBackport],
    unresolved_prs: list[UnresolvedPR],
) -> list[UnresolvedCherryPick]:
    """Keep only cherry-pick suspects not already flagged by another mechanism.

    Drops suspects that were remapped, flagged as unresolved backports, or 404'd.
    What remains is a PR credited under its own number with no other signal that
    its origin is unconfirmed.
    """
    if not suspects:
        return []
    credited = {pr.number for pr in prs}
    flagged_backports = {bp.number for bp in unresolved_backports}
    fetch_failed = {u.number for u in unresolved_prs}
    return [
        suspect
        for number, suspect in suspects.items()
        if number in credited
        and number not in flagged_backports
        and number not in fetch_failed
    ]

def _recover_multi_source_prs(pull: Any) -> tuple[int, ...]:
    """Return corroborated sources for a manually assembled container backport.

    Trust the expansion only when an explicit leading ``Backports #...`` line
    and the PR's actual commit subjects name the same multiple source PRs. This
    prevents a body-only claim from suppressing the container or minting notes
    for unrelated PRs.
    """
    body_sources = source_prs_from_backport_body(pull.body or "")
    if len(body_sources) < 2:
        return ()
    try:
        commits = retry_github_call(
            lambda: list(pull.get_commits()), retries=3,
            description=f"commits of multi-source PR #{pull.number}",
        )
        subjects = [c.commit.message.splitlines()[0] for c in commits if c.commit.message]
    except Exception as exc:  # noqa: BLE001 - failed proof falls back safely
        logger.warning("Could not read commits of multi-source PR #%s: %s", pull.number, exc)
        return ()
    commit_sources = _pr_numbers_from_subjects(subjects)
    return body_sources if set(body_sources) == commit_sources else ()

def _recover_source_pr(repo: Any, pull: Any) -> int | None:
    """Return the original PR of a per-PR backport, or None.

    Tries: ## Backport Summary Source PR row, a manual ``backport of <PR URL>``
    marker, PR's own commits' trailing (#N), and backport/<n>-to-<branch> head
    branch. Returns None when unrecoverable.
    """
    source = summary_source_pr_from_body(pull.body or "")
    if source is not None:
        return source
    source = source_pr_from_backport_title(pull.title or "")
    if source is not None:
        return source
    source = source_pr_from_backport_body(pull.body or "")
    if source is not None:
        return source
    try:
        commits = retry_github_call(
            lambda: list(pull.get_commits()), retries=3,
            description=f"commits of PR #{pull.number}",
        )
        subjects = [c.commit.message.splitlines()[0] for c in commits if c.commit.message]
        numbers = _pr_numbers_from_subjects(subjects)
        # Take the sole number when unambiguous.
        if len(numbers) == 1:
            return next(iter(numbers))
    except Exception as exc:  # noqa: BLE001 - a lookup miss must not abort discovery
        logger.warning("Could not read commits of PR #%s: %s", pull.number, exc)
    head_ref = getattr(getattr(pull, "head", None), "ref", "") or ""
    return source_pr_from_branch(head_ref)

def _resolve_base_ref(repo_dir: str, base_ref: str) -> str:
    """Return a resolvable ref for base_ref, falling back to origin/<name> if needed."""
    try:
        git_output(repo_dir, "rev-parse", "--verify", "--quiet", f"{base_ref}^{{commit}}")
        return base_ref
    except subprocess.CalledProcessError:
        remote = f"origin/{base_ref}"
        try:
            git_output(repo_dir, "rev-parse", "--verify", "--quiet", f"{remote}^{{commit}}")
        except subprocess.CalledProcessError as exc:
            raise ValueError(
                f"base ref {base_ref!r} resolves neither as given nor as {remote!r}"
            ) from exc
        logger.info("Base ref %r resolved via remote-tracking ref %r", base_ref, remote)
        return remote

def _same_change_subject(a: str, b: str) -> bool:
    """True if two commit subjects describe the same change (dedup is a correct collapse)."""
    na, nb = _norm_title(_title_core(a)), _norm_title(_title_core(b))
    if not na or not nb:
        return False
    if na == nb:
        return True
    return difflib.SequenceMatcher(None, na, nb).ratio() >= _TITLE_SIMILARITY_MIN

def _source_is_trusted(src_pull: Any, backport_pull: Any) -> bool:
    """True if src_pull is a credible original for backport_pull.

    Requires: src_pull is merged, and its title matches a distinctive source title
    the backport embeds. Returns False (fail-closed) when no title to compare.
    """
    if not (getattr(src_pull, "merged", None) or getattr(src_pull, "merged_at", None) is not None):
        return False
    expected = _expected_source_titles(backport_pull)
    if not expected:
        return False
    return _titles_consistent(expected, src_pull.title)

def _tag_matches_glob(tag: str, glob: str) -> bool:
    """Whether tag matches glob, stripping a leading 'v' if needed."""
    return fnmatch.fnmatch(tag, glob) or (
        tag[:1] in ("v", "V") and fnmatch.fnmatch(tag[1:], glob)
    )

def _title_core(title: Any) -> str:
    """Strip backport prefix and trailing PR refs to get the source title."""
    if not isinstance(title, str):
        return ""
    stripped = source_title_from_backport_title(title)
    core = stripped if stripped is not None else title
    while match := _TRAILING_REF_RE.search(core):
        core = core[:match.start()].rstrip()
    return core

def _titles_consistent(expected: set[str], actual: Any) -> bool:
    """True if actual title matches any in expected (exact or >= 0.90 similarity)."""
    a = _norm_title(_title_core(actual))
    if not a:
        return False
    for e in expected:
        if e == a or difflib.SequenceMatcher(None, e, a).ratio() >= _TITLE_SIMILARITY_MIN:
            return True
    return False

def _trusted_associated_sweep_source_prs(
    repo: Any, pulls: list[Any], *, release_branch: str | None
) -> tuple[set[int], dict[int, str]]:
    """Read (source PRs, revert rows) from the body of a verified associated sweep PR."""
    numbers: set[int] = set()
    reverts: dict[int, str] = {}
    for pull in pulls:
        if _is_trusted_sweep_pull(
            repo, pull, release_branch=release_branch
        ):
            body = getattr(pull, "body", "") or ""
            numbers.update(applied_source_prs_from_body(body))
            reverts.update(applied_revert_source_prs_from_body(body))
    return numbers, reverts

def hydrate_prs(
    repo: Any, pr_to_sha: dict[int, str]
) -> tuple[list[MergedPR], list[UnresolvedBackport], list[UnresolvedPR]]:
    """Fetch PR metadata and remap per-PR backports to their original source.

    Returns (prs, unresolved_backports, unresolved_prs). For backport PRs, walks
    to the original via _recover_source_pr and validates with _source_is_trusted.
    Deduplicates by final PR number (first-seen wins).
    """
    pull_cache: dict[int, Any] = {}
    final: dict[int, MergedPR] = {}
    unresolved_backports: list[UnresolvedBackport] = []
    unresolved_prs: list[UnresolvedPR] = []
    for number, sha in pr_to_sha.items():
        pull = _fetch_pull(repo, number, pull_cache)
        if pull is None:
            # PR not fetchable; record as unresolved so the shipped change is visible.
            logger.warning(
                "Commit %s resolved to PR #%s but it could not be fetched; "
                "surfacing it as unresolved so the shipped change is not dropped.",
                sha[:12], number,
            )
            unresolved_prs.append(UnresolvedPR(number=number, sha=sha))
            continue

        target_pull, target_number = pull, number
        if _is_backport_pull(pull):
            multi_sources = _recover_multi_source_prs(pull)
            if multi_sources:
                source_pulls: list[tuple[int, Any]] = []
                for source_number in multi_sources:
                    source_pull = _fetch_pull(repo, source_number, pull_cache)
                    if source_pull is None or not _is_merged_pull(source_pull):
                        source_pulls = []
                        break
                    source_pulls.append((source_number, source_pull))
                if source_pulls:
                    logger.info(
                        "Backport container PR #%s expanded to source PRs %s.",
                        number, list(multi_sources),
                    )
                    for source_number, source_pull in source_pulls:
                        if source_number not in final:
                            final[source_number] = _build_merged_pr(
                                source_pull, source_number, sha
                            )
                    continue
            source = _recover_source_pr(repo, pull)
            depth = 0
            visited = {number}
            while source is not None and source not in visited and depth < _MAX_BACKPORT_DEPTH:
                src_pull = _fetch_pull(repo, source, pull_cache)
                if src_pull is None:
                    break
                if not _source_is_trusted(src_pull, target_pull):
                    logger.warning(
                        "Recovered source PR #%s for backport PR #%s failed validation "
                        "(title mismatch or unmerged); keeping the backport credit.",
                        source, target_number,
                    )
                    break
                visited.add(source)
                target_pull, target_number = src_pull, source
                if not _is_backport_pull(src_pull):
                    break
                source = _recover_source_pr(repo, src_pull)
                depth += 1
            if not _is_backport_pull(target_pull):
                logger.info(
                    "Backport PR #%s credited to its original source PR #%s.",
                    number, target_number,
                )

        if target_number in final:
            continue  # dedup: first-seen wins
        if target_number == number:
            merge_sha = target_pull.merge_commit_sha or sha
        else:
            merge_sha = sha
        final[target_number] = _build_merged_pr(target_pull, target_number, merge_sha)
        # Still a backport after recovery: flag for maintainer review.
        if _is_backport_pull(target_pull):
            logger.warning(
                "PR #%s credited for a range commit is itself a backport (%r); "
                "the original PR could not be recovered from an ## Applied table, a "
                "-x trailer, the subject, its ## Backport Summary, a backport-of "
                "URL, its own commits, or its branch name. The note will credit "
                "this backport.",
                target_number, (target_pull.title or "")[:80],
            )
            unresolved_backports.append(
                UnresolvedBackport(
                    number=target_number,
                    title=target_pull.title or "",
                    url=target_pull.html_url or "",
                )
            )
    return list(final.values()), unresolved_backports, unresolved_prs

def resolve_last_tag(repo_dir: str, head_ref: str, *, tag_glob: str | None = None) -> tuple[str, str]:
    """Return (tag_name, tag_sha) for the highest-version tag reachable from head_ref.

    Lists all reachable tags (git tag --merged), filters by tag_glob in Python,
    parses to version keys, and picks the maximum. Raises ValueError if none match.
    """
    try:
        out = git_output(repo_dir, "tag", "--merged", head_ref)
    except subprocess.CalledProcessError as exc:
        raise ValueError(
            f"no tag reachable from {head_ref!r}"
            + (f" matching {tag_glob!r}" if tag_glob else "")
        ) from exc
    candidates = [
        (key, name)
        for name in out.split()
        if (tag_glob is None or _tag_matches_glob(name, tag_glob))
        and (key := _tag_sort_key(name)) is not None
    ]
    if not candidates:
        raise ValueError(
            f"no tag reachable from {head_ref!r}"
            + (f" matching {tag_glob!r}" if tag_glob else "")
        )
    _key, tag = max(candidates)
    # Dereference the (possibly annotated) tag to the commit it points at.
    tag_sha = git_output(repo_dir, "rev-list", "-n", "1", tag).strip()
    logger.info("Highest-version tag reachable from %s: %s (%s)", head_ref, tag, tag_sha[:12])
    return tag, tag_sha

def _apply_patch_category_bias(
    bullet: CategorizedBullet, pr: MergedPR, *, patch_release: bool
) -> CategorizedBullet:
    """Bias patch-release corrections into Bug Fixes without hiding exceptions."""
    if not patch_release or bullet.category == "Bug Fixes":
        return bullet

    # Keep deterministic evidence narrow. Generic words such as "error" and
    # "prevent" are common in explanatory PR bodies and otherwise make almost
    # every patch entry look like a positive fix match. The model may still use
    # the full body when it drafts and categorizes the note.
    evidence = "{}\n{}".format(pr.title or "", bullet.text)
    is_fix = bool(_PATCH_FIX_EVIDENCE_RE.search(evidence))
    intentional = bool(_PATCH_INTENTIONAL_CHANGE_RE.search(evidence))

    if is_fix and (
        bullet.category in _PATCH_FIX_DEFAULT_CATEGORIES
        or bullet.category == "Performance and Efficiency Improvements"
    ):
        return replace(bullet, category="Bug Fixes")

    if bullet.category in _PATCH_FIX_DEFAULT_CATEGORIES and not intentional:
        reason = "; ".join(
            part for part in (
                bullet.uncertain_reason,
                "ambiguous patch-release category defaulted to Bug Fixes",
            ) if part
        )
        return replace(
            bullet,
            category="Bug Fixes",
            uncertain=True,
            uncertain_reason=reason,
        )

    exceptional = bullet.category == "New Features and Enhanced Behavior" or (
        bullet.category == "Build and Tooling" and "release-notes" not in pr.labels
    ) or (bullet.category in _PATCH_FIX_DEFAULT_CATEGORIES and intentional)
    if not exceptional:
        return bullet
    reason = "; ".join(
        part for part in (
            bullet.uncertain_reason,
            "non-fix category on a patch release needs explicit maintainer confirmation",
        ) if part
    )
    return replace(bullet, uncertain=True, uncertain_reason=reason)

def _explicit_scope_evidence(scope: str) -> re.Pattern[str]:
    """Match evidence that clearly limits an effect to a named environment."""
    return re.compile(
        rf"\b(?:on|for|affects?|limited to|specific to|only on)\s+(?:{scope})\b|"
        rf"\b(?:{scope})(?:[- ]only|\s+(?:builds?|platforms?|systems?|"
        rf"architectures?|hosts?))\b",
        re.IGNORECASE,
    )

def _review_bullet(
    bullet: CategorizedBullet, pr: MergedPR, *, patch_release: bool = False
) -> CategorizedBullet:
    """Apply deterministic category and factual-scope review guardrails."""
    # For patch releases the patch policy supersedes the general surface-first
    # taxonomy: a command, INFO, cluster, or config correction should stay a Bug
    # Fix instead of being normalized away and then flagged low-confidence.
    reviewed = bullet if patch_release else _apply_category_guardrail(bullet, pr)
    reviewed = _apply_patch_category_bias(reviewed, pr, patch_release=patch_release)
    return _apply_factual_scope_guardrail(reviewed, pr)

def build_prompt(
    prs: Sequence[MergedPR], *, categories: Sequence[str], diffs: dict[int, str] | None = None,
    patch_release: bool = False,
) -> str:
    """Render the generation prompt for a batch of PRs.

    ``diffs`` maps PR number to inlined diff text; absent or empty entries omit
    the diff field. Defaults to no diffs so the prompt works without a clone.
    """
    return _PROMPT_TEMPLATE.format(
        categories="\n".join(f"- {name}" for name in categories),
        category_guidance=(
            _CATEGORY_GUIDANCE + (_PATCH_RELEASE_GUIDANCE if patch_release else "")
        ),
        prs_json=build_prompt_payload(prs, diffs=diffs),
    )

def _base_ref_exists(clone_dir: str, base_ref: str) -> bool:
    """True if *base_ref* resolves in the clone (tries bare name then origin/<name>)."""
    for candidate in (base_ref, f"origin/{base_ref}"):
        try:
            run_git(clone_dir, "rev-parse", "--verify", "--quiet", f"{candidate}^{{commit}}")
            return True
        except subprocess.CalledProcessError:
            continue
    return False

def _env_flag(name: str) -> bool:
    """True if env var *name* holds a truthy string ('true'/'1'/'yes')."""
    return os.environ.get(name, "").strip().lower() in {"true", "1", "yes"}

def _is_iso_date(value: str) -> bool:
    """True if *value* is a valid YYYY-MM-DD date string."""
    value = value.strip()
    if not _ISO_DATE_RE.match(value):
        return False
    try:
        datetime.datetime.strptime(value, "%Y-%m-%d")
    except ValueError:
        return False
    return True

def _recredited_commit_count(
    clone_dir: str, base_ref: str, head_ref: str, prev_release_ref: str
) -> int | None:
    """Count commits in base_ref..head_ref already reachable from prev_release_ref.

    Returns 0 for a correct base, positive when the range extends past the
    previous release, or None if any ref fails to resolve.
    """
    try:
        total = int(git_output(clone_dir, "rev-list", "--count", f"{base_ref}..{head_ref}").strip())
        new_only = int(
            git_output(
                clone_dir, "rev-list", "--count", head_ref, "--not", base_ref, prev_release_ref
            ).strip()
        )
    except subprocess.CalledProcessError:
        return None
    return max(0, total - new_only)

def _resolve_stage(version: str, stage: str) -> str:
    """Normalize an explicit stage, or infer GA for a patch release.

    A patch component greater than zero unambiguously identifies a normal patch
    release in Valkey's release model, so an omitted stage safely means ``ga``.
    ``M.m.0`` is shared by every RC and the initial GA; those releases must keep
    an explicit stage so dispatch cannot guess the maintainer's intent.
    """
    if stage.strip():
        return cut_mod._normalize_stage(stage)
    _major, _minor, patch = cut_mod._split_version(version)
    if patch > 0:
        return "ga"
    raise ValueError(
        "--stage is required for a .0 release; pass rc1..rcN or ga "
        "(patch versions infer ga when stage is omitted)"
    )

def _token() -> str:
    """Resolve the GitHub token from the environment variable chain."""
    return (
        os.environ.get("RELEASE_NOTES_GITHUB_TOKEN", "")
        or os.environ.get("TARGET_TOKEN", "")
        or os.environ.get("GITHUB_TOKEN", "")
    )

def _validate_base_ref(clone_dir: str, base_ref: str) -> None:
    """Raise ValueError if *base_ref* does not resolve in the clone."""
    if not _base_ref_exists(clone_dir, base_ref):
        raise ValueError(
            f"--base-ref {base_ref!r} not found in the clone (tried {base_ref!r} and "
            f"'origin/{base_ref}'). Pass an existing branch, tag, or commit SHA."
        )

def _validate_release_target(
    clone_dir: str, source_ref: str, version: str, stage: str
) -> None:
    """Fail before AI work if the requested release does not advance the line."""
    version_h = Path(clone_dir, cut_mod.VERSION_FILE).read_text(encoding="utf-8")
    cut_mod.validate_release_progression(version_h, version, stage)
    discover_mod.validate_target_release_tag(
        clone_dir, source_ref, version, stage
    )

@dataclass(frozen=True)
class GenerationResult:
    """AI output for the whole range: categorized bullets and skipped PRs."""

    bullets: tuple[CategorizedBullet, ...] = ()
    skipped: tuple[int, ...] = ()   # PR numbers the model declined to summarize

@dataclass(frozen=True)
class UncertainNote:
    """A low-confidence note surfaced in the PR body for maintainer review."""

    pr_number: int
    category: str
    reason: str

def _dedup_bullets_by_pr(bullets):
    """Keep one bullet per PR number; return (kept, duplicate_pr_numbers).

    Prefers a renderable bullet over a reserved-category one so a stray
    reserved bullet cannot shadow the PR's real note.
    """
    order: list[int] = []
    by_pr: dict[int, list] = {}
    for b in bullets:
        if b.pr_number not in by_pr:
            by_pr[b.pr_number] = []
            order.append(b.pr_number)
        by_pr[b.pr_number].append(b)

    kept = []
    dups: list[int] = []
    for pr in order:
        group = by_pr[pr]
        # First renderable bullet wins; fall back to first if all are reserved.
        chosen = next(
            (b for b in group if not render_mod.is_reserved_category(b.category)),
            group[0],
        )
        kept.append(chosen)
        if len(group) > 1:
            dups.append(pr)
            logger.warning("PR #%s has more than one bullet; keeping one renderable bullet", pr)
    return tuple(kept), tuple(dups)

def _triaged_prs(decisions, by_number):
    """Join AI triage decisions back to their PR facts, dropping unknown numbers.

    Preserves decision order and skips any verdict whose PR is not in *by_number*
    (an unknown number the triage parser should already have filtered out).
    """
    out = []
    for d in decisions:
        pr = by_number.get(d.pr_number)
        if pr is None:
            continue
        out.append(TriagedPR(
            number=pr.number, title=pr.title, author=pr.author, url=pr.url,
            included=d.included, reason=d.reason, uncertain=d.uncertain,
            guardrail=d.guardrail,
        ))
    return tuple(out)

def escape_cell(text: str) -> str:
    """Escape pipes and line breaks for a markdown table cell."""
    escaped = text.replace("\\", "\\\\").replace("|", "\\|")
    return _LINEBREAK_RE.sub(" ", escaped).strip()

def find_existing_pr(
    repo: Any, *, base_repo: str, push_repo: str | None, branch: str, base_branch: str
) -> Any | None:
    """Return the open PR whose head is *branch* and base is *base_branch*, or None."""
    head_ref = build_pull_search_head_ref(base_repo, push_repo, branch)
    pulls = retry_github_call(
        lambda: list(repo.get_pulls(state="open", head=head_ref, base=base_branch)),
        retries=3, description=f"search open PR for {head_ref} into {base_branch}",
    )
    return pulls[0] if pulls else None

def reconcile_draft(existing: Any, draft: bool) -> None:
    """Flip *existing*'s draft state to *draft* if it differs."""
    if bool(existing.draft) == draft:
        return
    if draft:
        retry_github_call(
            lambda: existing.convert_to_draft(),
            retries=3, description=f"convert PR #{existing.number} to draft",
        )
    else:
        retry_github_call(
            lambda: existing.mark_ready_for_review(),
            retries=3, description=f"mark PR #{existing.number} ready",
        )

def _assert_origin_url(repo_dir: str, repo_full_name: str) -> None:
    """Verify the clone's origin URL matches the expected repository.

    Defense-in-depth against a tampered remote (the primary defense is --safe-mode
    on Claude subprocess invocations, which prevents hooks from modifying the clone).
    The origin must match exactly. This guard runs immediately before every
    authenticated fetch so a tampered remote cannot receive the GitHub token.
    """
    try:
        actual = git_output(repo_dir, "remote", "get-url", "origin").strip()
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            "Clone origin URL could not be read; aborting before authenticated fetch."
        ) from exc
    expected = github_https_url(repo_full_name)
    if actual != expected:
        raise RuntimeError(
            f"Clone origin URL was modified (expected {expected!r}, got {actual!r}). "
            "Aborting to prevent credential disclosure to a tampered remote."
        )

def _contrib_base(
    repo_dir: str, *, explicit: Optional[str], notes_base_ref: Optional[str]
) -> Optional[str]:
    """Pick the contributor-range start.

    Order: explicit ``--contrib-base-ref``, then the notes baseline, then last
    tag, then root commit. When the notes baseline was pinned (``notes_base_ref``),
    it is used before ``git describe`` so the credits span the same range as the
    bullets. The describe/root fallbacks keep the contributor list from being empty
    when no pinned baseline is available.
    """
    if explicit:
        return explicit
    if notes_base_ref:
        return notes_base_ref
    try:
        tag = git_output(repo_dir, "describe", "--tags", "--abbrev=0").strip()
        if tag:
            return tag
    except Exception:  # noqa: BLE001 - no tag reachable; fall through to root
        pass
    return _root_commit(repo_dir)

def _drop_already_credited(
    grouped: dict[str, list[str]], credited: set[int]
) -> tuple[dict[str, list[str]], list[int]]:
    """Drop bullets whose trailing ``(#N)`` is in *credited* from *grouped*.

    Returns ``(filtered_grouped, dropped_numbers)``. A category left with no
    bullets is dropped entirely; render_release_notes already omits empty
    categories, so this just keeps the map tidy.
    """
    if not credited:
        return grouped, []
    kept: dict[str, list[str]] = {}
    dropped: list[int] = []
    for category, lines in grouped.items():
        kept_lines: list[str] = []
        for line in lines:
            m = _TRAILING_PR_RE.search(line)
            if m and int(m.group(1)) in credited:
                dropped.append(int(m.group(1)))
                continue
            kept_lines.append(line)
        if kept_lines:
            kept[category] = kept_lines
    return kept, dropped

def _duplicate_pr_section(duplicate_prs: Sequence[int]) -> str:
    """Flag PRs the model credited in more than one bullet (extra bullets dropped)."""
    if not duplicate_prs:
        return ""
    refs = ", ".join(f"#{n}" for n in duplicate_prs)
    return (
        "\n### ⚠️ A PR was noted more than once\n\n"
        f"The generator emitted more than one bullet for {refs}; only the first "
        "was kept. Review the dated section and confirm the surviving bullet is "
        "the right one before merging.\n"
    )

def _fetch_remote_branch_tip(
    repo_dir: str, branch: str, git_env: dict[str, str]
) -> str:
    """Fetch *branch* into its tracking ref and return the exact remote tip."""
    tracking_ref = f"refs/remotes/origin/{branch}"
    run_git(
        repo_dir,
        "fetch",
        "--quiet",
        "origin",
        f"+refs/heads/{branch}:{tracking_ref}",
        env=git_env,
    )
    return git_output(
        repo_dir, "rev-parse", "--verify", f"{tracking_ref}^{{commit}}"
    ).strip()

def _hold_reasons(plan: BranchPlan, notes_meta: "_NotesMeta") -> list[str]:
    """Every signal in this cut that a maintainer should address before merging.

    One short label per body section that would render. The list is the hold
    decision: a non-empty list means the release PR opens as a draft (blocking the
    merge) unless the cut was dispatched with ``force_ready`` (see
    :func:`_commit_push_release_pr`), and it seeds the "held" banner at the top of
    the body. Each condition mirrors exactly the guard of the section helper it
    names, so the banner can never claim a hold the body does not also explain, nor
    stay silent while a warning section renders below it.

    A clean advisory match (``--security-from-advisories`` with every advisory read
    and matched) is informational, not a warning, so it does not hold; only the
    advisory sub-cases that render a ``⚠️`` (fetch failed, or an advisory that could
    not be read) do. Deduping a PR that leaves real notes behind also does not
    hold: it renders no body section (only the version-bump-only case does, via
    :func:`_no_new_prs_section`).
    """
    regen = notes_meta.regen
    reasons: list[str] = []
    if plan.rc_warning:
        reasons.append("release candidate out of sequence")
    if notes_meta.baseline_unanchored:
        reasons.append("release-notes baseline is unanchored")
    # Empty dated section, and not the dedup cause (which has its own reason next).
    # Mirrors _empty_notes_section's two sub-causes: no PRs, or PRs existed but none
    # were included (every candidate AI-excluded or left undecided). A non-empty
    # security_fixes list counts as content (a security-only cut is legitimate, not
    # a generation miss).
    if not (regen.bullet_count or notes_meta.already_credited or notes_meta.security_fixes) and (
        not regen.had_prs or not regen.included
    ):
        reasons.append("empty release notes")
    if notes_meta.already_credited and not (notes_meta.noted_bullet_count or notes_meta.security_fixes):
        reasons.append("no new release notes (every PR already credited)")
    if regen.duplicate_prs:
        reasons.append("a PR was noted more than once")
    if regen.skipped:
        reasons.append("model declined to note some included PRs")
    if regen.uncertain:
        reasons.append("notes flagged low-confidence")
    if regen.guardrail_included:
        reasons.append("release-safety guardrail overrode AI triage")
    # AI decided inclusion for PRs without release-notes, so a maintainer confirms
    # the include/exclude table before shipping.
    if regen.ai_included or regen.ai_excluded:
        reasons.append("AI triaged PRs without release-notes (confirm include/exclude)")
    if (
        regen.impact_review
        and notes_meta.urgency.strip().upper() in ("LOW", "MODERATE")
    ):
        reasons.append("release impact may require higher urgency or security treatment")
    # A named CVE is factual, not a heuristic signal, so it holds at ANY urgency:
    # a CVE fix shipping as a plain bullet without SECURITY urgency and a
    # hand-authored Security Fixes entry is exactly the mistake to block.
    named_cves = [p for p in regen.impact_review if p.cve]
    if named_cves and not (
        notes_meta.urgency.strip().upper() == _SECURITY_URGENCY and notes_meta.security_fixes
    ):
        reasons.append("a PR names a CVE (needs SECURITY urgency and a Security Fixes entry)")
    sel = notes_meta.advisories
    if sel is not None and sel.fetch_failed:
        reasons.append("security advisories could not be read")
    elif sel is not None and getattr(sel, "unreadable_ids", None):
        reasons.append("some security advisories could not be read")
    # A PR supplied as a --security-fix is now dropped from the generated bullets
    # automatically (see _security_dedup_section), so it is a resolved, informational
    # case, not a hold reason. Only the urgency-with-no-fixes mismatch below holds.
    if notes_meta.urgency.strip().upper() == _SECURITY_URGENCY and not notes_meta.security_fixes:
        reasons.append("SECURITY urgency with no security-fix entries")
    if regen.triage:
        reasons.append("AI triage could not decide some PRs")
    if regen.unresolved:
        reasons.append("commits with no resolvable PR")
    if regen.unresolved_prs:
        reasons.append("commits whose PR could not be fetched")
    if regen.unresolved_backports:
        reasons.append("notes credited to a backport")
    if regen.unresolved_cherry_picks:
        reasons.append("notes with an unconfirmed cherry-pick origin")
    if regen.collided:
        reasons.append("a distinct commit was dropped by a reused PR number")
    if regen.reverted:
        reasons.append("a sweep manifest row is a revert (confirm coverage)")
    return reasons

def _normalize_stage(stage: str) -> str:
    s = stage.strip().lower()
    if s == "ga" or _RC_STAGE_RE.match(s):
        return s
    raise ValueError(f"stage must be 'ga' or 'rcN' (e.g. rc1), got {stage!r}")

def _plan_mode(plan: BranchPlan) -> str:
    """A short human label for the resolved branch plan."""
    return plan.stage

def _print_dry_run(
    plan, version, dest_notes, version_h, notes_meta: "_NotesMeta", *, force_ready: bool = False
) -> None:
    regen = notes_meta.regen
    print(f"\n===== release plan ({version} {plan.stage}) =====")
    print(f"target branch: {plan.target}  base: {plan.base_ref}")
    # Preview the hold decision the real cut would make: a draft PR (held) when any
    # reviewer-facing signal fired and force_ready was not set, else opened ready.
    # Security signals hold even under force_ready (see _should_hold).
    hold_reasons = _hold_reasons(plan, notes_meta)
    security_holds = _security_hold_reasons(hold_reasons)
    if hold_reasons and not force_ready:
        print(f"PR would open: DRAFT (held) - {len(hold_reasons)} item(s): {'; '.join(hold_reasons)}")
    elif security_holds:
        print(f"PR would open: DRAFT (held) - force_ready cannot override "
              f"{len(security_holds)} security item(s): {'; '.join(security_holds)}")
    elif hold_reasons:
        print(f"PR would open: ready (force_ready overrides {len(hold_reasons)} flagged item(s))")
    else:
        print("PR would open: ready (clean cut)")
    # The resolved discovery range is the actual span the notes were computed over;
    # plan.base_ref is the branch-model base, which can differ (e.g. nearest-tag
    # fallback). Print the precise base/head refs + SHAs so an over-broad range
    # shows, falling back to the coarse one-liner only if it could not be captured.
    if notes_meta.notes_range is not None:
        print("notes range:")
        for line in _notes_range_lines(notes_meta.notes_range):
            print(f"  {line}")
    else:
        print(f"notes range: {regen.base_tag}..HEAD")
    if notes_meta.baseline_unanchored:
        print(f"⚠️  baseline unanchored: rc1 of {version} fell back to nearest tag {regen.base_tag!r}")
    if plan.rc_warning:
        print(f"⚠️  rc out of sequence: {plan.rc_warning}")
    if notes_meta.already_credited:
        print(f"already credited on {plan.target} (dropped): {list(notes_meta.already_credited)}")
    if regen.duplicate_prs:
        print(f"⚠️  PR(s) noted more than once (extra bullets dropped): {list(regen.duplicate_prs)}")
    if regen.skipped:
        print(f"⚠️  model declined included PR(s) (no bullet): {list(regen.skipped)}")
    if regen.uncertain:
        flagged = [f"#{n.pr_number} ({n.reason or 'no reason'})" for n in regen.uncertain]
        print(f"⚠️  notes to double-check: {flagged}")
    if not regen.had_prs:
        print("note: no PRs in range (empty dated section)")
    if notes_meta.advisories is not None:
        sel = notes_meta.advisories
        if sel.fetch_failed:
            print(f"⚠️  advisory fetch failed ({sel.fetch_error}); no CVEs auto-added")
        else:
            matched = [f.display_id for f in sel.matched]
            print(f"advisories: {sel.considered} published, matched {matched or 'none'}")
            if sel.unmatched_ids:
                print(f"advisories not matching {version}: {list(sel.unmatched_ids)}")
            if sel.unreadable_ids:
                print(f"⚠️  advisories unreadable (may match {version}): {list(sel.unreadable_ids)}")
    if notes_meta.security_noted_prs:
        print(f"security fix supplied for noted PR(s); dropped from generated bullets "
              f"(kept only under Security Fixes): {list(notes_meta.security_noted_prs)}")
    if notes_meta.urgency.strip().upper() == _SECURITY_URGENCY and not notes_meta.security_fixes:
        print("⚠️  urgency SECURITY but no security-fix entries")
    if regen.ai_included:
        print("AI-triaged into notes (without release-notes; judged user-facing): "
              f"{[p.number for p in regen.ai_included]}")
    if regen.guardrail_included:
        print("⚠️  release-safety guardrail forced into notes after AI exclusion/no verdict: "
              f"{[p.number for p in regen.guardrail_included]}")
    if regen.ai_excluded:
        print("AI-triaged out (without release-notes; judged internal-only): "
              f"{[p.number for p in regen.ai_excluded]}")
    if regen.impact_review:
        print(
            f"⚠️  release-impact signals (confirm {notes_meta.urgency.strip().upper()} "
            "urgency and security treatment): "
            f"{[(p.number, p.reason) for p in regen.impact_review]}"
        )
        named = [(p.number, p.cve) for p in regen.impact_review if p.cve]
        if named:
            print(f"⚠️  PR(s) naming a CVE (needs SECURITY urgency + Security Fixes entry): {named}")
    if regen.label_excluded:
        print("hard-excluded (labelled no-release-notes): "
              f"{[p.number for p in regen.label_excluded]}")
    if regen.triage:
        print(f"triage PRs (AI undecided): {[p.number for p in regen.triage]}")
    if regen.unresolved:
        print(f"⚠️  commits with no resolvable PR: {[c.sha[:12] for c in regen.unresolved]}")
    if regen.unresolved_prs:
        print("⚠️  commits whose PR could not be fetched: "
              f"{[(u.sha[:12], u.number) for u in regen.unresolved_prs]}")
    if regen.unresolved_backports:
        print("⚠️  notes credited to a backport (original PR not recovered): "
              f"{[bp.number for bp in regen.unresolved_backports]}")
    if regen.unresolved_cherry_picks:
        print("⚠️  notes with an unconfirmed cherry-pick origin: "
              f"{[cp.number for cp in regen.unresolved_cherry_picks]}")
    if regen.collided:
        print("⚠️  distinct commits dropped by a reused PR number: "
              f"{[(c.sha[:12], c.number) for c in regen.collided]}")
    if regen.reverted:
        print("⚠️  reverted sweep manifest rows (no bullet generated): "
              f"{[r.number for r in regen.reverted]}")
    print(f"\n===== {NOTES_FILE} (release branch, dry run) =====\n{dest_notes}")
    print(f"\n===== {VERSION_FILE} (dry run) =====\n{version_h}")

def _read(path: str) -> str:
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()

def _release_order(version: str, stage: str) -> tuple[int, int, int, int, int]:
    """Return an ordering key for dev, RC, and GA release states."""
    major, minor, patch = _split_version(version)
    stage_lc = stage.strip().lower()
    if stage_lc == "dev":
        stage_key = (0, 0)
    elif (match := _RC_STAGE_RE.fullmatch(stage_lc)) is not None:
        stage_key = (1, int(match.group(1)))
    elif stage_lc == "ga":
        stage_key = (2, 0)
    else:
        raise ValueError(f"invalid release stage in version.h: {stage!r}")
    return major, minor, patch, *stage_key

def _remote_branch_exists(repo_dir: str, branch: str) -> bool:
    """True if ``refs/heads/<branch>`` exists on ``origin``."""
    out = git_output(repo_dir, "ls-remote", "--heads", "origin", f"refs/heads/{branch}")
    return bool(out.strip())

def _security_fix_prs_in_notes(
    security_fixes: Optional[Sequence[str]], noted: set[int]
) -> list[int]:
    """Return PR numbers credited both as a ``--security-fix`` and a normal bullet.

    Reads each security entry's trailing ``(#N)`` (the same canonical reference the
    notes use) and intersects with *noted* (the PRs this cut renders as normal
    bullets). A match means the change would be listed twice: once under **Security
    Fixes** and once under its generated category. The caller drops the normal
    bullet so the change appears only under Security Fixes, where it is reviewed as
    a factual, hand-authored entry (see :func:`cut`). Sorted for a deterministic
    dropped-list in the log and PR body.
    """
    if not security_fixes:
        return []
    found: set[int] = set()
    for entry in security_fixes:
        m = _TRAILING_PR_RE.search(entry)
        if m and int(m.group(1)) in noted:
            found.add(int(m.group(1)))
    return sorted(found)

def _security_hold_reasons(reasons: Sequence[str]) -> list[str]:
    """The subset of *reasons* that ``force_ready`` must not override."""
    return [r for r in reasons if r in _SECURITY_HOLD_REASONS]

def _should_hold(reasons: Sequence[str], force_ready: bool) -> bool:
    """Whether the release PR opens as a draft.

    Any reason holds by default; ``force_ready`` overrides all of them except
    security signals, which only resolving the signal (and re-cutting) clears.
    """
    if not reasons:
        return False
    if not force_ready:
        return True
    return bool(_security_hold_reasons(reasons))

def _write(path: str, text: str) -> None:
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)

def stage_release_name(version: str, stage_lc: str) -> str:
    """``9.1.0`` at ga, else ``9.1.0-rcN``."""
    return version if stage_lc == "ga" else f"{version}-{stage_lc}"

def _existing_dated_sections(text: str) -> str:
    """Return text from the first ``Valkey M.m.p`` heading onward."""
    match = _DATED_SECTION_RE.search(text)
    if not match:
        return ""
    return text[match.start():].strip()

def _format_date(date: str) -> str:
    """Render *date* as ``"Tue 02 June 2026"``. Passes non-ISO strings unchanged."""
    try:
        parsed = datetime.date.fromisoformat(date.strip())
    except ValueError:
        return date.strip()
    return parsed.strftime("%a %d %B %Y")

def _normalize_stage(stage: str) -> str:
    s = stage.strip().lower()
    if s == "ga":
        return "ga"
    if _RC_STAGE_RE.match(s):
        return s
    raise ValueError("release stage must be 'ga' or 'rcN' (e.g. rc1), got {!r}".format(stage))

def _stage_heading(version: str, stage: str) -> str:
    if stage == "ga":
        # Valkey uses "GA" for the initial M.m.0 release, while patch release
        # headings are simply "Valkey M.m.p".
        _major, _minor, patch = parse_version(version)
        return "Valkey {}{}".format(version, " GA" if patch == 0 else "")
    return "Valkey {}-{}".format(version, stage)

def _strip_bullet(line: str) -> str:
    """Return *line* trimmed of a leading ``* ``/``- `` bullet marker."""
    s = line.strip()
    if s.startswith(("* ", "- ")):
        return s[2:].strip()
    return s

def _urgency_sentence(version: str, stage: str, urgency: str) -> str:
    major, minor, patch = parse_version(version)
    if urgency == "SECURITY" or (stage == "ga" and patch > 0):
        return "Upgrade urgency {}: {}".format(
            urgency, _PATCH_URGENCY_SENTENCES[urgency]
        )
    if stage == "ga":
        which = ordinal(patch + 1)  # M.m.0 is the first stable release of M.m
        return (
            "Upgrade urgency {}: This is the {} stable release of Valkey {}.{}.".format(
                urgency, which, major, minor
            )
        )
    rc_num = int(_RC_STAGE_RE.match(stage).group(1))  # type: ignore[union-attr]
    which = ordinal(rc_num)
    return (
        "Upgrade urgency {}: This is the {} release candidate of Valkey {}.".format(
            urgency, which, version
        )
    )

def ordinal(n: int) -> str:
    """Return a small ordinal word ("first", "second", ...) or "Nth" fallback."""
    if 0 <= n < len(_ORDINALS):
        return _ORDINALS[n]
    return "{}th".format(n)

def parse_version(version: str) -> "tuple[int, int, int]":
    """Split ``"M.m.p"`` into integer ``(major, minor, patch)``.

    Each component must be 0-255 (one byte of VALKEY_VERSION_NUM).
    """
    match = _VERSION_RE.match(version.strip())
    if not match:
        raise ValueError(
            "version must be in the form MAJOR.MINOR.PATCH (e.g. 9.1.0), got {!r}".format(version)
        )
    parts = tuple(int(p) for p in match.groups())
    for component, value in zip(("major", "minor", "patch"), parts):
        if not 0 <= value <= 255:
            raise ValueError(
                "{} version {} is out of range 0-255".format(component, value)
            )
    return parts  # type: ignore[return-value]

def render_contributors_footer(contributors: Sequence[str]) -> str:
    """Render the cumulative footer, deduped by login/display-name identity.

    Returns ``""`` when the list is empty.
    """
    records: List[tuple[str, str, str]] = []
    for entry in contributors:
        rendered = _strip_bullet(entry)
        if not rendered:
            continue
        handle_match = re.search(r"\s+@([A-Za-z0-9-]+)$", rendered)
        handle = handle_match.group(1).casefold() if handle_match else ""
        display = (
            rendered[:handle_match.start()].strip()
            if handle_match
            else rendered
        )
        display_key = display.casefold()
        matches = [
            index
            for index, (known_name, known_handle, _known_rendered) in enumerate(records)
            if (handle and known_handle == handle)
            or (display_key and known_name == display_key)
        ]
        if not matches:
            records.append((display_key, handle, rendered))
            continue

        # A later handled entry is the freshest API identity and replaces stale
        # profile names or name-only fallbacks carried from an older footer.
        winner = (display_key, handle, rendered)
        if not handle:
            winner = next(
                (records[index] for index in matches if records[index][1]),
                records[matches[0]],
            )
        for index in reversed(matches):
            del records[index]
        records.append(winner)

    if not records:
        return ""
    unique = sorted(
        (rendered for _name, _handle, rendered in records),
        key=lambda entry: entry.rsplit(" @", 1)[0].casefold(),
    )
    out = ["### Contributors"]
    out.extend("* {}".format(name) for name in unique)
    return "\n".join(out)

def render_header(major: int, minor: int) -> str:
    """Render the file title and urgency legend for a ``M.m`` release line."""
    title = "Valkey {}.{} release notes".format(major, minor)
    underline = "=" * len(title)
    return "{}\n{}\n\n{}".format(title, underline, URGENCY_LEGEND)

def unrecognized_categories(notes: "Dict[str, List[str]]") -> List[str]:
    """Return category names in *notes* that are not in CATEGORIES.

    Reserved sections are excluded. Empty categories are ignored.
    """
    known = set(CATEGORIES) | set(RESERVED_SECTIONS)
    return [
        category
        for category, bullets in notes.items()
        if bullets and category not in known
    ]

def _one_line(text: str) -> str:
    """Collapse *text* to a single physical line."""
    return " ".join(text.splitlines()).strip()

def _reserved_sections() -> set[str]:
    """Case-folded reserved section names that group_bullets refuses to render."""
    return {r.casefold() for r in _release_format.RESERVED_SECTIONS}

def group_bullets(
    bullets: Sequence[CategorizedBullet],
) -> dict[str, list[str]]:
    """Group bullets into ``{category: [rendered line, ...]}``.

    Non-canonical categories are coerced into the catch-all. Bullets under
    reserved sections (Security Fixes, Contributors) are refused and logged.
    Output keys are in CATEGORIES order.
    """
    reserved = _reserved_sections()
    canonical = set(_release_format.CATEGORIES)
    # Fallback if CATCH_ALL_CATEGORY were edited off-list.
    catch_all = _release_format.CATCH_ALL_CATEGORY
    if catch_all not in canonical:
        catch_all = _release_format.CATEGORIES[-1]
    grouped: dict[str, list[str]] = {}
    for bullet in bullets:
        category = _one_line(bullet.category)
        if category.casefold() in reserved:
            logger.warning(
                "Refusing PR #%s under reserved section %r (auto-generated at release)",
                bullet.pr_number, category,
            )
            continue
        if category not in canonical:
            logger.warning(
                "PR #%s assigned non-canonical category %r; placing under %r",
                bullet.pr_number, category, catch_all,
            )
            category = catch_all
        grouped.setdefault(category, []).append(format_bullet(bullet))

    # Emit in canonical order.
    ordered: dict[str, list[str]] = {}
    for name in _release_format.CATEGORIES:
        if grouped.get(name):
            ordered[name] = grouped[name]
    return ordered

def is_reserved_category(category: str) -> bool:
    """Whether *category* names a reserved section that group_bullets will drop."""
    return _one_line(category).casefold() in _reserved_sections()

def _cve_id(advisory: Any) -> str:
    """Return the advisory's CVE id, falling back to the identifiers list."""
    direct = _string_attr(advisory, "cve_id")
    if direct:
        return direct
    try:
        identifiers = advisory.identifiers
    except Exception:  # noqa: BLE001
        identifiers = None
    if not isinstance(identifiers, list):
        return ""
    for ident in identifiers:
        if isinstance(ident, dict) and ident.get("type") == "CVE" and ident.get("value"):
            return str(ident["value"])
    return ""

def _fixed_version_tokens(text: str) -> set[str]:
    """Extract discrete fixed-version tokens from *text*, dropping range bounds."""
    tokens: set[str] = set()
    for m in _VERSION_TOKEN_RE.finditer(text):
        if _RANGE_BOUND_RE.search(text[: m.start()]):
            continue
        tokens.add(m.group(1))
    return tokens

def _render_summary(advisory: Any) -> str:
    """Return the advisory summary as a single line.

    Falls back to the first non-blank line of description, then a placeholder.
    """
    summary = _string_attr(advisory, "summary")
    if summary:
        return " ".join(summary.splitlines()).strip() or "(no summary provided)"
    description = _string_attr(advisory, "description")
    for line in description.splitlines():
        if line.strip():
            return line.strip()
    return "(no summary provided)"

def collect_advisory_fixes(repo: Any, version: str) -> AdvisorySelection:
    """Fetch published advisories and select those fixed by *version*.

    Never raises; API failures are captured in the returned selection.
    """
    try:
        advisories = retry_github_call(
            lambda: list(repo.get_repository_advisories()),
            retries=3,
            description="list repository advisories",
        )
    except Exception as exc:  # noqa: BLE001 - degrade, never abort the cut on a fetch failure
        logger.warning("Could not fetch repository advisories: %s", exc)
        return AdvisorySelection(fetch_failed=True, fetch_error=str(exc))

    matched: list[AdvisoryFix] = []
    unmatched_ids: list[str] = []
    unreadable_ids: list[str] = []
    considered = 0
    for advisory in advisories:
        if _string_attr(advisory, "state") != "published":
            continue
        try:
            withdrawn = advisory.withdrawn_at
        except Exception:  # noqa: BLE001
            withdrawn = None
        if withdrawn is not None:
            continue
        considered += 1
        fix = _extract_fix(advisory, version)
        if isinstance(fix, AdvisoryFix):
            matched.append(fix)
        elif fix is _UNREADABLE:
            unreadable_ids.append(_cve_id(advisory) or _string_attr(advisory, "ghsa_id") or "(unknown advisory)")
        else:
            ident = _cve_id(advisory) or _string_attr(advisory, "ghsa_id")
            if ident:
                unmatched_ids.append(ident)

    # Deterministic order and dedup.
    matched.sort(key=lambda f: f.display_id)
    seen: set[str] = set()
    deduped: list[AdvisoryFix] = []
    for fix in matched:
        if fix.display_id in seen:
            continue
        seen.add(fix.display_id)
        deduped.append(fix)

    logger.info(
        "Advisories: %d published, %d fixed by %s, %d other, %d unreadable",
        considered, len(deduped), version, len(unmatched_ids), len(unreadable_ids),
    )
    return AdvisorySelection(
        matched=tuple(deduped),
        considered=considered,
        unmatched_ids=tuple(sorted(unmatched_ids)),
        unreadable_ids=tuple(sorted(unreadable_ids)),
    )

def merge_with_manual(
    matched: Sequence[AdvisoryFix], manual_fixes: Optional[Sequence[str]]
) -> Optional[list[str]]:
    """Merge advisory-derived fixes with hand-supplied --security-fix entries.

    Manual entries win on CVE/GHSA collision. Returns None when nothing remains.
    """
    manual = list(manual_fixes or [])
    manual_cves = {
        cve.upper()
        for entry in manual
        for cve in _CVE_ID_RE.findall(entry)
    }
    manual_ghsas = {
        ghsa.upper()
        for entry in manual
        for ghsa in _GHSA_ID_RE.findall(entry)
    }
    merged = list(manual)
    for fix in matched:
        cve_collision = bool(fix.cve_id) and fix.cve_id.upper() in manual_cves
        ghsa_collision = bool(fix.ghsa_id) and fix.ghsa_id.upper() in manual_ghsas
        if cve_collision or ghsa_collision:
            logger.info("Advisory %s superseded by a manual --security-fix", fix.display_id)
            continue
        merged.append(render_bullet(fix))
    return merged or None

def patched_version_tokens(raw_vulnerabilities: Sequence[Any]) -> set[str]:
    """Collect every discrete fixed M.m.p token from an advisory's raw vulnerabilities.

    Reads both patched_versions and first_patched_version from raw JSON dicts.
    Range bounds are dropped.
    """
    tokens: set[str] = set()
    if not isinstance(raw_vulnerabilities, list):
        return tokens
    for vuln in raw_vulnerabilities:
        if not isinstance(vuln, dict):
            continue
        patched = vuln.get("patched_versions")
        if isinstance(patched, str):
            tokens.update(_fixed_version_tokens(patched))
        fpv = vuln.get("first_patched_version")
        if isinstance(fpv, dict):
            identifier = fpv.get("identifier")
            if isinstance(identifier, str):
                tokens.update(_fixed_version_tokens(identifier))
        elif isinstance(fpv, str):
            tokens.update(_fixed_version_tokens(fpv))
    return tokens

def _is_test_or_ci_only(pr: MergedPR) -> bool:
    """True when every changed file of *pr* is under tests/ or .github/.

    False when the file list is empty (lookup failed): unknown must not exempt.
    """
    if not pr.changed_files:
        return False
    return all(
        path.startswith(_NON_SHIPPED_PATH_PREFIXES) for path in pr.changed_files
    )

def _validate_stage(stage: str) -> str:
    stage = stage.strip().lower()
    if not _STAGE_RE.match(stage):
        raise ValueError(
            "release stage must be 'dev', 'ga', or 'rcN' (e.g. rc1), got {!r}".format(stage)
        )
    return stage

def version_num(version: str) -> str:
    """Return the ``0x00MMmmpp`` hex literal for a ``"M.m.p"`` version string."""
    major, minor, patch = parse_version(version)
    return "0x00{:02x}{:02x}{:02x}".format(major, minor, patch)

def render(self, marker: str, occurrences: int) -> IssueContent:
    """The ``render`` callback: title/body/comment/labels for the issue."""
    return IssueContent(
        title=title_for(self._failure),
        body=_build_body(self._failure, marker, occurrences=occurrences),
        comment=_build_comment(
            self._failure,
            newly_failing=self._newly_failing,
            new_error=self._new_error,
        ),
        labels=(LABEL_NAME,),
    )

def _extract_environments_from_body(body: str) -> list[str]:
    """Extract existing environment names from an issue body."""
    env_match = re.search(r"\*\*Environments:\*\*\s*(.+)", body)
    if not env_match:
        return []
    return re.findall(r"`([^`]+)`", env_match.group(1))

def _extract_error_from_body(body: str) -> str:
    """Extract the error trace recorded under the Error stack trace header.

    Returns ``""`` when the body has no such section (e.g. issues created
    before this section existed), which the caller treats as "unknown" rather
    than "unchanged".
    """
    match = _ERROR_BLOCK_RE.search(body)
    if not match:
        return ""
    return match.group(1).strip()

def _update_environments_in_body(body: str, all_envs: list[str]) -> str:
    """Replace the Environments line in the issue body with an updated list."""
    new_env_line = f"**Environments:** {', '.join(f'`{e}`' for e in all_envs)}"
    return re.sub(r"\*\*Environments:\*\*\s*.+", new_env_line, body)

def _one_line(text: str) -> str:
    """Collapse text to a single line safe inside a markdown code span.

    A damage entry carries a zip member name and an exception message, either of
    which can hold a newline or a backtick that would break the list item.
    """
    return " ".join(text.split()).replace("`", "'")

@dataclass
class JobReference:
    """A reference to a specific CI job where a test failed."""

    job: str
    suite: str
    url: str = ""

@dataclass
class UniqueFailure:
    """A deduplicated test failure that may appear across multiple jobs."""

    test_name: str
    test_file: str
    error: str = ""
    jobs: list[JobReference] = field(default_factory=list)

    @property
    def display_name(self) -> str:
        return f"{self.test_name} in {self.test_file}"

@property
def display_name(self) -> str:
    return f"{self.test_name} in {self.test_file}"
